void main() {
	float a = sin(TIME * vitesse * 2.0) * radians(angle);
	float aspect = RENDERSIZE.x / RENDERSIZE.y;
	// recadrage juste suffisant pour que les coins restent couverts à l'angle maximal
	float m = radians(angle);
	float zoom = cos(m) + sin(m) * max(aspect, 1.0 / aspect);
	vec2 p = isf_FragNormCoord - 0.5;
	p.x *= aspect;
	float c = cos(a); float s = sin(a);
	p = vec2(c * p.x - s * p.y, s * p.x + c * p.y) / zoom;
	p.x /= aspect;
	gl_FragColor = IMG_NORM_PIXEL(inputImage, p + 0.5);
}

float hash(float n) { return fract(sin(n) * 43758.5453123); }

void main() {
	float phase = mod(TIME, intervalle);
	float env = exp(-phase * amorti); // 1 à l'impact, puis décroît
	float f = floor(TIME * 30.0);
	vec2 off = (vec2(hash(f), hash(f + 91.0)) - 0.5) * 0.14 * intensite * env;
	float zoom = 1.0 + (0.04 + 0.10 * env) * intensite;
	vec2 uv = (isf_FragNormCoord - 0.5) / zoom + 0.5 + off;
	gl_FragColor = IMG_NORM_PIXEL(inputImage, uv);
}

float hash(float n) { return fract(sin(n) * 43758.5453123); }
float noise(float x) { float i = floor(x); float f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(hash(i), hash(i + 1.0), f); }

void main() {
	float t = TIME * vitesse * 2.0;
	// deux octaves : un balancement lent et un tremblement fin par-dessus
	vec2 off = (vec2(noise(t), noise(t + 37.0)) - 0.5) * 0.06 + (vec2(noise(t * 3.1 + 11.0), noise(t * 3.1 + 71.0)) - 0.5) * 0.02;
	off *= intensite;
	float a = (noise(t * 0.8 + 5.0) - 0.5) * 0.10 * rotation * intensite;
	float zoom = 1.0 + 0.12 * intensite; // léger recadrage : les bords ne rentrent jamais dans l'image
	float aspect = RENDERSIZE.x / RENDERSIZE.y;
	vec2 p = isf_FragNormCoord - 0.5;
	p.x *= aspect;
	float c = cos(a); float s = sin(a);
	p = vec2(c * p.x - s * p.y, s * p.x + c * p.y) / zoom;
	p.x /= aspect;
	gl_FragColor = IMG_NORM_PIXEL(inputImage, p + 0.5 + off);
}

float hash(float n) { return fract(sin(n) * 43758.5453123); }

void main() {
	float f = floor(TIME * frequence); // une nouvelle position à chaque pas, sans transition
	vec2 off = (vec2(hash(f), hash(f + 91.0)) - 0.5) * 0.10 * intensite;
	float zoom = 1.0 + 0.12 * intensite;
	vec2 uv = (isf_FragNormCoord - 0.5) / zoom + 0.5 + off;
	vec2 split = off * couleurs * 0.6;
	float r = IMG_NORM_PIXEL(inputImage, uv + split).r;
	vec4 g = IMG_NORM_PIXEL(inputImage, uv);
	float b = IMG_NORM_PIXEL(inputImage, uv - split).b;
	gl_FragColor = vec4(r, g.g, b, g.a);
}

void main() {
	float k = EZ_PROGRESS * EZ_PROGRESS * (3.0 - 2.0 * EZ_PROGRESS);
	float zoom = 1.0 + quantite * (1.0 - k);
	gl_FragColor = IMG_NORM_PIXEL(inputImage, (isf_FragNormCoord - centre) / zoom + centre);
}

void main() {
	float k = EZ_PROGRESS * EZ_PROGRESS * (3.0 - 2.0 * EZ_PROGRESS); // départ et arrivée en douceur
	float zoom = 1.0 + quantite * k;
	gl_FragColor = IMG_NORM_PIXEL(inputImage, (isf_FragNormCoord - centre) / zoom + centre);
}

void main() {
	float k = clamp(TIME / duree, 0.0, 1.0);
	float rest = pow(1.0 - k, 3.0); // 1 au début du clip, 0 une fois posé
	float zoom = 1.0 + quantite * rest;
	vec2 dir = isf_FragNormCoord - 0.5;
	// flou radial : plusieurs échantillons le long du mouvement de zoom
	float spread = flou * rest * 0.25;
	vec4 sum = vec4(0.0);
	for (int i = 0; i < 12; i++) {
		float s = 1.0 - spread * float(i) / 11.0;
		sum += IMG_NORM_PIXEL(inputImage, dir * s / zoom + 0.5);
	}
	gl_FragColor = sum / 12.0;
}

void main() {
	float phase = fract(TIME * tempo / 60.0);
	float zoom = 1.0 + quantite * exp(-phase * amorti);
	gl_FragColor = IMG_NORM_PIXEL(inputImage, (isf_FragNormCoord - 0.5) / zoom + 0.5);
}

float character(float n, vec2 p) // some compilers have the word "char" reserved
{
	p = floor(p*vec2(4.0, -4.0) + 2.5);
	if (clamp(p.x, 0.0, 4.0) == p.x && clamp(p.y, 0.0, 4.0) == p.y)
	{
		if (int(mod(n/exp2(p.x + 5.0*p.y), 2.0)) == 1) return 1.0;
	}	
	return 0.0;
}



void main()	{
	float _size = size*36.0+8.0;
	vec2 uv = gl_FragCoord.xy;
	vec4 inputColor = IMG_NORM_PIXEL(inputImage, (floor(uv/_size)*_size/RENDERSIZE.xy));
	vec3 col = inputColor.rgb;
	float gray = (col.r + col.g + col.b)/3.0;
	gray = pow(gray, gamma);
	col = mix(tintColor.rgb, col.rgb, 1.0-tint);
	
	float n =  65536.0;             // .
	if (gray > 0.2) n = 65600.0;    // :
	if (gray > 0.3) n = 332772.0;   // *
	if (gray > 0.4) n = 15255086.0; // o 
	if (gray > 0.5) n = 23385164.0; // &
	if (gray > 0.6) n = 15252014.0; // 8
	if (gray > 0.7) n = 13199452.0; // @
	if (gray > 0.8) n = 11512810.0; // #
		
	vec2 p = mod(uv/(_size/2.0), 2.0) - vec2(1.0);
	col = col*character(n, p);
	float alpha = mix(tintColor.a * inputColor.a, inputColor.a, 1.0-tint);
	if (alphaMode)	{
		alpha = (col.r + col.g + col.b)/3.0;
		alpha = (alpha > 0.01) ? tintColor.a : alpha;
	}
	
	gl_FragColor = vec4(col,alpha);

}

vec3 rgb2hsv(vec3 c)	{
	vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
	//vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
	//vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
	vec4 p = c.g < c.b ? vec4(c.bg, K.wz) : vec4(c.gb, K.xy);
	vec4 q = c.r < p.x ? vec4(p.xyw, c.r) : vec4(c.r, p.yzx);
	
	float d = q.x - min(q.w, q.y);
	float e = 1.0e-10;
	return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

vec3 hsv2rgb(vec3 c)	{
	vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
	vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
	return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

float gray(vec4 c)	{
	return (c.r + c.g + c.b) * c.a / 3.0;	
}

void main()
{
	if (PASSINDEX == 0)	{
		vec4 		inputColor = IMG_NORM_PIXEL(inputImage, isf_FragNormCoord);
		gl_FragColor = inputColor;
	}
	else if (PASSINDEX == 1)	{
		vec4 		inputColor = IMG_NORM_PIXEL(bufferPassA, isf_FragNormCoord);
		vec4 		oldColor = IMG_NORM_PIXEL(autoColorBuffer, vec2(0.5,0.5));
		gl_FragColor = mix(inputColor, oldColor, 0.8);
	}
	else if (PASSINDEX == 2)	{
		vec4 		inputColor = IMG_THIS_PIXEL(inputImage);
		vec4		inColor = baseColor;
		float		index = floor(gray(inputColor) * float(colorCount));	
		//float		index = floor(isf_FragNormCoord.x * float(colorCount));
		float		variation = 0.3236;	//	1/5 the golden ratio
		int			colorMode = colorModeOverride;

		if (sampleMode == 0)	{
			inColor = baseColor;
			inColor.rgb = rgb2hsv(inColor.rgb);
		}
		else if (sampleMode == 1)	{
			inColor = IMG_NORM_PIXEL(inputImage, pixelFollowLocation);
			inColor.rgb = rgb2hsv(inColor.rgb);
		}
		else if (sampleMode == 2)	{
			inColor = IMG_NORM_PIXEL(autoColorBuffer, vec2(0.5,0.5));
			inColor.rgb = rgb2hsv(inColor.rgb);
			if (inColor.b < 0.1)	{
				inColor = inColor * 1.5;	
			}
		}
	
		vec4		outColor = inColor;
	
		//	Basic complimentary  saturation and brightness variations on two fixed 180 degree opposite hues
		if (colorMode == 0)	{
			if (mod(index, 2.0) >= 1.0)	{
				outColor.r = outColor.r + 0.5;
				outColor.r = outColor.r - floor(outColor.r);
			}
		
			outColor.g = outColor.g - variation * floor(index / 2.0);
		
			if (outColor.g < 0.1)	{
				outColor.g = outColor.g + variation * floor(index / 2.0);
				outColor.g = outColor.g - floor(outColor.g);
			}
		
			outColor.b = outColor.b - variation * floor(index / 4.0);
			if (outColor.b < 0.2)	{
				outColor.b = outColor.b + variation * floor(index / 4.0);
				outColor.b = outColor.b - floor(outColor.b);
			}
		}
		//	Split complimentary  saturation and brightness variations on a 3 fixed 120 degree hues
		else if (colorMode == 1)	{
			float divisor = 3.0;
			float ratio = 0.45;
			if (mod(index, 3.0) >= 2.0)	{
				outColor.r = outColor.r - ratio;
			}
			else if (mod(index, 3.0) >= 1.0)	{
				outColor.r = outColor.r + ratio;
			}
		
			//outColor.g = outColor.g + variation * floor(index / divisor);
		
			if (mod(index, 5.0) >= 3.0)	{
				outColor.g = outColor.g - variation;
				outColor.g = outColor.g - floor(outColor.g);
			}
			outColor.b = outColor.b - variation * floor(index / (divisor));
			if (outColor.b < 0.1)	{
				outColor.b = outColor.b + variation * floor(index / (divisor));
				outColor.b = outColor.b - floor(outColor.b);
			}
		}
		//	Compound complimentary  a combination of shades, complimentary and analogous colors with slight shifts
		else if (colorMode == 2)	{
			if (mod(index, 3.0) >= 2.0)	{
				outColor.r = outColor.r + 0.5;
				outColor.r = outColor.r + variation * index * 1.0 / float(colorCount - 1) / 4.0;
			}
			else	{
				outColor.r = outColor.r + variation * index * 1.0 / float(colorCount - 1);
			}
			outColor.r = outColor.r - floor(outColor.r);
		
		
			if (mod(index, 2.0) >= 1.0)	{
				outColor.g = outColor.g + index * variation / 2.0;
			}
			else if (mod(index, 3.0) >= 2.0)	{
				outColor.g = outColor.g - variation / 2.0;
			}
			else	{
				outColor.g = outColor.g - index * variation / float(colorCount - 1);
			}
			if (outColor.g > 1.0)	{
				outColor.g = outColor.g - floor(outColor.g);
			}
		}
		//	Spectrum  hue shifts based on number of colors with minor saturation shifts
		else if (colorMode == 3)	{
			outColor.r = outColor.r + index * 1.0 / float(colorCount);
			if (mod(index, 3.0) >= 2.0)	{
				outColor.g = outColor.g - variation / 2.0;
				outColor.g = outColor.g - floor(outColor.g);
			}
			else if (mod(index, 4.0) >= 3.0)	{
				outColor.g = outColor.g + variation / 2.0;
				//outColor.g = outColor.g - floor(outColor.g);
			}
		}
		//	Shades  saturation and brightness variations on a single fixed hue
		else if (colorMode == 4)	{
			if (mod(index, 2.0) >= 1.0)	{
				outColor.b = outColor.b - (index * variation) / float(colorCount-1);
			}
			else	{
				outColor.b = outColor.b + (index * variation) / float(colorCount-1);
				outColor.b = outColor.b - floor(outColor.b);
			}
			if (outColor.b < 0.075)	{
				outColor.b = 1.0 - outColor.b * variation;
			}
		
			if (mod(index, 3.0) >= 2.0)	{
				outColor.g = outColor.g - (index * variation) / 2.0;
			}
			else if (mod(index, 4.0) >= 3.0)	{
				outColor.g = outColor.g + (index * variation) / 2.0;
			}
		
			if ((outColor.g > 1.0) || (outColor.g < 0.05))	{
				outColor.g = outColor.g - floor(outColor.g);
			}
		}
		//	Analogous  small hue and saturation shifts 
		else if (colorMode == 5)	{

			outColor.r = outColor.r + variation * index * 1.0 / float(colorCount - 1); 		

			if (mod(index, 3.0) >= 1.0)	{
				outColor.g = outColor.g - variation / 2.0;
				if (outColor.g < 0.0)	{
					outColor.g = outColor.g + variation / 2.0;
				}
				if (outColor.g > 1.0)	{
					outColor.g = outColor.g - floor(outColor.g);
				}
			}
		}
		//	Compound Analogous  similar to analogous but with negative hue shifts
		else if (colorMode == 6)	{
			if (mod(index, 3.0) >= 1.0)	{
				outColor.r = outColor.r + variation * index * 1.0 / float(colorCount - 1);
			}
			else	{
				outColor.r = outColor.r - variation * index * 0.5 / float(colorCount - 1);	
			}
			if (mod(index, 3.0) >= 1.0)	{
				outColor.g = outColor.g - variation / 2.0;
				if (outColor.g < 0.0)	{
					outColor.g = outColor.g + variation;
				}
				if (outColor.g > 1.0)	{
					outColor.g = outColor.g - floor(outColor.g);
				}
			}
			if (mod(index, 4.0) >= 2.0)	{
				if (outColor.b < variation)	{
					outColor.b = outColor.b + variation;
				}				
			}
		}
	
		gl_FragColor = vec4(hsv2rgb(outColor.rgb), inColor.a);
	}
}

#if __VERSION__ <= 120
varying vec2 left_coord;
varying vec2 right_coord;
varying vec2 above_coord;
varying vec2 below_coord;

varying vec2 lefta_coord;
varying vec2 righta_coord;
varying vec2 leftb_coord;
varying vec2 rightb_coord;
#else
in vec2 left_coord;
in vec2 right_coord;
in vec2 above_coord;
in vec2 below_coord;

in vec2 lefta_coord;
in vec2 righta_coord;
in vec2 leftb_coord;
in vec2 rightb_coord;
#endif

float gray(vec4 n)
{
	return (n.r + n.g + n.b)/3.0;
}

//	packed as min, mid, max
vec3 minmaxmean(vec4 n, vec3 old)
{
	float val = gray(n);
	vec3 returnMe = old;
	if (val < returnMe.x)	{
		returnMe.x = val;
	}
	if (val > returnMe.z)	{
		returnMe.z = val;
	}
	returnMe.y = returnMe.y + val / 9.0;
	return returnMe;
}

vec3 minmaxcompare(vec4 n, vec3 old)	{
	vec3 returnMe = old;
	if (n.r < returnMe.x)	{
		returnMe.x = n.r;
	}
	if (n.g > returnMe.z)	{
		returnMe.z = n.g;
	}
	returnMe.y = returnMe.y + n.b / 9.0;
	return returnMe;
}


void main()
{
	vec3 vals = vec3(1.0,0.0,0.0);
	
	//	on this first pass we find the local mins, mid, and max for each pixel
	if (PASSINDEX == 0)	{
		vec4 min_color = IMG_THIS_PIXEL(inputImage);
		vec4 min_colorL = IMG_NORM_PIXEL(inputImage, left_coord);
		vec4 min_colorR = IMG_NORM_PIXEL(inputImage, right_coord);
		vec4 min_colorA = IMG_NORM_PIXEL(inputImage, above_coord);
		vec4 min_colorB = IMG_NORM_PIXEL(inputImage, below_coord);
	
		vec4 min_colorLA = IMG_NORM_PIXEL(inputImage, lefta_coord);
		vec4 min_colorRA = IMG_NORM_PIXEL(inputImage, righta_coord);
		vec4 min_colorLB = IMG_NORM_PIXEL(inputImage, leftb_coord);
		vec4 min_colorRB = IMG_NORM_PIXEL(inputImage, rightb_coord);
	
		vals = minmaxmean(min_color,vals);

		vals = minmaxmean(min_colorL,vals);
		vals = minmaxmean(min_colorR,vals);
		vals = minmaxmean(min_colorA,vals);
		vals = minmaxmean(min_colorB,vals);

		vals = minmaxmean(min_colorLA,vals);
		vals = minmaxmean(min_colorRA,vals);
		vals = minmaxmean(min_colorLB,vals);
		vals = minmaxmean(min_colorRB,vals);
		gl_FragColor = vec4(vals.x,vals.y,vals.z,min_color.a);
	}
	//	second pass: read from "bufferPassA", write to "bufferPassB"
	else if (PASSINDEX == 1)	{
		vec4 min_color = IMG_THIS_PIXEL(bufferPassA);
		vec4 min_colorL = IMG_NORM_PIXEL(bufferPassA, left_coord);
		vec4 min_colorR = IMG_NORM_PIXEL(bufferPassA, right_coord);
		vec4 min_colorA = IMG_NORM_PIXEL(bufferPassA, above_coord);
		vec4 min_colorB = IMG_NORM_PIXEL(bufferPassA, below_coord);
	
		vec4 min_colorLA = IMG_NORM_PIXEL(bufferPassA, lefta_coord);
		vec4 min_colorRA = IMG_NORM_PIXEL(bufferPassA, righta_coord);
		vec4 min_colorLB = IMG_NORM_PIXEL(bufferPassA, leftb_coord);
		vec4 min_colorRB = IMG_NORM_PIXEL(bufferPassA, rightb_coord);
	
		vals = minmaxcompare(min_color,vals);

		vals = minmaxcompare(min_colorL,vals);
		vals = minmaxcompare(min_colorR,vals);
		vals = minmaxcompare(min_colorA,vals);
		vals = minmaxcompare(min_colorB,vals);

		vals = minmaxcompare(min_colorLA,vals);
		vals = minmaxcompare(min_colorRA,vals);
		vals = minmaxcompare(min_colorLB,vals);
		vals = minmaxcompare(min_colorRB,vals);
		gl_FragColor = vec4(vals.x,vals.y,vals.z,min_color.a);
	}
	//	read from "bufferPassB", write to "bufferPassC"
	else if (PASSINDEX == 2)	{
		vec4 min_color = IMG_THIS_PIXEL(bufferPassB);
		vec4 min_colorL = IMG_NORM_PIXEL(bufferPassB, left_coord);
		vec4 min_colorR = IMG_NORM_PIXEL(bufferPassB, right_coord);
		vec4 min_colorA = IMG_NORM_PIXEL(bufferPassB, above_coord);
		vec4 min_colorB = IMG_NORM_PIXEL(bufferPassB, below_coord);
	
		vec4 min_colorLA = IMG_NORM_PIXEL(bufferPassB, lefta_coord);
		vec4 min_colorRA = IMG_NORM_PIXEL(bufferPassB, righta_coord);
		vec4 min_colorLB = IMG_NORM_PIXEL(bufferPassB, leftb_coord);
		vec4 min_colorRB = IMG_NORM_PIXEL(bufferPassB, rightb_coord);

		vals = minmaxcompare(min_color,vals);

		vals = minmaxcompare(min_colorL,vals);
		vals = minmaxcompare(min_colorR,vals);
		vals = minmaxcompare(min_colorA,vals);
		vals = minmaxcompare(min_colorB,vals);

		vals = minmaxcompare(min_colorLA,vals);
		vals = minmaxcompare(min_colorRA,vals);
		vals = minmaxcompare(min_colorLB,vals);
		vals = minmaxcompare(min_colorRB,vals);
		gl_FragColor = vec4(vals.x,vals.y,vals.z,min_color.a);
	}
	//	read from "bufferPassC", write to "bufferPassD"
	else if (PASSINDEX == 3)	{
		vec4 min_color = IMG_THIS_PIXEL(bufferPassC);
		vec4 min_colorL = IMG_NORM_PIXEL(bufferPassC, left_coord);
		vec4 min_colorR = IMG_NORM_PIXEL(bufferPassC, right_coord);
		vec4 min_colorA = IMG_NORM_PIXEL(bufferPassC, above_coord);
		vec4 min_colorB = IMG_NORM_PIXEL(bufferPassC, below_coord);
	
		vec4 min_colorLA = IMG_NORM_PIXEL(bufferPassC, lefta_coord);
		vec4 min_colorRA = IMG_NORM_PIXEL(bufferPassC, righta_coord);
		vec4 min_colorLB = IMG_NORM_PIXEL(bufferPassC, leftb_coord);
		vec4 min_colorRB = IMG_NORM_PIXEL(bufferPassC, rightb_coord);
	
		vals = minmaxcompare(min_color,vals);

		vals = minmaxcompare(min_colorL,vals);
		vals = minmaxcompare(min_colorR,vals);
		vals = minmaxcompare(min_colorA,vals);
		vals = minmaxcompare(min_colorB,vals);

		vals = minmaxcompare(min_colorLA,vals);
		vals = minmaxcompare(min_colorRA,vals);
		vals = minmaxcompare(min_colorLB,vals);
		vals = minmaxcompare(min_colorRB,vals);
		gl_FragColor = vec4(vals.x,vals.y,vals.z,min_color.a);
	}
	//	read from "bufferPassD", write to "bufferVariableNameA"
	else if (PASSINDEX == 4)	{
		vec4 min_color = IMG_THIS_PIXEL(bufferPassD);
		vec4 stalePixel = IMG_THIS_PIXEL(bufferVariableNameA);
		vec4 min_colorL = IMG_NORM_PIXEL(bufferPassD, left_coord);
		vec4 min_colorR = IMG_NORM_PIXEL(bufferPassD, right_coord);
		vec4 min_colorA = IMG_NORM_PIXEL(bufferPassD, above_coord);
		vec4 min_colorB = IMG_NORM_PIXEL(bufferPassD, below_coord);
	
		vec4 min_colorLA = IMG_NORM_PIXEL(bufferPassD, lefta_coord);
		vec4 min_colorRA = IMG_NORM_PIXEL(bufferPassD, righta_coord);
		vec4 min_colorLB = IMG_NORM_PIXEL(bufferPassD, leftb_coord);
		vec4 min_colorRB = IMG_NORM_PIXEL(bufferPassD, rightb_coord);
	
		vals = minmaxcompare(min_color,vals);

		vals = minmaxcompare(min_colorL,vals);
		vals = minmaxcompare(min_colorR,vals);
		vals = minmaxcompare(min_colorA,vals);
		vals = minmaxcompare(min_colorB,vals);

		vals = minmaxcompare(min_colorLA,vals);
		vals = minmaxcompare(min_colorRA,vals);
		vals = minmaxcompare(min_colorLB,vals);
		vals = minmaxcompare(min_colorRB,vals);
		gl_FragColor = mix(vec4(vals.x,vals.y,vals.z,min_color.a),stalePixel,adapt_rate);;
	}
	//	read from "bufferVariableNameA", write to output
	else if (PASSINDEX == 5)	{
		vec4 min_color = IMG_THIS_PIXEL(bufferVariableNameA);
		vec4 min_colorL = IMG_NORM_PIXEL(bufferVariableNameA, left_coord);
		vec4 min_colorR = IMG_NORM_PIXEL(bufferVariableNameA, right_coord);
		vec4 min_colorA = IMG_NORM_PIXEL(bufferVariableNameA, above_coord);
		vec4 min_colorB = IMG_NORM_PIXEL(bufferVariableNameA, below_coord);
	
		vec4 min_colorLA = IMG_NORM_PIXEL(bufferVariableNameA, lefta_coord);
		vec4 min_colorRA = IMG_NORM_PIXEL(bufferVariableNameA, righta_coord);
		vec4 min_colorLB = IMG_NORM_PIXEL(bufferVariableNameA, leftb_coord);
		vec4 min_colorRB = IMG_NORM_PIXEL(bufferVariableNameA, rightb_coord);
	
		vals = minmaxcompare(min_color,vals);

		vals = minmaxcompare(min_colorL,vals);
		vals = minmaxcompare(min_colorR,vals);
		vals = minmaxcompare(min_colorA,vals);
		vals = minmaxcompare(min_colorB,vals);

		vals = minmaxcompare(min_colorLA,vals);
		vals = minmaxcompare(min_colorRA,vals);
		vals = minmaxcompare(min_colorLB,vals);
		vals = minmaxcompare(min_colorRB,vals);
		
		vec4 final_pixel = IMG_THIS_PIXEL(inputImage);
		
		
		float val = gray (final_pixel);
		if (vals.x < min_threshold)	{
			vals.x = min_threshold;
		}
		if (val < min_threshold)	{
			val = min_threshold;
		}
		if (vals.z > max_threshold)	{
			vals.z = max_threshold;
		}
		if (val > max_threshold)	{
			val = max_threshold;
		}
		//final_pixel.rgb = (final_pixel.rgb - vals.x) / (vals.z - vals.x);
		//	shift by the absdiff of the midpoint
		//final_pixel.rgb = final_pixel.rgb + (mid_point - vals.y);
		final_pixel.rgb = final_pixel.rgb - (0.5 - mid_point);
		//	by contrast adjustments
		float diff = vals.z-vals.x;
		if (diff < 0.01)	{
			diff = 0.01;
		}
		final_pixel.rgb = (final_pixel.rgb - vals.x) / diff;
		//float contrast = 1.0/diff;		
		//final_pixel.rgb = ((vec3(2.0) * (final_pixel.rgb - vec3(vals.x))) * vec3(contrast) / vec3(2.0)) + vec3(0.5);
		
		gl_FragColor = final_pixel;
		//gl_FragColor = vec4(vec3(vals.z),1.0);
	}
}

