		final = (1.0 - abs(intensity)) * color + abs(intensity) * (colorL + colorR + colorA + colorB + colorLA + colorRA + colorLB + colorRB) / 8.0;
		final.a = color.a;
	}
	else if (PASSINDEX == 2)	{
