	//	if the brightness is below the threshold draw black
	if (bright < threshold)	{
		if (opaque)
			final = vec4(0.0, 0.0, 0.0, 1.0);
		else
			final = vec4(0.0, 0.0, 0.0, 0.0);
	}
	else	{
		final.rgb = final.rgb * intensity;
		if (opaque)
			final.a = 1.0;
		else
			final.a = color.a;
	}
	
	gl_FragColor = final;
}

