		//	i'm only using the X and Y components, which are the X and Y offset (normalized) for the frame
		srcPixel.xy = (flashEvent) ? vec2(0.0) : (srcPixel.xy - vec2(hHold,vHold));
		gl_FragColor = mod(srcPixel,1.0);
