//	2D hash returning (0..1, 0..1) per integer-grid input.
vec2 hash2(vec2 p)	{
	p = vec2(dot(p, vec2(127.1, 311.7)),
			 dot(p, vec2(269.5, 183.3)));
	return fract(sin(p) * 43758.5453);
}


void main()	{
	vec2  uv         = isf_FragNormCoord;
	vec2  pixelUV    = vec2(1.0) / RENDERSIZE;
	
	//	Luma block grid (8x8 by default).
	float lumaPx          = max(blockSize, 1.0);
	vec2  lumaBlockUV     = vec2(lumaPx) * pixelUV;
	vec2  lumaBlockCoord  = floor(uv / lumaBlockUV);
	vec2  lumaBlockCenter = (lumaBlockCoord + 0.5) * lumaBlockUV;
	
	//	Chroma block grid (typically 2x bigger per axis, mimicking 4:2:0 subsampling).
	float chromaPx          = lumaPx * max(chromaSubsample, 1.0);
	vec2  chromaBlockUV     = vec2(chromaPx) * pixelUV;
	vec2  chromaBlockCoord  = floor(uv / chromaBlockUV);
	vec2  chromaBlockCenter = (chromaBlockCoord + 0.5) * chromaBlockUV;
	
	//	Per-luma-block hash drives displacement and DC corruption.
	//	Shared vertex of seed offset means animating seed wanders the pattern.
	vec2 h = hash2(lumaBlockCoord + seed);
	
	//	Block displacement: each block samples from a different location,
	//	up to ±1 block in each axis. Same displacement applies to luma + chroma
	//	so we preserve the block's color identity, just move it spatially.
	vec2 displace = (h - 0.5) * 2.0 * blockDisplace * lumaBlockUV;
	
	//	Quantize: blend between full-resolution UV (no flattening) and
	//	block-center UV (DC-only flat block).
	vec2 lumaSampleUV   = mix(uv + displace, lumaBlockCenter   + displace, quantize);
	vec2 chromaSampleUV = mix(uv + displace, chromaBlockCenter + displace, quantize);
	
	//	Two samples — one for luma, one for chroma.
	vec4 lumaSrc   = IMG_NORM_PIXEL(inputImage, lumaSampleUV);
	vec4 chromaSrc = IMG_NORM_PIXEL(inputImage, chromaSampleUV);
	
	//	RGB -> Y from luma sample, Cb/Cr from chroma sample (BT.601 coefficients).
	//	The two samples can come from different positions when chromaSubsample > 1
	//	or blockDisplace > 0, which is what produces JPEG-style color bleed.
	float Y      = dot(lumaSrc.rgb,   vec3(0.299, 0.587, 0.114));
	float Y_chr  = dot(chromaSrc.rgb, vec3(0.299, 0.587, 0.114));
	float Cb     = (chromaSrc.b - Y_chr) * 0.564;
	float Cr     = (chromaSrc.r - Y_chr) * 0.713;
	
	//	Per-block DC corruption: shift the luminance up or down by a fraction
	//	determined by the block's hash. This is the "wrong AC=0 coefficient"
	//	artifact you see in deliberately mangled JPEG files.
	Y += (h.y - 0.5) * 2.0 * dcCorrupt;
	
	//	YCbCr -> RGB.
	float R = Y + 1.402 * Cr;
	float G = Y - 0.344 * Cb - 0.714 * Cr;
	float B = Y + 1.772 * Cb;
	
	gl_FragColor = vec4(R, G, B, lumaSrc.a);
}

const float tau = 6.28318530718;


vec2 pattern() {
	float s = sin(tau * rotation);
	float c = cos(tau * rotation);
	vec2 tex = isf_FragNormCoord * RENDERSIZE;
	float scale = 1.0 / max(size,0.001);
	vec2 point = vec2( c * tex.x - s * tex.y, s * tex.x + c * tex.y ) * scale;
	point = (point - (shift*RENDERSIZE)) / RENDERSIZE;
	//	do this to repeat
	point = mod(point,1.0);
	if (point.x < 0.5)	{
		point.y = mod(point.y + slide1.y, 1.0);
	}
	else	{
		point.y = mod(point.y + slide2.y, 1.0);
	}
	if (point.y < 0.5)	{
		point.x = mod(point.x + slide1.x, 1.0);
	}
	else	{
		point.x = mod(point.x + slide2.x, 1.0);
	}
	//	do this for relections
	point = 1.0-abs(1.0-2.0*point);
	
	//	Now let's do a squish based on angle
	//	convert to polar coordinates
	vec2 center = vec2(0.5,0.5);
	float r = distance(center, point);
	float a = atan ((point.y-center.y),(point.x-center.x));
	
	// now do the kaleidoscope
	a = mod(a, tau/sides);
	a = abs(a - tau/sides/2.);
	
	s = sin(a + tau * angle);
	c = cos(a + tau * angle);
	
	float zoom = RENDERSIZE.x / RENDERSIZE.y;
	
	point.x = (r * c)/zoom + 0.5;
	point.y = (r * s)/zoom + 0.5;
	
	return point;
}


void main() {

	vec2 pat = pattern();

	gl_FragColor = IMG_NORM_PIXEL(inputImage,pat);
}

const float tau = 6.28318530718;




void main() {
  // normalize to the center
	vec2 loc = RENDERSIZE * vec2(isf_FragNormCoord[0],isf_FragNormCoord[1]);
	float r = distance(center*RENDERSIZE, loc);
	float a = atan ((loc.y-center.y*RENDERSIZE.y),(loc.x-center.x*RENDERSIZE.x));
	
	// kaleidoscope
	a = mod(a, tau/sides);
	a = abs(a - tau/sides/2.);
	
	loc.x = r * cos(a + tau * angle);
	loc.y = r * sin(a + tau * angle);
	
	loc = (center*RENDERSIZE + loc) / RENDERSIZE;
	
	loc.x = mod(loc.x + slidex, 1.0);
	loc.y = mod(loc.y + slidey, 1.0);

	// sample the image
	if (loc.x < 0.0)	{
		loc.x = mod(abs(loc.x), 1.0);
	}
	if (loc.y < 0.0)	{
		loc.y = mod(abs(loc.y),1.0);
	}
	if (loc.x > 1.0)	{
		loc.x = mod(abs(1.0-loc.x),1.0);
	}
	if(loc.y > 1.0)	{
		loc.y = mod(abs(1.0-loc.y),1.0);	
	}
	gl_FragColor = IMG_NORM_PIXEL(inputImage, loc);;
}

void main()	{
	vec4		color = IMG_THIS_PIXEL(inputImage);
	vec4		scaledLift = (lift - vec4(0.5));
	vec4		scaledGain = gain * 4.0;
	vec4		scaledGamma = max(vec4(0.0001),gamma * 4.0);
	
	color = clamp(color + (scaledLift * (1.0 - color)), 0.0, 1.0);
	color = clamp(color * scaledGain, 0.0, 1.0);
	color = clamp(pow(color, scaledGamma), 0.0, 1.0);
	
	float		satLuma = (0.2126 * color.r) + (0.7152 * color.g) + (0.0722 * color.b);
	
	color.r = clamp(satLuma + (saturation*(color.r - satLuma)), 0.0, 1.0);
	color.g = clamp(satLuma + (saturation*(color.g - satLuma)), 0.0, 1.0);
	color.b = clamp(satLuma + (saturation*(color.b - satLuma)), 0.0, 1.0);

	gl_FragColor = color;
}

//	as a guide, http://john-chapman-graphics.blogspot.co.uk/2013/02/pseudo-lens-flare.html
//	1 downsample and threshold
//	2 feature generation: ghosts, halos and chromatic distortion
//	3 blur
