	//	get the pixel location
	vec2	loc = gl_FragCoord.xy;
	
	float	gridSize = 5.0;
	
	if ((mod(loc.x, gridSize * 2.0) > gridSize) && (mod(loc.y, gridSize * 2.0) < gridSize))	{
		returnMe = vec4(1.0);
	}
	else if ((mod(loc.x, gridSize * 2.0) < gridSize) && (mod(loc.y, gridSize * 2.0) > gridSize))	{
		returnMe = vec4(1.0);
	}
	
	return returnMe;
}

//	returns the pattern based on the index
vec4 patternSelect(int pIndex, vec2 seed)	{
	
	//	black
	if (pIndex == 0)	{
		return vec4(0.0, 0.0, 0.0, 1.0);
	}
	//	checkerboard
	else if (pIndex == 1)	{
		return checkerboard();
	}
	//	h stripes
	else if (pIndex == 2)	{
		return horizontalStripes();
	}
	//	v stripes
	else if (pIndex == 3)	{
		return verticalStripes();
	}
	//	color bars
	else if (pIndex == 4)	{
		return colorBars();
	}
	//	noise (b&w)
	else if (pIndex == 5)	{
		return noiseBW();
	}
	else if (pIndex == 6)	{
		return noiseColor(seed);
	}
	
	return vec4(0.0);
}

