// Author: gre
// License: MIT
// Description: The outgoing image comes apart like interlaced lines of data: its even rows slide up and its odd rows slide down into two half-height copies, each copy splits again into four, then eight; the copies flip over to the incoming image, whose rows interleave back into one picture
// Tags: stripes, interlace, split, flip, 3d, graphic

// @range(1, 4, 1) Number of splitting rounds: the image ends up as 2, 4, 8 or 16 copies
uniform int stages; // = 3
// @color Color showing between the rows while they are apart
uniform vec4 gap; // = vec4(0.08, 0.08, 0.09, 1.0)

const float PI = 3.14159265;

float ease3(float x) {
  x = clamp(x, 0.0, 1.0);
  float y = 2.0 - 2.0 * x;
  return x < 0.5 ? 4.0 * x * x * x : 1.0 - 0.5 * y * y * y;
}

// inverse of one round at amount a: in each block of B rows, even rows gather in its top half, odd rows in its bottom half
float unweave(float z, float B, float a, inout float lit) {
  float bo = floor(z / B) * B;
  float lz = z - bo;
  float c = 1.0 - 0.5 * a;
  float off = a * (B - 1.0) * 0.5;
  // rows of one parity are at least one row apart, so only the last one starting before lz can cover it
  float io = floor((lz - off) / c);
  float ko = io - mod(io + 1.0, 2.0);
  float f = lz - ko * c - off;
  if (ko >= 1.0 && ko < B && f < 1.0) return bo + ko + f;
  float ie = floor(lz / c);
  float ke = ie - mod(ie, 2.0);
  f = lz - ke * c;
  if (ke >= 0.0 && ke < B && f < 1.0) {
    // dimming the even rows while they move makes the odd ones read as passing over them
    lit *= 1.0 - 0.25 * sin(PI * a);
    return bo + ke + f;
  }
  lit = -1.0;
  return z;
}

vec4 transition(vec2 uv) {
  float S = clamp(float(stages), 1.0, 4.0);
  // built by doubling so block sizes stay exact integers
  float copies = 1.0;
  for (int i = 0; i < 4; i++) {
    if (float(i) < S) copies *= 2.0;
  }
  // rows per copy: at least 6, and at least 48 rows over the frame
  float rows = max(6.0, 48.0 / copies);
  float M = rows * copies;
  float z = (1.0 - uv.y) * M;
  float band = floor(z / rows);
  float th = PI * ease3((progress - 0.43 - 0.07 * band / (copies - 1.0)) / 0.07);
  float ca = cos(th);
  bool inc = ca < 0.0;
  // each copy flips about its horizontal axis, seen from 2.5 frame heights away
  float kp = sin(th) * sign(ca) / (2.5 * copies);
  float ys = fract(z / rows) - 0.5;
  float v = ys / max(abs(ca) - ys * kp, 1e-4);
  float x = 0.5 + (uv.x - 0.5) * (1.0 + v * kp);
  z = (band + 0.5 + clamp(v, -0.5, 0.4999)) * rows;
  float q = clamp((inc ? 1.0 - progress : progress) / 0.43, 0.0, 1.0);
  // rounds overlap so the rows never stop between them
  float w = 1.0 / (0.6 * (S - 1.0) + 1.0);
  float lit = 1.0;
  float B = 2.0 * rows;
  for (int i = 4; i >= 1; i--) {
    if (float(i) > S) continue;
    z = unweave(z, B, ease3((q - 0.6 * w * float(i - 1)) / w), lit);
    if (lit < 0.0) break;
    B *= 2.0;
  }
  vec2 p = vec2(x, 1.0 - z / M);
  vec4 c = inc ? getToColor(p) : getFromColor(p);
  c.rgb *= max(lit, 0.0) * (0.55 + 0.45 * abs(ca));
  float aa = 400.0 / copies;
  float edge = clamp((0.5 - abs(v)) * aa + 1.0, 0.0, 1.0) * clamp((0.5 - abs(x - 0.5)) * 400.0 * ratio + 1.0, 0.0, 1.0);
  return mix(gap, c, step(0.0, lit) * edge);
}

// Author: gre
// License: MIT
// Description: A soft-edged diamond grows from the center to reveal the incoming image
// Tags: shape, wipe, iris

// @param Center of the diamond
uniform vec2 center; // = vec2(0.5)
// @range(0, 0.5) Softness of the diamond's edge
uniform float smoothness; // = 0.03

vec4 transition (vec2 uv) {
  // Measured in square pixels, so the diamond is not stretched
  vec2 d = abs(uv - center) * vec2(ratio, 1.0);
  vec2 far = max(center, 1.0 - center) * vec2(ratio, 1.0);
  float dist = (d.x + d.y) / (far.x + far.y);
  float s = max(smoothness, 0.001);
  float m = smoothstep(0.0, s, progress * (1.0 + s) - dist);
  return mix(getFromColor(uv), getToColor(uv), m);
}

// Author: gre
// License: MIT
// Description: The outgoing image diffuses into a shimmering, grainy haze, as if its pixels were scattered further and further from where they belong, and the incoming image condenses back out of the haze as they settle into place
// Tags: dissolve, grain, noise, scatter, texture

// @range(0.01, 0.2) How far the pixels scatter at the peak, in frame heights
uniform float radius; // = 0.06
// @range(0.002, 0.02) Size of a grain, in frame heights
uniform float grainSize; // = 0.004
// @range(0, 1) How much the grains swirl around while they are scattered
uniform float shimmer; // = 0.5

const float PI = 3.14159265;

// a hash of an integer cell, stable across precisions
vec4 hash42(vec2 p) {
  vec4 p4 = fract(vec4(p.xyxy) * vec4(0.1031, 0.1030, 0.0973, 0.1099));
  p4 += dot(p4, p4.wzxy + 33.33);
  return fract((p4.xxyz + p4.yzzw) * p4.zywx);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 transition(vec2 uv) {
  float a = 1.0 - abs(2.0 * progress - 1.0);
  float amount = a * a * (3.0 - 2.0 * a);
  vec2 cell = floor(uv * vec2(ratio, 1.0) / max(grainSize, 1e-4));
  vec4 h = hash42(cell);
  float angle = 2.0 * PI * (h.x + shimmer * (2.0 * h.w - 1.0) * progress);
  float dist = radius * amount * 0.5 * (h.y + h.z);
  vec2 offset = dist * vec2(cos(angle) / ratio, sin(angle));
  vec2 suv = mirror(uv + offset);
  // each grain switches at its own moment around the peak (hashed off the cell corners, independently of the scatter)
  float when = 0.3 + 0.4 * hash42(cell + vec2(0.5, 0.25)).x;
  float m = smoothstep(when - 0.1, when + 0.1, progress);
  // each image is only read while it shows
  if (m <= 0.0) return getFromColor(suv);
  if (m >= 1.0) return getToColor(suv);
  return mix(getFromColor(suv), getToColor(suv), m);
}

// Author: Gaëtan Renaudeau
// License: MIT
// Description: The incoming image pushes the outgoing one out in a given direction
// Tags: slide, push, directional

// @param Direction of the movement
uniform vec2 direction; // = vec2(0.0, 1.0)

vec4 transition (vec2 uv) {
  vec2 p = uv + progress * sign(direction);
  vec2 f = fract(p);
  return mix(
    getToColor(f),
    getFromColor(f),
    step(0.0, p.y) * step(p.y, 1.0) * step(0.0, p.x) * step(p.x, 1.0)
  );
