// Description: The outgoing image shrinks away to the left while the incoming one slides in from the right
// Tags: slide, zoom, horizontal

const vec4 black = vec4(0.0); // where no image is drawn: transparent
const vec2 boundMin = vec2(0.0, 0.0);
const vec2 boundMax = vec2(1.0, 1.0);

bool inBounds (vec2 p) {
    return all(lessThan(boundMin, p)) && all(lessThan(p, boundMax));
}

vec4 transition (vec2 uv) {
    vec2 spfr,spto = vec2(-1.);

    float size = mix(1.0, 3.0, progress*0.2);
    spto = (uv + vec2(-0.5,-0.5))*vec2(size,size)+vec2(0.5,0.5);
    spfr = (uv - vec2(1.-progress, 0.0));
    if(inBounds(spfr)){
        return getToColor(spfr);
    }else if(inBounds(spto)){
        return getFromColor(spto) * (1.0 - progress);
    } else{
        return black;
    }
}

// Author: gre
// License: MIT
// Description: A bright light sweeps across the frame and flares the lens: a long thin horizontal streak, a glowing core and a trail of colored ghost reflections; at its peak the incoming image spreads out from the light under its glare
// Tags: light, flare, glow, streak

// @range(-90, 90) Angle of the path of the light, in degrees (0 sweeps from left to right)
uniform float angle; // = -12.0
// @range(-0.5, 0.5) How far above the center of the frame the light passes
uniform float height; // = 0.18
// @range(0, 2) Brightness of the flare
uniform float intensity; // = 1.0
// @color Color of the streak and of the glare
uniform vec3 color; // = vec3(0.35, 0.6, 1.0)

const int BLOOM_TAPS = 12;
const int GHOSTS = 6;

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 premultiplied(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 frame(vec2 st, float m) {
  if (m <= 0.0) return premultiplied(getFromColor(st));
  if (m >= 1.0) return premultiplied(getToColor(st));
  return mix(premultiplied(getFromColor(st)), premultiplied(getToColor(st)), m);
}

vec3 highlight(vec4 c) {
  float lum = dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
  return c.rgb * smoothstep(0.55, 0.95, lum);
}

vec4 transition(vec2 uv) {
  float p = progress;

  float env = 4.0 * p * (1.0 - p);
  float peak = pow(env, 24.0);
  vec2 aspect = vec2(ratio, 1.0);
  vec2 q = (uv - 0.5) * aspect;
  float r = radians(angle);
  vec2 dir = vec2(cos(r), -sin(r));
  vec2 normal = vec2(-dir.y, dir.x);
  float t = p - 0.5;
  float travel = 0.5 * (abs(dir.x) * ratio + abs(dir.y)) + 0.3;
  float along = travel * (2.0 * t) * (0.55 + 1.8 * t * t);
  vec2 src = dir * along + normal * height;

  vec2 d = q - src;
  float dist = length(d);
  float k = intensity * env;

  // the cut, under the glare: the incoming image spreads out from the light in a soft circle,
  // slower as the flare gets dimmer so that it still reads as intended
  float cut = mix(0.2, 0.06, clamp(intensity, 0.0, 1.0));
  float s = clamp((p - 0.5 + cut) / (2.0 * cut), 0.0, 1.0);
  float soft = 0.3;
  float reach = 0.5 * length(aspect) + length(src) + soft;
  float front = s * (reach + soft);
  float m = smoothstep(front, front - soft, dist);
  vec4 base = frame(uv, m);

  float ax = abs(d.x);
  float ay = abs(d.y);
  float thin = exp(-ay * 140.0) * exp(-ax * 0.7);
  float wide = exp(-ay * 30.0) * exp(-ax * 1.6);
  vec3 tint = color;
  vec3 streak = (thin * mix(vec3(1.0), tint, smoothstep(0.0, 0.3, ax)) + 0.5 * wide * tint) * 3.0;

  vec3 core = vec3(1.0, 0.97, 0.92) * exp(-dist * dist * 600.0) * 3.0 + mix(vec3(1.0), tint, 0.5) * exp(-dist * 7.0) * 0.6;

  vec3 ghosts = vec3(0.0);
  for (int i = 0; i < GHOSTS; i++) {
    float fi = float(i);
    float f = -0.45 + 0.42 * fi + 0.08 * sin(fi * 2.3);
    vec2 g = -src * f;
    float size = 0.025 + 0.06 * fract(fi * 0.618 + 0.2);
    float gd = length(q - g) / size;
    float disc = smoothstep(1.0, 0.8, gd) * (0.35 + 0.65 * smoothstep(0.4, 0.95, gd));
    vec3 hue = mix(tint, vec3(1.0, 0.65, 0.35), fract(fi * 0.53));
    hue = mix(hue, vec3(0.5, 1.0, 0.6), step(4.5, fi) * 0.6);
    ghosts += disc * hue * 0.45;
  }

  vec3 bloom = vec3(0.0);
  if (peak > 1e-3) {
    float radius = 0.06 * env;
    for (int i = 0; i < BLOOM_TAPS; i++) {
      float fi = float(i);
      float a = fi * 2.39996;
      float rr = radius * sqrt((fi + 0.5) / float(BLOOM_TAPS));
      vec2 o = vec2(cos(a), sin(a)) * rr / aspect;
      bloom += highlight(frame(mirror(uv + o), m));
    }
    bloom /= float(BLOOM_TAPS);
  }

  // at the peak, the glare: a wide halo around the light and a light veil over the frame, to hide the cut
  vec3 glare = mix(vec3(1.0), tint, 0.5) * peak * (0.45 + 2.2 * exp(-dist * 3.0));

  vec3 light = k * (streak + core + ghosts) + intensity * (bloom * 2.5 * peak + glare);
  light = 1.0 - exp(-light);

  // screened over the image; the flare only shows on the image, so transparency is kept
  vec3 c = base.rgb + light * base.a - base.rgb * light;
  if (base.a <= 0.0) return vec4(0.0);
  return vec4(clamp(c / base.a, 0.0, 1.0), base.a);
}

// Author: gre
// License: MIT
// Description: The incoming image pushes the outgoing one out of frame as if seen through a wide-angle lens: the frame bulges and bends the seam while the images speed past, with motion blur, color fringes toward the edges and a light vignette, then flattens back as the push lands
// Tags: slide, push, lens, distort, motion-blur, chromatic-aberration, directional

// @param Direction in which the images move, snapped to the nearest of the 8 horizontal, vertical and diagonal directions
uniform vec2 direction; // = vec2(-1.0, 0.0)
// @range(0, 1) Strength of the lens bulge at the peak
uniform float strength; // = 0.7
// @range(0, 1) Spread of the color fringes toward the edges
uniform float fringe; // = 0.5
// @range(0, 1) Length of the motion blur at full speed
uniform float blur; // = 0.35

const int SAMPLES = 24;

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 strip(vec2 q, vec2 d) {
  if (q.x >= 0.0 && q.x <= 1.0 && q.y >= 0.0 && q.y <= 1.0) {
    return getFromColor(q);
  }
  return getToColor(mirror(q + d));
}

vec4 transition(vec2 uv) {
  // snap to the nearest of the 8 directions: drop a component under tan(22.5deg) of the other
  vec2 ad = abs(direction);
  vec2 d = sign(direction) * step(0.4142 * max(ad.x, ad.y), ad);
  if (dot(d, d) == 0.0) d = vec2(-1.0, 0.0);
  float p = progress;
  // position: smooth start and landing; the motion blur follows the speed (1.875 at the peak)
  float pos = p * p * p * (p * (p * 6.0 - 15.0) + 10.0);
  float speed = 30.0 * p * p * (1.0 - p) * (1.0 - p) / 1.875;
  float len = clamp(blur, 0.0, 1.0) * 0.25 * speed;
  float h = 1.0 - abs(2.0 * p - 1.0);
  float hs = h * h * (3.0 - 2.0 * h);
  float k = clamp(strength, 0.0, 1.0) * 0.75 * hs;
  float ca = clamp(fringe, 0.0, 1.0) * 0.06 * hs;

  // round barrel lens that keeps the corners in place: 1.0 at the corners
  vec2 aspect = vec2(ratio, 1.0);
  float r = length((uv - 0.5) * aspect) / length(0.5 * aspect);
  float r2 = r * r;

  // each tap is both a step of the motion blur and a wavelength: the blue end is drawn in a bit
  // more than the red end, growing toward the edges, so colors split around the contours there
  float jitter = hash(uv * aspect * 731.0);
  vec3 col = vec3(0.0);
  vec3 wsum = vec3(0.0);
  float alpha = 0.0;
  for (int i = 0; i < SAMPLES; i++) {
    float t = (float(i) + 0.5) / float(SAMPLES);
    vec3 w = vec3(t, 1.0 - abs(2.0 * t - 1.0), 1.0 - t);
    vec2 q = 0.5 + (uv - 0.5) * (1.0 - k + k * r2) * (1.0 - ca * (1.0 - t) * r2);
    // spread the blur steps over the wavelengths, so every color gets an even blur; the steps
    // never reach past the two images, at the start and at the landing
    float b = fract((float(i) * 7.0 + jitter) / float(SAMPLES)) - 0.5;
    vec4 c = strip(q - d * clamp(pos + len * b, 0.0, 1.0), d);
    col += w * c.rgb * c.a;
    wsum += w * c.a;
    alpha += c.a;
  }
  col /= max(wsum, vec3(1e-5));
  col *= 1.0 - 0.45 * k * r2;
  return vec4(col, alpha / float(SAMPLES));
}

// Author: gre
// License: MIT
// Description: A round glass lens grows from a point over the outgoing image, casting a soft shadow on it, and shows the incoming image magnified through it, with a bright bevelled rim and faint color fringes; as the lens fills the frame the magnification relaxes until the incoming image lies flat
// Tags: lens, glass, circle, iris, magnify, reveal

// @param Point the lens grows from
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(0, 0.8) How strongly the lens magnifies the middle of the incoming image at the start
uniform float strength; // = 0.5
// @range(0, 1) Strength of the rim's light and shade and of the shadow the lens casts (0 for a clean cut)
uniform float shading; // = 0.6

const float AA = 0.0015;
const float BEVEL = 0.07;
// moment the lens has grown past the farthest corner
const float OPEN = 0.8;
// toward the light, from the top left (xy of a unit vector)
const vec2 LIGHT = vec2(-0.6, 0.8);

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 aspect = vec2(ratio, 1.0);
  float sh = clamp(shading, 0.0, 1.0);

  vec2 far = max(center, 1.0 - center) * aspect;
  float full = length(far) / (1.0 - BEVEL) + 2.0 * AA;
  float t = clamp(p / OPEN, 0.0, 1.0);
  float radius = full * t * (0.5 + t * (2.0 - 1.5 * t));

  // the magnification relaxes while the lens finishes growing: exactly 0 at the end
  float k = clamp(strength, 0.0, 0.8) * (1.0 - smoothstep(0.35, 1.0, p));

  vec2 d = (uv - center) * aspect;
  float r = length(d);

  vec4 a = vec4(0.0);
  if (r > radius - 2.0 * AA) {
    a = getFromColor(uv);
    float sd = length(d + 0.1 * LIGHT * radius) / max(radius, 1e-5);
    float shadow = 0.55 * sh * (1.0 - smoothstep(0.85, 1.35, sd)) * smoothstep(0.0, 0.05, radius);
    a.rgb *= 1.0 - shadow;
    if (r >= radius) return a;
  }

  float s = r / radius;
  float f = 1.0 - k * (1.0 - s * s);
  vec2 n = r > 0.0 ? d / r : vec2(0.0);
  vec2 ca = n * (0.014 * k * s * s) / aspect;
  vec2 q = center + d * f / aspect;
  // each channel keeps the alpha of the tap it comes from
  vec4 cr = getToColor(mirror(q + ca));
  vec4 cg = getToColor(mirror(q));
  vec4 cb = getToColor(mirror(q - ca));
  float alpha = (cr.a + cg.a + cb.a) / 3.0;
  vec4 b = vec4(vec3(cr.r * cr.a, cg.g * cg.a, cb.b * cb.a) / max(alpha, 1e-5), alpha);

  float bevel = smoothstep(1.0 - BEVEL, 1.0, s);
  float facing = dot(n, LIGHT);
  float lit = bevel * bevel;
  vec3 shade = vec3(1.0 - 0.35 * sh * lit * max(-facing, 0.0) - 0.12 * sh * bevel);
  float spec = sh * lit * (0.55 * max(facing, 0.0) + 0.12);
