  return fract((p3.x + p3.y) * p3.z);
}

vec4 pdHash4(vec2 p) {
  vec4 p4 = fract(vec4(p.xyxy) * vec4(0.1031, 0.1030, 0.0973, 0.1099));
  p4 += dot(p4, p4.wzxy + 33.33);
  return fract((p4.xxyz + p4.yzzw) * p4.zywx);
}

float pdNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(pdHash(i), pdHash(i + vec2(1.0, 0.0)), f.x),
    mix(pdHash(i + vec2(0.0, 1.0)), pdHash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

vec2 pdFold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

// Strokes lie in rows along the direction of their layer, each row shifted by its own amount.
// A pixel looks for strokes in the 2 nearest cells of the 2 nearest rows: a stroke never reaches
// further than 1 cell along its row (0.76 + 0.06 at its dry end + 0.06 of antialiasing + 0.02 of tilt
// + 0.08 of jitter = 0.98) nor than 1 row across (0.2 + 0.06 of antialiasing + 0.05 of tilt + 0.04 of bend
// + 0.02 of jitter = 0.37, out of ROW = 0.4).
// Antialiasing is 0.0025 frame heights, which fits in 0.06 cells when cells are at least MIN_SIZE long.
const float MIN_SIZE = 0.042;

// center of the stroke of a cell (row in y) whose row is shifted by `shift`, in cells of its layer
vec2 pdCenter(vec2 cell, float shift, vec4 h) {
  return vec2(cell.x + 0.5 + shift + (h.x - 0.5) * 0.16, cell.y + 0.5 + (h.y - 0.5) * 0.1);
}

vec2 pdToUv(vec2 p, vec2 off, float size, vec2 dir) {
  vec2 l = (p - off) * vec2(size, size * ROW);
  vec2 q = dir * l.x + vec2(-dir.y, dir.x) * l.y;
  return q / vec2(ratio, 1.0) + 0.5;
}

// the stroke centered at c (in cells of layer k, offset by `off`) seen from p.
// returns (coverage, relief shading, start time, streaks)
vec4 pdStroke(vec2 p, vec2 c, vec2 cell, vec4 h, float size, float k, vec2 off, float t0, float spread, float dur, float dry, vec2 dir) {
  vec2 d = (p - c) * vec2(1.0, ROW); // in stroke lengths
  float tilt = (h.z - 0.5) * 0.12;
  float a = d.x + tilt * d.y; // along the stroke
  float b = d.y - tilt * d.x - (h.w - 0.5) * 0.12 * a * a; // across it
  float L = 0.66 + 0.1 * h.w;
  float W = 0.17 + 0.03 * h.z;
  vec2 world = (c - off) * vec2(size, size * ROW);
  float order = 0.55 * pdNoise(world * 3.0 + k * 5.0) + 0.45 * pdHash(cell * 1.7 + vec2(k * 9.0, 3.0));
  float start = t0 + spread * clamp((order - 0.15) / 0.7, 0.0, 1.0); // (order is mostly in 0.15..0.85)
  float s = clamp((progress - start) / dur, 0.0, 1.0);
  s = 1.0 - (1.0 - s) * (1.0 - s);
  float seed = h.x * 37.0 + k * 11.0;
  float bw = b / W; // -1..1 across the core of the stroke
  // bristle streaks along the stroke (fewer on small strokes, so that they stay a few pixels wide)
  float hairs = clamp(size * 50.0, 3.0, 16.0);
  float br = 0.6 * pdNoise(vec2(bw * 0.4 * hairs + seed, a * 2.0)) + 0.4 * pdNoise(vec2(bw * 0.8 * hairs - seed, a * 1.2 + 5.0));
  float aa = 0.0025 / size;
  float u = clamp(a / L, -1.0, 1.0);
  float width = (0.8 + 0.2 * (1.0 - u * u)) * (0.92 + 0.08 * pdNoise(vec2(a * 6.0, seed))) - 0.1 * br;
  float side = 1.0 - smoothstep(width - aa / W, width + aa / W, abs(bw));
  float tail = smoothstep(-aa, aa, a + L - 0.12 * bw * bw);
  float head = mix(-L - 0.1, L + 0.2, s);
  float lay = smoothstep(0.0, 0.25, (head - a) / 0.2 - 0.6 * br);
  float lift = smoothstep(-aa, aa, L + 0.12 * (br - 0.5) - a);
  float fb = pdNoise(vec2(bw * hairs + seed, a * 0.9 - seed));
  float dryness = dry * smoothstep(0.1, 1.0, u);
  float cover = side * tail * lay * lift * (1.0 - dryness * (1.0 - smoothstep(0.3, 0.6, fb)));
  float ridge = bw * (1.0 - 0.5 * abs(bw)) * 0.8 + (br - 0.5) + 0.7 * (fb - 0.5);
  float facing = dot(vec2(-dir.y, dir.x), vec2(-0.6, 0.8));
  return vec4(cover, -ridge * facing, start, br);
}

// how much stroke x shows through stroke y: hidden by y where y was laid down after it
float pdUnder(vec4 x, vec4 y) {
  return y.z > x.z ? 1.0 - y.x : 1.0;
}

// paints one layer of strokes over `below`, at an angle `th`.
// solid layers take the color of the incoming image under the middle of each stroke, the detail
// layers lay down the incoming image itself (`detail`, at this pixel), with less dry gaps
vec4 pdLayer(vec4 below, vec2 q, float size, float k, float th, float t0, float spread, float dur, bool solid, vec4 detail) {
  size = max(size, MIN_SIZE);
  vec2 dir = vec2(cos(th), sin(th));
  vec2 off = vec2(k * 0.37, k * 0.61);
  vec2 p = vec2(dot(q, dir), dot(q, vec2(-dir.y, dir.x))) / vec2(size, size * ROW) + off;
  float r = floor(p.y - 0.5);
  float sh0 = pdHash(vec2(r, 7.3));
  float sh1 = pdHash(vec2(r + 1.0, 7.3));
  float x0 = floor(p.x - sh0 - 0.5);
  float x1 = floor(p.x - sh1 - 0.5);
  vec2 c0 = vec2(x0, r);
  vec2 c1 = vec2(x0 + 1.0, r);
  vec2 c2 = vec2(x1, r + 1.0);
  vec2 c3 = vec2(x1 + 1.0, r + 1.0);
  vec2 kk = vec2(k * 41.0, k * 17.0);
  vec4 h0 = pdHash4(c0 + kk);
  vec4 h1 = pdHash4(c1 + kk);
  vec4 h2 = pdHash4(c2 + kk);
  vec4 h3 = pdHash4(c3 + kk);
  vec2 m0 = pdCenter(c0, sh0, h0);
  vec2 m1 = pdCenter(c1, sh0, h1);
  vec2 m2 = pdCenter(c2, sh1, h2);
  vec2 m3 = pdCenter(c3, sh1, h3);
  float dry = solid ? 0.85 : 0.4;
  vec4 s0 = pdStroke(p, m0, c0, h0, size, k, off, t0, spread, dur, dry, dir);
  vec4 s1 = pdStroke(p, m1, c1, h1, size, k, off, t0, spread, dur, dry, dir);
  vec4 s2 = pdStroke(p, m2, c2, h2, size, k, off, t0, spread, dur, dry, dir);
  vec4 s3 = pdStroke(p, m3, c3, h3, size, k, off, t0, spread, dur, dry, dir);
  float v0 = s0.x * pdUnder(s0, s1) * pdUnder(s0, s2) * pdUnder(s0, s3);
  float v1 = s1.x * pdUnder(s1, s0) * pdUnder(s1, s2) * pdUnder(s1, s3);
  float v2 = s2.x * pdUnder(s2, s0) * pdUnder(s2, s1) * pdUnder(s2, s3);
  float v3 = s3.x * pdUnder(s3, s0) * pdUnder(s3, s1) * pdUnder(s3, s2);
  vec4 k0 = detail;
  vec4 k1 = detail;
  vec4 k2 = detail;
  vec4 k3 = detail;
  // only the strokes that show are sampled
  if (solid) {
    if (v0 > 0.0) k0 = getToColor(pdFold(pdToUv(m0, off, size, dir)));
    if (v1 > 0.0) k1 = getToColor(pdFold(pdToUv(m1, off, size, dir)));
    if (v2 > 0.0) k2 = getToColor(pdFold(pdToUv(m2, off, size, dir)));
    if (v3 > 0.0) k3 = getToColor(pdFold(pdToUv(m3, off, size, dir)));
  }
  float relief = impasto * (solid ? 0.18 : 0.12) * (1.0 - smoothstep(0.7, 0.95, progress));
  k0.rgb *= 1.0 + relief * (s0.y + 0.5 * (s0.w - 0.5));
  k1.rgb *= 1.0 + relief * (s1.y + 0.5 * (s1.w - 0.5));
  k2.rgb *= 1.0 + relief * (s2.y + 0.5 * (s2.w - 0.5));
  k3.rgb *= 1.0 + relief * (s3.y + 0.5 * (s3.w - 0.5));
  float vis = v0 + v1 + v2 + v3;
  return below * (1.0 - vis) + k0 * v0 + k1 * v1 + k2 * v2 + k3 * v3;
}

vec4 transition(vec2 uv) {
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  vec4 to = getToColor(uv);
  vec4 col = getFromColor(uv);
  float sz = brushSize;
  float th = angle * PI / 180.0;
  float x = crossing * 0.6;
  col = pdLayer(col, q, sz, 0.0, th, 0.0, 0.3, 0.12, true, to);
  col = pdLayer(col, q, sz * 0.6, 1.0, th + x, 0.2, 0.28, 0.1, true, to);
  col = pdLayer(col, q, sz * 0.36, 2.0, th - x * 0.7, 0.38, 0.26, 0.09, true, to);
  col = pdLayer(col, q, sz * 0.22, 3.0, th + x * 0.4, 0.56, 0.22, 0.08, false, to);
  col = pdLayer(col, q, sz * 0.2, 4.0, th - x * 0.3, 0.68, 0.2, 0.08, false, to);
  col = mix(col, to, smoothstep(0.92, 1.0, progress));
  return clamp(col, 0.0, 1.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image is a sheet of paper that folds in half in 3D along a vertical crease, then in half again along a horizontal one, its lit and shaded faces turning to show the back of the paper, and the small folded packet flies off the frame, leaving its shadow on the incoming image underneath
// Tags: paper, fold, 3d, shadow

// @param Direction the folded packet flies off toward
uniform vec2 direction; // = vec2(1.0, 0.5)
// @range(0, 1) How much the sheet tilts and recedes while it folds, so that the folds are seen in 3D
uniform float tilt; // = 0.6
// @range(0, 1) How much the faces darken as they turn away from the light, and the shadows they cast
uniform float shading; // = 0.6
// @color Color of the back of the paper, through which the print faintly shows
uniform vec4 paper; // = vec4(0.95, 0.94, 0.9, 1.0)

const float PI = 3.141592653589793;
const float EDGE = 0.0015;
const float SHOW = 0.1;
const float CREASE = 0.02;
const vec3 LIGHT = vec3(-0.3995, 0.4494, 0.799);

vec4 front(vec2 st) {
  return getFromColor(st / vec2(ratio, 1.0));
}

vec4 back(vec2 st) {
  vec4 c = front(st);
  return vec4(mix(paper.rgb, c.rgb, SHOW), c.a * paper.a);
}

// the face of the packet's top layer: the image itself during the first fold, then the back
// of the right half, laid mirrored over the left half
vec4 topFace(vec2 st, bool second) {
  return second ? back(vec2(ratio - st.x, st.y)) : front(st);
}

// distance inside the rectangle [0, h] x [0, k] (negative outside)
float inside(vec2 p, float h, float k) {
  return min(min(p.x, h - p.x), min(p.y, k - p.y));
}

// The sheet in its own frame: a flat part [0, h] x [0, k] lying at z = 0 and a flap of the same
// size hinged on its edge x = h, turned toward the viewer so that it lies along `along`, with the
// normal n. During the second fold, x and y are swapped so that the crease is always along y.
// Where the ray o + t * v meets the flap's plane: (t, distance from the hinge, y), t < 0 if never.
vec3 hitFlap(vec3 o, vec3 v, float h, vec3 n, vec3 along) {
  float den = dot(n, v);
  if (abs(den) < 1e-5) return vec3(-1.0, 0.0, 0.0);
  vec3 hinge = vec3(h, 0.0, 0.0);
  float t = dot(n, hinge - o) / den;
  vec3 q = o + t * v;
  return vec3(t, dot(q - hinge, along), q.y);
}

// how much the point q is shaded, lit by l: by the flap, and by the flat part once it lifts
// above the incoming image
float shadowAt(vec3 q, vec3 l, float h, float k, vec3 n, vec3 along) {
  float sh = 0.0;
  if (q.z < -1e-4) {
    float soft = 0.004 - 0.4 * q.z;
    sh = smoothstep(-soft, soft, inside(q.xy - q.z / l.z * l.xy, h, k));
  }
  vec3 hit = hitFlap(q, l, h, n, along);
  if (hit.x > 0.0) {
    float height = hit.x * l.z;
    float soft = 0.004 + 0.3 * height;
    sh = max(sh, min(4.0 * n.x * n.x, 1.0) * smoothstep(-soft, soft, inside(hit.yz, h, k)) / (1.0 + 3.0 * height));
  }
  return sh;
}

// a vector of the frame into the frame of the sheet, turned by yaw (around y), pitch (around x)
// and spin (around z), each given as (cos, sin)
vec3 toSheet(vec3 v, vec2 yaw, vec2 pitch, vec2 spin) {
  v = vec3(yaw.x * v.x + yaw.y * v.z, v.y, yaw.x * v.z - yaw.y * v.x);
  v = vec3(v.x, pitch.x * v.y + pitch.y * v.z, pitch.x * v.z - pitch.y * v.y);
  return vec3(spin.x * v.x + spin.y * v.y, spin.x * v.y - spin.y * v.x, v.z);
}

vec4 transition(vec2 uv) {
  float w = ratio;
  float shade = clamp(shading, 0.0, 1.0);
  float s = 2.0 * smoothstep(0.0, 0.62, progress);
  bool second = s > 1.0;
  float x = second ? s - 1.0 : s;
  float a = PI * mix(x, x * x * (3.0 - 2.0 * x), 0.6);
  float f = clamp((progress - 0.5) / 0.47, 0.0, 1.0);

  float turn = clamp(tilt, 0.0, 1.0) * (smoothstep(0.0, 0.25, progress) - smoothstep(0.4, 0.8, progress));
  vec2 yaw = vec2(cos(0.45 * turn), sin(0.45 * turn));
  vec2 pitch = vec2(cos(0.55 * turn), -sin(0.55 * turn));
  float dist = 2.5 * max(w, 1.0);
  float recede = dist * 0.35 * turn;

  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(1.0, 0.0);
  // the point of the sheet held in the middle of the frame slides to the middle of the packet
  vec2 c = vec2(0.5 * w - 0.25 * w * min(s, 1.0), 0.5 - 0.25 * max(s - 1.0, 0.0));
  float reach = 0.5 * (abs(dir.x) * w + abs(dir.y)) + length(vec2(0.25 * w, 0.25)) + 0.4;
  float lift = 0.3 * smoothstep(0.0, 0.5, f);
  float turned = (dir.x < 0.0 ? 0.7 : -0.7) * f * f;
  vec2 spin = vec2(cos(turned), sin(turned));

  // the eye, the ray toward the point of the frame and the light, in the frame of the sheet,
  // where the sheet lies on the plane z = 0 and the incoming image on z = -lift
  vec3 center = vec3(vec2(0.5 * w, 0.5) + dir * reach * f * f, -recede);
  vec3 eye = vec3(0.5 * w, 0.5, dist);
  vec3 e = toSheet(eye - center, yaw, pitch, spin) + vec3(c, 0.0);
  vec3 d = toSheet(vec3(uv.x * w, uv.y, 0.0) - eye, yaw, pitch, spin);
  vec3 l = toSheet(LIGHT, yaw, pitch, spin);
  if (second) {
    e.xy = e.yx;
    d.xy = d.yx;
    l.xy = l.yx;
  }
  float h = second ? 0.5 : 0.5 * w;
  float k = second ? 0.5 * w : 1.0;
  float creased = sin(a);
  vec3 n = vec3(-creased, 0.0, cos(a));
  vec3 along = vec3(cos(a), 0.0, creased);

  vec4 col = getToColor(uv);
  if (d.z < 0.0) {
    vec3 g = e + d * (e.z + lift) / -d.z;
    col.rgb *= 1.0 - 0.7 * shade * (1.0 - f * f) * shadowAt(g, l, h, k, n, along);
  }

  float t = d.z < 0.0 ? e.z / -d.z : -1.0;
  vec3 p = e + t * d;
  float m = clamp(inside(p.xy, h, k) / (EDGE * t) + 1.0, 0.0, 1.0);
  if (t > 0.0 && m > 0.0) {
    vec4 img = topFace(second ? p.yx : p.xy, second);
    float sh = shadowAt(p, l, h, k, n, along);
    img.rgb *= (1.0 - 0.7 * shade * sh) * (1.0 - 0.5 * shade * creased * exp(-abs(h - p.x) / CREASE));
    col = mix(col, img, m);
  }

  vec3 hit = hitFlap(e, d, h, n, along);
  if (hit.x > 0.0) {
    float r = hit.y;
    // edges seen at a grazing angle are narrower on screen
    float dr = dot(along, normalize(d));
    float fore = sqrt(max(1.0 - dr * dr, 0.0025));
    float mf = clamp(min(min(r, h - r) * fore, min(hit.z, k - hit.z)) / (EDGE * hit.x) + 1.0, 0.0, 1.0);
    if (mf > 0.0) {
      bool up = dot(n, e - vec3(h, 0.0, 0.0)) > 0.0;
      vec2 st = vec2(h + r, hit.z);
      if (second) st = st.yx;
      vec4 img = up ? topFace(st, second) : back(st);
      // lit by the light, relative to the sheet lying flat
      float lit = dot(up ? n : -n, l) - l.z;
      img.rgb *= max(1.0 + 0.6 * shade * lit, 0.0) * (1.0 - 0.5 * shade * creased * exp(-abs(r) / CREASE));
      col = mix(col, img, mf);
    }
  }
  return col;
}

// Author: gre
// License: MIT
// Description: The incoming image is rebuilt as a stack of cut paper sheets, one per band of brightness: from the darkest to the lightest, each sheet slides in lifted above the stack, drops into place with a soft shadow on the sheets below, then the paper flattens into the photo
// Tags: paper, layers, cut, shadow, stylized

// @range(2, 8, 1) Number of paper sheets, one per band of brightness of the incoming image
uniform int layers; // = 5
// @range(0, 1) How much of the incoming image's colors the paper takes: 0 is plain paper in shades of the paper color
uniform float colorful; // = 0.7
// @range(0, 1) Darkness of the shadows the sheets cast on the ones below
uniform float shadow; // = 0.6
// @color Color of the lightest sheet of paper, the darker ones are shades of it
uniform vec4 paper; // = vec4(0.97, 0.94, 0.88, 1.0)

const float MAX_LAYERS = 8.0;
// part of the progress at which the last sheet lands, and longest duration of the slide of one sheet
const float STACKED = 0.74;
const float SLIDE = 0.2;
// height a sheet falls from, as the extra distance its shadow is cast at
const float LIFT = 3.0;
const vec2 SHADOW = vec2(0.012, -0.018);
// softness of the cut edges and of the shadows' edges, in brightness
const float CUT = 0.012;
const float SHADOW_CUT = 0.05;
// radius over which the brightness is softened before it is cut, so that the cuts follow smooth curves,
// and the wider one for the shadows, in frame heights
const float BLUR = 0.004;
const float SHADOW_BLUR = 0.01;
const float EDGE = 0.0015;

float luma(vec4 c) {
  return dot(c.rgb, vec3(0.299, 0.587, 0.114));
}

float plHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float grain(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(plHash(i), plHash(i + vec2(1.0, 0.0)), f.x),
    mix(plHash(i + vec2(0.0, 1.0)), plHash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

// mirrored coordinates, so that a shifted lookup never smears the frame's border
vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// brightness of the incoming image at p (whose color is c) softened over a disc of the given radius in frame heights
float softLuma(vec2 p, vec4 c, float radius, vec2 aspect) {
  vec2 r = radius / aspect;
  float l = luma(c);
  l += luma(getToColor(mirror(p + r * vec2(0.0, 1.0))));
  l += luma(getToColor(mirror(p + r * vec2(0.866, -0.5))));
  l += luma(getToColor(mirror(p + r * vec2(-0.866, -0.5))));
  return l / 4.0;
}

// coverage of sheet k of n: the whole frame for the first one, else where the softened brightness l reaches its threshold
float cut(float k, float n, float l, float soft) {
  if (k < 0.5) return 1.0;
  float thr = k / n;
  return smoothstep(thr - soft, thr + soft, l);
}

vec4 transition(vec2 uv) {
  float n = clamp(float(layers), 2.0, MAX_LAYERS);
  float sh = clamp(shadow, 0.0, 1.0);
  vec2 aspect = vec2(ratio, 1.0);
  vec2 shadowOffset = SHADOW / aspect;
  float toPhoto = smoothstep(STACKED - 0.03, 1.0, progress);

  // the incoming image where the sheets lie on the stack, and where they cast their shadow
  // (only looked up once the first sheet has landed)
  vec4 rest = getToColor(uv);
  float restLuma = 0.0;
  vec4 restShadowColor = vec4(0.0);
  float restShadow = 0.0;
  float n1 = n - 1.0;
  // duration of the slide of one sheet, short enough that at most two sheets slide at once
  float slide = min(SLIDE, 2.0 * STACKED / (n1 + 2.0));
  float spacing = (STACKED - slide) / n1;
  if (progress >= slide) {
    restLuma = softLuma(uv, rest, BLUR, aspect);
    vec2 ps = uv - shadowOffset;
    restShadowColor = getToColor(mirror(ps));
    restShadow = softLuma(ps, restShadowColor, SHADOW_BLUR, aspect);
  }

  vec4 color = getFromColor(uv);
  for (float k = 0.0; k < MAX_LAYERS; k += 1.0) {
    if (k < n) {
      float t = clamp((progress - k * spacing) / slide, 0.0, 1.0);
      if (t > 0.0) {
        float e = 1.0 - (1.0 - t) * (1.0 - t) * (1.0 - t);
        float lift = 1.0 - smoothstep(0.5, 1.0, t);
        vec2 q = (uv - 0.5) / (1.0 + 0.03 * lift) + 0.5;
        q.y -= (1.0 - e) * 1.15;
        vec2 so = shadowOffset * (1.0 + LIFT * lift);
        vec4 src = rest;
        float l = restLuma;
        float ls = restShadow;
        float shadowAlpha = restShadowColor.a;
        if (t < 1.0) {
          src = getToColor(mirror(q));
          l = softLuma(q, src, BLUR, aspect);
          vec4 cs = getToColor(mirror(q - so));
          ls = softLuma(q - so, cs, SHADOW_BLUR, aspect);
          shadowAlpha = cs.a;
        }
        float m = cut(k, n, l, CUT) * src.a * smoothstep(-EDGE, EDGE, q.y);
        float s = cut(k, n, ls, SHADOW_CUT) * shadowAlpha * smoothstep(-EDGE, EDGE, q.y - so.y);
        color.rgb *= 1.0 - sh * (1.0 - toPhoto) * (0.7 - 0.35 * lift) * s * (1.0 - m);
        // the sheet's color: a shade of paper for its band of brightness, tinted by the photo
        // (the dark bands are lifted a little, as paper is never black)
        float level = 0.25 + 0.75 * k / n1;
        vec3 plain = paper.rgb * level;
        vec3 tinted = clamp(level + 1.25 * (src.rgb - luma(src)), 0.0, 1.0);
        vec3 sheet = mix(plain, tinted, 0.9 * clamp(colorful, 0.0, 1.0));
        sheet *= 0.975 + 0.05 * grain(q * aspect * 160.0 + k * 37.0);
        color = mix(color, vec4(sheet, paper.a), m);
      }
    }
  }
  return mix(color, rest, toPhoto);
}

// Author: gre
// License: MIT
// Description: The outgoing image tears in two along a ragged line, and the halves are pulled apart to reveal the incoming one
// Tags: split, horizontal, shadow

// @range(0, 0.3) How far the tear wanders from the middle, relative to the image height
uniform float roughness; // = 0.12
// @range(0, 0.5) How much the top of each half leans away first, so that the tear opens from the top
uniform float tilt; // = 0.1
// @range(0, 0.05) Width of the white torn edge, relative to the image height
uniform float rim; // = 0.012
// @color Color of the paper fibers on the torn edges
uniform vec4 paper; // = vec4(1.0, 0.98, 0.94, 1.0)
// @color Color of the shadow cast on the incoming image
uniform vec4 shadow; // = vec4(0.0, 0.0, 0.0, 0.35)

float tri (float x) {
  return abs(fract(x) - 0.5) - 0.25;
}

// horizontal position of the tear at height y: smooth meanders...
float meander (float y) {
  return 0.5 * ratio + roughness * (0.5 * sin(y * 4.7 + 1.3) + 0.25 * sin(y * 11.3 + 4.1));
}

// ...and sharp jags
float tear (float y) {
  return meander(y) + roughness * (0.1 * sin(y * 29.0 + 0.7) + 0.35 * tri(y * 19.0 + sin(y * 7.0)) + 0.12 * tri(y * 47.0 + 0.6 * sin(y * 13.0)));
}

float fibers (float y, float seed) {
  return rim * (0.7 + 0.3 * sin(y * 37.0 + seed) + 0.4 * tri(y * 83.0 + seed));
}

// the left half (or the mirrored right half) slides out, its top leaning away first:
// from a point on screen to the point of the paper (the frame edges stay covered)
vec2 unfold (vec2 q, float away, float lean) {
  return vec2(q.x + away + lean * q.y, q.y);
}

// a torn half over bg; e: distance past the torn edge, limit: how far the fibers reach, aa: edge softness
vec4 torn (vec4 bg, vec4 col, float e, float limit, float aa) {
  vec4 c = vec4(mix(col.rgb, paper.rgb, clamp(0.5 + e / aa, 0.0, 1.0) * paper.a), col.a);
  return mix(bg, c, clamp(0.5 - (e - limit) / aa, 0.0, 1.0));
}

vec4 transition (vec2 uv) {
  float p = progress;
  float away = p * p * (0.5 * ratio + 0.1 + roughness + 2.0 * rim); // far enough to leave the frame
  float lean = tilt * p * (2.0 - p);
  float fiber = smoothstep(0.0, 0.15, p); // no torn edge on the intact image
  float aa = 0.002 * fiber + 1e-6;
  vec2 q = vec2(uv.x * ratio, uv.y);
  vec2 l = unfold(q, away, lean);
  vec2 r = unfold(vec2(ratio - q.x, q.y), away, lean);
  float el = l.x - tear(l.y); // > 0 right of the left half's torn edge
  float er = r.x - (ratio - tear(r.y)); // > 0 left of the right half's torn edge
  vec2 sq = q - vec2(0.01, 0.0);
  float dl = unfold(sq, away, lean).x - meander(sq.y);
  float dr = unfold(vec2(ratio - sq.x, sq.y), away, lean).x - (ratio - meander(sq.y));
  vec4 to = getToColor(uv);
  float sh = shadow.a * (1.0 - smoothstep(-0.02, 0.08, min(dl, dr)));
  vec4 c = vec4(mix(to.rgb, shadow.rgb, sh), to.a);
  if (r.x >= 0.0) {
    c = torn(c, getFromColor(vec2(1.0 - r.x / ratio, r.y)), er, fibers(r.y, 2.0) * 1.5 * fiber, aa);
  }
  if (l.x >= 0.0) {
    c = torn(c, getFromColor(vec2(l.x / ratio, l.y)), el, fibers(l.y, 0.0) * fiber, aa);
  }
  return c;
}

// Author: gre
// License: MIT
// Description: The camera tracks sideways past a dark, out-of-focus pillar standing close to the lens: the pillar rushes across the frame while the images far behind it drift slowly the same way with a slight push in, and the cut to the incoming image happens hidden behind it
// Tags: push, parallax, depth, camera, wipe, directional

// @param Direction in which everything moves, snapped to its main axis (left, right, up or down)
uniform vec2 direction; // = vec2(-1.0, 0.0)
// @range(0, 0.25) How far each image drifts behind the pillar, as a part of the frame
uniform float parallax; // = 0.1
// @range(0.1, 1) Width of the pillar, as a part of the shorter side of the frame
uniform float width; // = 0.45
// @range(0, 1) How out of focus the pillar is, and how much it blurs as it rushes past
uniform float blur; // = 0.5
// @color Color of the pillar, lit from the side it moves toward
uniform vec4 pillar; // = vec4(0.2, 0.17, 0.15, 1.0)

// mirror the coordinates back into the frame
vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

vec4 transition(vec2 uv) {
  // the main axis of the direction, to the left when there is none
  vec2 d = abs(direction.x) >= abs(direction.y)
    ? vec2(direction.x > 0.0 ? 1.0 : -1.0, 0.0)
    : vec2(0.0, direction.y > 0.0 ? 1.0 : -1.0);
  // u: position along the motion in frame heights, from 0 on the side everything comes from to len
  float len = d.x != 0.0 ? ratio : 1.0;
  float u = (dot(uv - 0.5, d) + 0.5) * len;
  // v: across the motion, 0 to 1
  float v = d.x != 0.0 ? uv.y : uv.x;

  float p = progress;
  // the camera's travel: eased in and out, with a little linear motion so it never stands still
  float e = 0.7 * p * p * (3.0 - 2.0 * p) + 0.3 * p;
  float speed = 0.7 * 6.0 * p * (1.0 - p) + 0.3;

  // the images, far away, drift slowly: the outgoing one leaves the way it moves, the incoming one
  // comes from the opposite side, so each is exactly in place at its end of the transition. Each
  // is scaled up just enough that its drift never reaches past its edges
  float drift = clamp(parallax, 0.0, 0.25);
  float da = drift * e;
  float db = drift * (1.0 - e);
  vec4 a = getFromColor(mirror(0.5 + (uv - 0.5) * (1.0 - 2.0 * da) - d * da));
  vec4 b = getToColor(mirror(0.5 + (uv - 0.5) * (1.0 - 2.0 * db) + d * db));

  // the pillar, close to the lens, crosses the whole frame. Its edges are soft: out of focus, and
  // smeared by its own speed on screen, but it starts and ends fully out of frame
  float w = clamp(width, 0.1, 1.0) * min(ratio, 1.0);
  float bl = clamp(blur, 0.0, 1.0);
  float defocus = w * (0.02 + 0.08 * bl);
  // the motion blur follows the pillar's speed on screen, about len + w frame heights per progress
  float smear = 0.035 * bl * (len + w);
  float soft = min(defocus + smear * speed, 0.8 * w);
  // at both ends (where the speed is 0.3) the pillar's blurred edge just touches the frame's edge
  float reach = 0.5 * w + 0.5 * min(defocus + smear * 0.3, 0.8 * w) + 0.001;
  float c = -reach + (len + 2.0 * reach) * e;
  // x: across the pillar, -1 on its leading edge to 1 on its trailing edge
  float x = (c - u) / (0.5 * w);
  float edge = soft / w;
  float cover = 1.0 - smoothstep(1.0 - edge, 1.0 + edge, abs(x));
  if (cover <= 0.0) return u < c ? b : a;

  // the cut happens behind the pillar's opaque core, as a dissolve across it, so a see-through
  // pillar never shows a hard seam
  vec4 bg = mix(a, b, smoothstep(-0.8, 0.8, x));

  // the pillar's shading: a rounded post, lit from the side it moves toward, darker toward one end,
  // with a faint rim where the light of the images behind it wraps around its edges
  float xs = clamp(x, -1.0, 1.0);
  float n = sqrt(max(1.0 - xs * xs, 0.0));
  float lambert = max(0.5 * n - 0.85 * xs, 0.0);
  float spec = pow(max(0.6 * n - 0.8 * xs, 0.0), 12.0);
  float rim = smoothstep(0.6, 1.0, abs(xs)) * (1.0 - cover);
  vec4 side = xs < 0.0 ? a : b;
  vec3 lit = pillar.rgb * (0.35 + 1.1 * lambert) * (0.6 + 0.5 * v) + 0.12 * spec;
  lit += 0.25 * rim * side.rgb * side.a;

  // the pillar over the images, premultiplied
  float pa = pillar.a * cover;
  vec4 col = vec4(lit * pa + bg.rgb * bg.a * (1.0 - pa), pa + bg.a * (1.0 - pa));
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: A row of perforation holes is punched across the outgoing picture along a gentle wave; the lower half tears away along the holes from left to right, bending down behind the tear and dropping off, then the upper half tears off the top edge from right to left and falls the same way, revealing the incoming picture
// Tags: paper, tear, gravity

// @range(0, 0.12) Height of the wave of the perforation line, in frame heights
uniform float wave; // = 0.05

const float SPACING = 0.03;
const float HOLE = 0.0065;
const float RIM = 0.0025;
const vec2 SHADOW = vec2(0.02, -0.03);

float aa(float d) { return clamp(d * 400.0 + 1.0, 0.0, 1.0); }
float frameDist(vec2 S) { vec2 d = min(S, vec2(ratio, 1.0) - S); return min(d.x, d.y); }
float line(float x) { return 0.5 + wave * sin(x * 4.0 + 1.0); }
float drop(float t) { t = clamp(t, 0.0, 1.0); return t * t; }

// sheet point and bend angle seen at Q, the free part (on side dir of the tear front T) swung down about T;
// the swing grows with the screen angle around T, which keeps the map one-to-one and needs no solve
vec3 bend(vec2 Q, vec2 T, float an, float dir) {
  vec2 d = Q - T;
  d.x *= dir;
  float r = length(d);
  float a = an * smoothstep(0.0, 0.25, r) * smoothstep(-0.2, 2.2, atan(d.x, -d.y));
  float c = cos(a), s = sin(a);
  return vec3(T + vec2(dir * (d.x * c - d.y * s), d.y * c + d.x * s), a);
}

float punch(float x) {
  float t = 0.12 * x / ratio;
  return smoothstep(t, t + 0.05, progress);
}

// side: 1 for the upper half, -1 for the lower one
float lineDist(vec2 S, float side) { return side * (S.y - line(S.x)); }

// the torn edge whitens where the lower front at tornX has passed
vec4 drawPiece(vec4 col, vec3 B, float side, float tornX) {
  vec2 S = B.xy;
  float dl = lineDist(S, side);
  float cx = (floor(S.x / SPACING) + 0.5) * SPACING;
  float h = length(vec2(S.x - cx, dl)) - HOLE * punch(cx);
  float m = aa(dl) * aa(h) * aa(frameDist(S));
  if (m <= 0.0) return col;
  vec4 c = getFromColor(clamp(vec2(S.x / ratio, S.y), 0.0, 1.0));
  c.rgb *= 1.0 - 0.22 * sin(min(B.z, 1.5));
  float rim = max((1.0 - smoothstep(0.0, RIM, h)) * punch(cx), (1.0 - smoothstep(0.0, RIM, dl)) * smoothstep(0.0, 0.02, tornX - S.x));
  c.rgb = mix(c.rgb, vec3(0.93, 0.91, 0.87), 0.6 * rim);
  return mix(col, c, m);
}

float shadowOf(vec3 B, float side) {
  return smoothstep(-0.03, 0.03, min(lineDist(B.xy, side), frameDist(B.xy))) * smoothstep(0.0, 0.25, B.z);
}

vec4 transition(vec2 uv) {
  float p = progress, R = ratio;
  vec2 Q = vec2(uv.x * R, uv.y);
  float k1 = smoothstep(0.06, 0.44, p);
  float k2 = smoothstep(0.44, 0.82, p);
  // each half drops only once its tear front has left the frame
  float d1 = drop((p - 0.4) / 0.3);
  float d2 = drop((p - 0.78) / 0.22);
  float fall1 = 2.4 * d1, fall2 = 2.6 * d2;
  float an1 = 1.1 * k1 + 0.5 * d1;
  float an2 = 1.1 * k2 + 0.5 * d2;
  float x1 = R * (k1 * 1.1 - 0.05);
  vec2 T1 = vec2(x1, line(x1));
  vec2 T2 = vec2(R * (1.05 - 1.1 * k2), 1.0);

  vec4 col = getToColor(uv);
  float sh = max(
    shadowOf(bend(Q - SHADOW + vec2(0.0, fall1), T1, an1, -1.0), -1.0),
    shadowOf(bend(Q - SHADOW + vec2(0.0, fall2), T2, an2, 1.0), 1.0));
  col.rgb *= 1.0 - 0.5 * sh;

  col = drawPiece(col, bend(Q + vec2(0.0, fall1), T1, an1, -1.0), -1.0, T1.x);
  col = drawPiece(col, bend(Q + vec2(0.0, fall2), T2, an2, 1.0), 1.0, T1.x);
  return col;
}

// Author: Rich Harris
// License: MIT
// Description: The incoming image appears through blobs of Perlin noise
// Tags: noise, dissolve

// @param Scale of the noise; higher values make smaller blobs
uniform float scale; // = 4.0
// @param Softness of the blob edges
uniform float smoothness; // = 0.01

// @param Random seed
uniform float seed; // = 12.9898

// http://byteblacksmith.com/improvements-to-the-canonical-one-liner-glsl-rand-for-opengl-es-2-0/
float random(vec2 co)
{
    float a = seed;
    float b = 78.233;
    float c = 43758.5453;
    float dt= dot(co.xy ,vec2(a,b));
    float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

// 2D Noise based on Morgan McGuire @morgan3d
// https://www.shadertoy.com/view/4dS3Wd
float noise (in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f*f*(3.0-2.0*f);

    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}

vec4 transition (vec2 uv) {
  vec4 from = getFromColor(uv);
  vec4 to = getToColor(uv);
  float n = noise(uv * scale);

  float p = mix(-smoothness, 1.0 + smoothness, progress);
  float lower = p - smoothness;
  float higher = p + smoothness;

  float q = smoothstep(lower, higher, n);

  return mix(
    from,
    to,
    1.0 - q
  );
}

// Author: gre
// License: MIT
// Description: The outgoing image washes out to a blank cream card, then the incoming image develops on it like an instant photo: shadows first, faint and tinted, then its contrast and colors come up and it settles
// Tags: fade, color, photo, retro

// @color Color of the blank card between the two images
uniform vec4 card; // = vec4(0.93, 0.91, 0.85, 1.0)
// @range(0, 1) How long the outgoing image takes to wash out (from 10% to 70% of the transition)
uniform float wash; // = 0.35
// @range(0, 1) Strength of the cyan and magenta cast while the image develops
uniform float tint; // = 0.8

vec3 saturation(vec3 c, float s) {
  float lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
  return mix(vec3(lum), c, s);
}

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  float p = progress;

  // the card only shows where the images are: it takes the alpha of the outgoing image, then the incoming one's
  float split = mix(0.1, 0.7, clamp(wash, 0.0, 1.0));
  float cardAlpha = card.a * mix(a.a, b.a, smoothstep(0.6 * split, split + 0.1, p));
  vec3 cardColor = card.rgb * cardAlpha;

  float w = smoothstep(0.0, split, p);
  float fromLum = dot(a.rgb, vec3(0.2126, 0.7152, 0.0722));
  float wl = clamp(w * (1.0 + 0.5 * fromLum), 0.0, 1.0);
  vec3 washed = mix(a.rgb, mix(vec3(fromLum), a.rgb, 0.4), w) * a.a;
  vec3 outgoing = mix(washed, cardColor, wl);
  float outAlpha = mix(a.a, cardAlpha, wl);

  float x = clamp((p - split) / max(1.0 - split, 1e-3), 0.0, 1.0);
  float d = 1.0 - pow(1.0 - x, 1.5);
  float lum = dot(b.rgb, vec3(0.2126, 0.7152, 0.0722));
  float dev = clamp((d - 0.45 * lum) / 0.55, 0.0, 1.0);
  dev = dev * dev * (3.0 - 2.0 * dev);
  float early = 1.0 - smoothstep(0.2, 0.95, d);
  vec3 tinted = saturation(b.rgb, smoothstep(0.3, 1.0, d));
  tinted = mix(vec3(0.6), tinted, mix(0.55, 1.0, d));
  vec3 tone = mix(vec3(-0.2, 0.06, 0.1), vec3(0.12, -0.1, 0.06), smoothstep(0.15, 0.6, lum));
  tinted += tone * tint * early;
  vec3 incoming = mix(cardColor, clamp(tinted, 0.0, 1.0) * b.a, dev);
  float inAlpha = mix(cardAlpha, b.a, dev);

  vec3 color = p < split ? outgoing : incoming;
  float alpha = p < split ? outAlpha : inAlpha;
  if (alpha <= 0.0) return vec4(0.0);
  return vec4(clamp(color / alpha, 0.0, 1.0), alpha);
}

// Author: gre
// License: MIT
// Description: The outgoing image is pinched at one point like a handkerchief: its sides drop and swing in under the pinch, gathering into hanging pleats, then it is let go and falls down out of the frame, revealing the incoming image behind its shadow
// Tags: fabric, fold, gravity, shadow

// Point where the cloth is pinched
uniform vec2 center; // = vec2(0.5, 0.8)
// @range(4, 24, 1) Number of pleats hanging from the pinch
uniform float pleats; // = 9.0
// @range(0, 1) Depth of the pleats and of their shading
uniform float depth; // = 0.8
// @range(0, 1) How far the hanging cloth swings before it settles
uniform float swing; // = 0.5
// @range(0, 1) Darkness of the soft shadow cast on the incoming image
uniform float shadow; // = 0.6

const float PI = 3.14159265;

// width of the hanging fan (1 = flat picture, small = cloth hanging straight down) at distance r from the pinch
float fanWidth(float t, float r) {
  // the far cloth swings a longer arc and arrives later, so the hem lags behind in a curve
  float a = clamp((t - 0.03 - 0.1 * r) / 0.45, 0.0, 1.0);
  float s = a * a * (3.0 - 2.0 * a) + 0.15 * sin(PI * a) * a * a;
  float m = smoothstep(0.5, 1.0, t);
  return mix(1.0, 0.3, s) + 0.12 * m * min(r, 1.0);
}

float pleatPhase(float th) {
  return floor(pleats + 0.5) * th + 0.8 * sin(3.0 * th + 1.0) + 0.5 * sin(5.0 * th + 2.0);
}

// angle of d away from straight down below the pinch, in -PI..PI
float hangAngle(vec2 d, float sway) {
  float th = abs(d.x) + abs(d.y) > 0.0 ? atan(d.x, -d.y) : 0.0;
  return mod(th - sway + PI, 2.0 * PI) - PI;
}

// xy: point of the outgoing image (aspect units), z: gathering (0 flat .. 1 hanging), w: distance to the fan edge
vec4 cloth(vec2 d, float t, vec2 P, float sway) {
  float r = length(d);
  float th = hangAngle(d, sway);
  float w = fanWidth(t, r);
  float th0 = th / w;
  float A = clamp((1.0 - w) / 0.7, 0.0, 1.0);
  // pleats fold the angle back and forth, so the extra width hides in the folds
  // (not at the fan's edges, which stay on the image's top edge above the pinch)
  float k = pleatPhase(th0);
  float th1 = th0 + 0.9 * A * sin(k) * smoothstep(0.0, 0.3, PI - abs(th0)) / floor(pleats + 0.5);
  float r0 = r * (1.0 + 0.12 * A * (0.5 - 0.5 * cos(k)));
  vec2 o = P + r0 * vec2(sin(th1), -cos(th1));
  return vec4(o, A, (PI * w - abs(th)) * r);
}

vec4 transition(vec2 uv) {
  float t = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 P = center * asp;
  float m = clamp((t - 0.52) / 0.48, 0.0, 1.0);
  vec2 C = P - vec2(0.0, m * m * (P.y + 0.25));
  float a = clamp((t - 0.1) / 0.45, 0.0, 1.0);
  float sway = swing * (0.22 * sin(2.6 * PI * a) * (1.0 - a) * a * 3.0 - 0.08 * m);

  vec2 d = uv * asp - C;
  float r = length(d);
  vec4 c = cloth(d, t, P, sway);
  vec2 src = c.xy / asp;
  vec2 bd = min(src, 1.0 - src) * asp;
  // antialiased edge (no edge on the frame's border at the start)
  float e = 0.002 * (1.0 + 2.0 * c.z) * min(1.0, 30.0 * t) + 1e-5;
  float cov = clamp(min(bd.x, bd.y) / e + 0.5, 0.0, 1.0);
  // the opening above the pinch, filtered over the pixel: x is the distance to the seam
  // straight above the pinch and h the opening's half width, so nothing opens while the fan is flat
  float w = fanWidth(t, r);
  float h = PI * (1.0 - w) * r;
  float x = c.w + h;
  cov *= 1.0 - clamp((min(x + 0.5 * e, h) - max(x - 0.5 * e, -h)) / e, 0.0, 1.0);

  vec4 img = vec4(0.0);
  if (cov > 0.0) {
    img = getFromColor(clamp(src, 0.0, 1.0));
    float th = hangAngle(d, sway) / w;
    float N = floor(pleats + 0.5);
    float k = pleatPhase(th);
    float amp = 0.6 + 0.4 * sin(2.0 * th + 2.5) * sin(3.0 * th + 0.7);
    float A = sqrt(c.z) * depth * amp * smoothstep(0.0, 0.25, r);
    float aw = 0.003 * N / max(r * w, 1e-3) + 0.05;
    float face = clamp(sin(k) / aw, -1.0, 1.0);
    float valley = pow(0.5 - 0.5 * cos(k), 3.0);
    float shade = 1.0 + A * (0.45 * face * (0.4 + 0.6 * abs(sin(k))) - 0.55 * valley);
    shade += 0.2 * depth * c.z * (1.0 - smoothstep(0.0, 0.06, r));
    shade -= 0.15 * depth * c.z * smoothstep(0.2, 1.0, r);
    shade -= 0.35 * depth * sqrt(c.z) * exp(-c.w / 0.025);
    img.rgb *= max(shade, 0.0);
    if (cov >= 1.0) return img;
  }

  vec4 bg = getToColor(uv);
  float lift = sin(PI * t);
  if (lift > 0.0) {
    vec4 cs = cloth(d - vec2(0.03, -0.035), t, P, sway);
    vec2 ss = cs.xy / asp;
    vec2 sb = min(ss, 1.0 - ss) * asp;
    float sh = smoothstep(-0.05, 0.04, min(min(sb.x, sb.y), cs.w));
    // and a darker contact shade in the opening above the pinch, so it reads as a fold, not a crack
    float edge = (hangAngle(d, sway) < 0.0 ? -PI : PI) * w * 0.999 + sway;
    vec2 es = cloth(r * vec2(sin(edge), -cos(edge)), t, P, sway).xy / asp;
    vec2 eb = min(es, 1.0 - es) * asp;
    float gap = (1.0 - m * m) * smoothstep(-0.01, 0.0, -c.w) * (1.0 - smoothstep(0.0, 0.05, -c.w));
    gap *= smoothstep(-0.01, 0.01, min(eb.x, eb.y));
    bg.rgb *= (1.0 - shadow * 0.55 * sh * lift) * (1.0 - shadow * 0.55 * gap);
  }
  return mix(bg, img, cov);
}

// Author: Mr Speaker
// License: MIT
// Description: A spinning pinwheel reveals the incoming image
// Tags: pinwheel, radial, rotate

// @param Rotation speed
uniform float speed; // = 2.0

vec4 transition(vec2 uv) {

  vec2 p = uv.xy / vec2(1.0).xy;

  float circPos = atan(p.y - 0.5, p.x - 0.5) + progress * speed;
  float modPos = mod(circPos, 3.1415 / 4.);
  // starts just below 0 so the sector edges are not drawn on the first frame
  float signed = sign(progress * (3.1415 / 4. + 0.01) - 0.01 - modPos);

  return mix(getToColor(p), getFromColor(p), step(signed, 0.5));

}

// Author: gre
// License: MIT
// Description: A line sweeps across the frame and drags the outgoing image's pixels behind it as long streaks, which shorten as it goes and reveal the incoming image
// Tags: smear, streaks, directional, chromatic

// @param Direction in which the line sweeps
uniform vec2 direction; // = vec2(1.0, 0.0)
// @range(0, 1) Length of the streaks at the middle of the sweep, as a part of the frame
uniform float stretch; // = 0.45
// @range(0, 1) Amount of RGB split along the streaks
uniform float chroma; // = 0.5
// @range(0, 0.2) Softness of the line and of the streaks' ends, as a part of the frame
uniform float softness; // = 0.03
// @range(0, 1) How much the streaks jitter, each row at its own length
uniform float jitter; // = 0.5

float hash(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

// smooth max with a compact support: exactly max(x, y) when they are k apart
float smax(float x, float y, float k) {
  float h = max(k - abs(x - y), 0.0) / k;
  return max(x, y) + h * h * k * 0.25;
}

// position s along the sweep (0 to 1 across the frame) to a frame coordinate
vec2 at(vec2 uv, float s0, float s, vec2 d, float ext) {
  return clamp(uv + d * (s - s0) * ext, 0.0, 1.0);
}

vec4 transition(vec2 uv) {
  vec2 d = normalize(direction + vec2(1e-6, 0.0));
  float ext = abs(d.x) + abs(d.y);
  float s = 0.5 + dot(uv - 0.5, d) / ext;
  // rows across the streaks (about one per pixel line), in frame heights
  vec2 n = vec2(-d.y, d.x);
  float t = dot((uv - 0.5) * vec2(ratio, 1.0), n);
  float row = floor(t * 540.0);
  float clump = floor(t * 60.0);
  float rnd = 0.6 * hash(row + 17.0) + 0.4 * hash(clump + 311.0);

  float p = progress;
  float k = softness + 1e-4;
  // the line starts and ends at rest just beyond the frame, past its soft edge, so both ends are exact;
  // it enters at once and slows down a little toward the end
  float margin = k + 0.002;
  float a = mix(-margin, 1.0 + margin, mix(p, p * p * (3.0 - 2.0 * p), 0.5));

  // the streaks are longest when the line crosses the middle and vanish as it reaches the edges,
  // so they never repeat the frame's own border (often dark, or letterboxing)
  float h = clamp(4.0 * a * (1.0 - a), 0.0, 1.0);
  float len = stretch * h * (1.0 - 0.6 * jitter * rnd);
  float split = 0.02 * chroma * h;

  // ahead of the line the outgoing image is intact; behind it, each pixel repeats the pixel at the line
  vec4 fr = getFromColor(at(uv, s, smax(s, a + split, k), d, ext));
  vec4 fg = getFromColor(at(uv, s, smax(s, a, k), d, ext));
  vec4 fb = getFromColor(at(uv, s, smax(s, a - split, k), d, ext));
  vec4 streak = vec4(fr.r, fg.g, fb.b, fg.a);
  float behind = step(s, a);
  streak.rgb *= 1.0 + 0.06 * jitter * h * (hash(row * 3.0 + 5.0) - 0.5) * behind;

  float w = smoothstep(len - k, len + k, a - s);
  return mix(streak, getToColor(uv), w);
}

// Author: gre
// License: MIT
// Description: Both images pixelate, crossfade, then sharpen again
// Tags: pixelate, blend
// forked from https://gist.github.com/benraziel/c528607361d90a072e98

// @param Number of squares at the strongest pixelation
uniform ivec2 squaresMin; // = ivec2(20)
// @param Number of pixelation steps; 0 for a continuous effect
uniform int steps; // = 50

vec4 transition(vec2 uv) {
  float d = min(progress, 1.0 - progress);
  float dist = steps>0 ? ceil(d * float(steps)) / float(steps) : d;
  vec2 squareSize = 2.0 * dist / vec2(squaresMin);
  vec2 p = dist>0.0 ? (floor(uv / squareSize) + 0.5) * squareSize : uv;
  return mix(getFromColor(p), getToColor(p), progress);
}

// Author: gre
// License: MIT
// Description: A flowing plasma of sine waves, as in the old demos, draws moving bands through which the incoming image spreads like tendrils, with a glowing edge
// Tags: wipe, plasma, organic, glow

// @range(0.5, 10) Size of the plasma: higher values make more, thinner bands
uniform float scale; // = 3.0
// @range(0, 0.5) Softness of the band edges
uniform float smoothness; // = 0.1
// @range(0, 1) How much the plasma flows during the transition (at most 1, so a revealed area never goes back)
uniform float flow; // = 1.0
// @color Color of the glow along the edges
uniform vec3 edgeColor; // = vec3(1.0, 0.45, 0.9)
// @range(0, 2) Strength of the glow along the edges
uniform float edgeStrength; // = 0.6

const float PI = 3.14159265;

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);

  // measured in square pixels, so the waves are not stretched
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0) * max(scale, 0.0) * 2.0 * PI;
  // the phase of the waves; the folded plasma below then changes by at most 0.9 * flow per
  // unit of progress, slower than the threshold, so the reveal never goes back
  float t = clamp(flow, 0.0, 1.0) * progress * 0.5;
  float v = sin(p.x * 0.6 + t)
    + sin(p.y * 0.8 - t * 0.8)
    + sin((p.x * 0.5 + p.y * 0.7) * 0.7 + t * 0.6)
    + sin(length(p - vec2(0.15, -0.1) * max(scale, 0.0) * 2.0 * PI) * 0.9 - t * 1.2);
  v = abs(fract(v * 0.25 + 0.5) * 2.0 - 1.0);

  // the soft edge is fully below every band at the start and above every band at the end
  float s = max(smoothness, 0.001);
  float threshold = mix(-s, 1.0 + s, progress);
  float m = 1.0 - smoothstep(threshold - s, threshold + s, v);

  // mixed premultiplied, so transparent images do not bleed their color
  vec4 col = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
  if (col.a <= 0.0) return vec4(0.0);
  // a light along the edge, adding nothing to the alpha
  float glow = 4.0 * m * (1.0 - m) * max(edgeStrength, 0.0);
  return vec4(col.rgb / col.a + edgeColor * glow, col.a);
}

// Author: gre
// License: MIT
// Description: A plus-shaped cross grows from the center and widens its arms until the incoming image fills the frame
// Tags: shape, wipe, cross, plus

// @range(0, 0.1) Softness of the cross's edge
uniform float smoothness; // = 0.01
// @param Close four corner rectangles in toward the middle instead
uniform bool reverse; // = false

float boxDist (vec2 p, vec2 halfSize) {
  vec2 d = abs(p) - halfSize;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float plus (vec2 q, float t, float s) {
  vec2 frame = vec2(0.5 * ratio, 0.5);
  float k = min(frame.x, frame.y);
  // The arms start equally thick, then widen with the frame's proportions,
  // so the four corners left uncovered vanish together
  vec2 halfWidth = k * t + (frame - k) * t * t;
  float halfLength = 3.0 * max(frame.x, frame.y) * t;
  float d = min(boxDist(q, vec2(halfLength, halfWidth.y)), boxDist(q, vec2(halfWidth.x, halfLength)));
  // The soft edge slides from outside to inside the cross, so nothing shows at
  // t = 0 and everything at t = 1, whatever the softness
  return 1.0 - smoothstep(0.0, s, d + s * (1.0 - t));
}

vec4 transition (vec2 uv) {
  // Measured in square pixels, so the cross is not stretched
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
  float s = max(smoothness, 0.001);
  float m = reverse ? 1.0 - plus(q, 1.0 - progress, s) : plus(q, progress, s);
  return mix(getFromColor(uv), getToColor(uv), m);
}

// Author: bobylito
// License: MIT
// Description: The incoming image appears through growing polka dots
// Tags: dots, pattern
const float SQRT_2 = 1.414213562373;
// @param Number of dots across the image
uniform float dots; // = 20.0
uniform vec2 center; // = vec2(0, 0)

vec4 transition(vec2 uv) {
  bool nextImage = distance(fract(uv * dots), vec2(0.5, 0.5)) < ( progress / distance(uv, center));
  return nextImage ? getToColor(uv) : getFromColor(uv);
}

// Author: gre
// License: MIT
// Description: The incoming image pops in as a rounded card over the outgoing one, with an elastic overshoot: too big, a bit small, then it settles into the full frame as its corners square off
// Tags: pop, scale, zoom, elastic, bounce, shadow

// @param Point of the frame the incoming image pops from
uniform vec2 center; // = vec2(0.5, 0.5)
// @range(0, 1.5) How far the card overshoots (too big, then a bit small) before it settles
uniform float bounce; // = 1.0
// @range(0, 0.5) Corner radius of the card while it pops, relative to its shorter side
uniform float corner; // = 0.12
// @range(0, 1) Darkness of the drop shadow the card casts on the outgoing image
uniform float shadow; // = 0.5

const float PI = 3.141592653589793;

float roundedBox(vec2 p, vec2 b, float r) {
  vec2 q = abs(p) - b + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

vec4 transition(vec2 uv) {
  float t = progress;
  // scale of the card: an ease-out, plus a damped spring that overshoots and lands exactly at t = 1
  float easeOut = 1.0 - (1.0 - t) * (1.0 - t) * (1.0 - t);
  float spring = 1.0 - exp(-1.5 * t) * cos(2.5 * PI * t) * (1.0 - t);
  float s = mix(easeOut, spring, bounce);

  vec2 asp = vec2(ratio, 1.0);
  float side = min(ratio, 1.0);
  vec2 cardCenter = center + (0.5 - center) * s;
  vec2 halfSize = 0.5 * s * asp;
  float r = corner * s * side * (1.0 - t);
  float aa = 0.002;
  // the edge is pushed out by one antialiasing width, so at t = 1 the card covers the whole frame
  float d = roundedBox((uv - cardCenter) * asp, halfSize, r) - aa;
  float cover = clamp(0.5 - d / aa, 0.0, 1.0) * smoothstep(0.0, 0.08, t);

  float k = min(s, 1.0) * side;
  float blur = 0.05 * k + 1e-4;
  vec2 offset = vec2(0.0, -0.03 * k);
  float ds = roundedBox((uv - cardCenter - offset) * asp, halfSize, r);
  float shade = shadow * (1.0 - smoothstep(-blur, blur, ds)) * smoothstep(0.0, 0.15, t);

  vec4 a = getFromColor(uv);
  // the shadow darkens the outgoing image, it does not change its alpha (no shadow on transparent areas)
  a.rgb *= 1.0 - shade;
  // clamped: only the antialiased rim, one pixel or two outside the card, reads past the edge
  vec4 b = getToColor(clamp((uv - center) / max(s, 1e-4) + center, 0.0, 1.0));
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), cover);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The incoming image is pasted over the outgoing one as a poster, sheet after sheet: each wet sheet drops onto the wall hanging loose from its top edge with a soft shadow, then a brush smooths it on from top to bottom, leaving wrinkles and air bubbles that flatten out and seams that fade as the paste dries
// Tags: paper, poster, panels, wipe, shadow, 3d

// @range(2, 8) Number of poster sheets pasted side by side, from left to right
uniform float sheets; // = 4.0
// @range(0, 1) How wrinkled, blistered and billowing the wet paper is before the brush smooths it flat
uniform float wrinkles; // = 0.6

const float AA = 0.0015;
// length of the bend of a loose sheet just below its pasted part, in frame heights
const float ARC = 0.18;
// the last sheet is brushed on at this progress, then the paste dries until the end
const float END = 0.86;
// each sheet starts this share of a sheet's duration after the previous one
const float STAGGER = 0.45;
// share of a sheet's duration spent unfolding its top onto the wall, before the brush
const float UNFOLD = 0.22;
// length of paper hanging unfolded below the brush, in frame heights; the rest is still folded up behind it
const float FLAP = 0.34;
// how far a sheet overlaps the previous one, in frame widths
const float OVERLAP = 0.006;
// strength of the perspective: how much nearer things grow, per frame height of distance from the wall
const float PERSPECTIVE = 1.2;
// direction towards the light: from the upper left, in front of the wall
const vec3 LIGHT = vec3(-0.25, 0.5, 0.83);
const float RELIEF = 2.5;

float ppHash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float ppNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(ppHash(i), ppHash(i + vec2(1.0, 0.0)), f.x),
    mix(ppHash(i + vec2(0.0, 1.0)), ppHash(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

vec2 ppFold(vec2 p) {
  return 1.0 - abs(1.0 - mod(p, 2.0));
}

// state of sheet k out of n:
// x = height of the brushed edge in the middle of the sheet, y = how much higher that edge is at the sides of the sheet
// (the brush works from the middle outwards), z = angle at which the loose paper leaves the wall, w = its unfolded length
vec4 ppSheet(float k, float n) {
  float dur = END / (1.0 + (n - 1.0) * STAGGER);
  float t = (progress - k * STAGGER * dur) / dur;
  float a = clamp(t / UNFOLD, 0.0, 1.0);
  a = a * a * (3.0 - 2.0 * a);
  float b = max((t - UNFOLD) / (1.0 - UNFOLD), 0.0);
  float f = b < 0.2 ? b * b * 2.5 : b - 0.1;
  float front = 1.0 + 2.0 * AA - f * 1.12 / 0.9;
  float theta = mix(1.35, 0.6, a) - 0.15 * smoothstep(0.0, 0.4, b) + 0.1 * sin(b * 10.0) * (1.0 - smoothstep(0.0, 0.6, b));
  return vec4(front, 0.035 * a, theta, FLAP * a);
}

float ppWrinkle(vec2 q, float k) {
  float a = 1.0 - abs(2.0 * ppNoise(q * vec2(12.0, 2.5) + vec2(k * 13.1, k * 5.7)) - 1.0);
  float b = ppNoise(q * vec2(22.0, 6.0) + vec2(k * 7.3 + 4.0, 2.0));
  return 0.004 * a * a + 0.0015 * b;
}

// relief of the wet paper of sheet k at q (aspect-corrected, on the sheet laid flat): returns its slope.
// Wrinkles flatten with `fresh`; bubbles swell where the brush has just passed, then are pushed flat.
vec2 ppRelief(vec2 q, float k, float fresh, vec4 st, float x0, float x1) {
  float h0 = ppWrinkle(q, k);
  vec2 g = vec2(ppWrinkle(q + vec2(0.002, 0.0), k) - h0, ppWrinkle(q + vec2(0.0, 0.002), k) - h0) * (fresh / 0.002);
  for (int j = 0; j < 3; j++) {
    float fj = float(j);
    vec4 h = vec4(ppHash(vec2(k, fj)), ppHash(vec2(fj, k + 11.0)), ppHash(vec2(k + 5.0, fj + 3.0)), ppHash(vec2(fj + 7.0, k + 2.0)));
    vec2 c = vec2(mix(x0, x1, 0.2 + 0.6 * h.z) * ratio, 0.12 + 0.76 * h.w);
    float e = 0.6 * (2.0 * h.z - 1.0);
    float past = c.y - st.x - st.y * e * e;
    float swell = smoothstep(0.0, 0.08, past) * (1.0 - smoothstep(0.1, 0.55, past));
    float r = (0.03 + 0.03 * h.x) * (0.55 + 0.45 * swell);
    vec2 v = q - c;
    float u = max(1.0 - dot(v, v) / (r * r), 0.0);
    // height 0.12 r (1 - |v|²/r²)²
    g -= v * (0.48 / r) * u * swell * step(0.5, h.y + 0.25 * fj);
  }
  return g;
}

// the loose paper of a sheet, hanging from its brushed edge: it leaves the wall at angle theta, bends down over ARC,
// then hangs straight down to a fold. Returns (coverage with edges of half width w, x and height on the sheet laid flat,
// distance from the wall).
vec4 ppLoose(vec2 p, vec4 st, float x0, float x1, float xl, float xr, float w, float topShift) {
  float th = st.z;
  float c = th / ARC;
  float sinT = sin(th);
  float cosT = cos(th);
  float d1 = sinT / c;
  float x = p.x;
  float h = 0.0;
  float d = 0.0;
  float s = 0.0;
  float z = 0.0;
  float y = p.y;
  // the sheet is seen in perspective, from the middle of the frame: find where it is from where it would be on the wall
  for (int i = 0; i < 3; i++) {
    float e = clamp((x - x0) / (x1 - x0) * 2.0 - 1.0, -1.0, 1.0);
    h = st.x + st.y * e * e;
    d = h - y;
    s = (th - asin(clamp(sinT - c * clamp(d, 0.0, d1), -1.0, 1.0))) / c + max(d - d1, 0.0) + min(d, 0.0);
    z = (cos(th - c * clamp(s, 0.0, ARC)) - cosT) / c;
    x = 0.5 + (p.x - 0.5) * (1.0 - PERSPECTIVE * z);
    y = 0.5 + (p.y - 0.5) * (1.0 - PERSPECTIVE * z);
  }
  y = min(h, 1.0) - s;
  float wx = w / ratio;
  float cov = smoothstep(-AA, AA, d + topShift) * smoothstep(-w, w, y) * smoothstep(-w, w, st.w - s) * smoothstep(-wx, wx, x - xl) * smoothstep(-wx, wx, xr - x);
  return vec4(cov, x, y, z);
}

vec4 transition(vec2 uv) {
  float n = floor(clamp(sheets, 2.0, 8.0) + 0.5);
  float creases = clamp(wrinkles, 0.0, 1.0);
  float wet = 1.0 - smoothstep(END, 1.0, progress);
  float relief = creases * wet;
  float aax = AA / ratio;
  float cover = 0.0; // coverage of the incoming image
  float lit = 0.0; // its shading, premultiplied by the coverage
  float wall = 1.0; // shading of the outgoing image
  vec2 tuv = uv;

  for (int i = 0; i < 8; i++) {
    float k = float(i);
    if (k >= n) break;
    float x0 = k / n;
    float x1 = (k + 1.0) / n;
    float xl = k < 0.5 ? -1.0 : x0 - OVERLAP;
    float xr = k > n - 1.5 ? 2.0 : x1;
    vec4 st = ppSheet(k, n);
    float e = clamp((uv.x - x0) / (x1 - x0) * 2.0 - 1.0, -1.0, 1.0);
    float past = uv.y - st.x - st.y * e * e;
    float inY = smoothstep(-AA, AA, past);
    float cov = inY * smoothstep(-aax, aax, uv.x - xl) * smoothstep(-aax, aax, xr - uv.x);
    float edge = (uv.x - xl) * ratio;
    float seam = 0.3 * wet * step(0.5, k) * inY * (1.0 - smoothstep(0.0, 0.005, -edge)) * step(edge, 0.0);
    lit *= 1.0 - seam;
    wall *= 1.0 - seam;
    if (cov <= 0.0) continue;
    float fresh = 1.0 - smoothstep(0.0, 0.6, past);
    vec2 g = relief > 0.0 ? ppRelief(vec2(uv.x * ratio, uv.y), k, fresh, st, x0, x1) * relief : vec2(0.0);
    float shade = 1.0 - RELIEF * dot(g, LIGHT.xy) / LIGHT.z;
    shade *= (1.0 - 0.08 * fresh * wet) * (1.0 + 0.06 * (1.0 - smoothstep(0.0, 0.2, past)) * wet);
    float overlap = 0.07 * (1.0 - smoothstep(OVERLAP * ratio, OVERLAP * ratio + 0.002, edge));
    float rim = 0.12 * (1.0 - smoothstep(0.0, 0.0025, edge));
    shade *= 1.0 - (overlap - rim) * wet * step(0.5, k);
    tuv = mix(tuv, uv - g * 0.004, cov);
    lit = lit * (1.0 - cov) + shade * cov;
    cover = cover * (1.0 - cov) + cov;
  }

  // loose sheets in front of the wall, each one further out than the previous
  for (int i = 0; i < 8; i++) {
    float k = float(i);
    if (k >= n) break;
    vec4 st = ppSheet(k, n);
    if (st.w <= 0.0 || st.x + st.y < -0.01) continue;
    float x0 = k / n;
    float x1 = (k + 1.0) / n;
    float xl = k < 0.5 ? -1.0 : x0 - OVERLAP;
    float xr = k > n - 1.5 ? 2.0 : x1;
    float topShift = 2.0 * AA;
    float zMax = ARC * (1.0 - cos(st.z)) / st.z * smoothstep(0.0, ARC, st.w);
    vec4 sh = ppLoose(uv + LIGHT.xy / LIGHT.z * zMax * vec2(1.0 / ratio, 1.0), st, x0, x1, xl, xr, AA + 0.5 * zMax, topShift);
    float shadow = 0.5 * sh.x * smoothstep(0.0, 0.04, sh.w);
    lit *= 1.0 - shadow;
    wall *= 1.0 - shadow;
    vec4 l = ppLoose(uv, st, x0, x1, xl, xr, AA, topShift);
    if (l.x <= 0.0) continue;
    float th = acos(clamp(cos(st.z) + l.w * st.z / ARC, -1.0, 1.0));
    vec2 g = relief > 0.0 ? ppRelief(vec2(l.y * ratio, l.z), k, 1.0, st, x0, x1) * relief : vec2(0.0);
    float e = clamp((l.y - x0) / (x1 - x0) * 2.0 - 1.0, -1.0, 1.0);
    float s = min(st.x + st.y * e * e, 1.0) - l.z;
    g.x += 0.8 * creases * smoothstep(0.0, 0.3, s) * cos(l.y * n * 12.57 + k * 2.1 + st.z * 4.0);
    float fold = 1.0 - smoothstep(0.0, 0.035, st.w - s);
    float curl = 1.0 - smoothstep(0.0, 0.04, l.z);
    float shade = (LIGHT.y * sin(th) + LIGHT.z * cos(th)) / LIGHT.z;
    shade *= (1.0 - RELIEF * dot(g, LIGHT.xy) / LIGHT.z) * (1.0 - 0.8 * l.w) * (1.0 - 0.08 * wet) * (1.0 - 0.35 * fold * fold) * (1.0 + 0.15 * curl);
    tuv = mix(tuv, vec2(l.y, l.z) - g * 0.004, l.x);
    lit = lit * (1.0 - l.x) + shade * l.x;
    cover = cover * (1.0 - l.x) + l.x;
  }

  vec4 a = getFromColor(uv);
  vec4 b = getToColor(ppFold(tuv));
  return vec4(a.rgb * wall * (1.0 - cover) + b.rgb * lit, mix(a.a, b.a, cover));
}

// Name: Power Kaleido
// Author: Boundless
// License: MIT
// Description: The image folds into an animated kaleidoscope before revealing the incoming one
// Tags: kaleidoscope, distort
#define PI 3.14159265358979
const float rad = 120.; // change this value to get different mirror effects
const float deg = rad / 180. * PI;
uniform float scale; // = 2.0
uniform float z; // = 1.5
uniform float speed; // = 5.
vec2 refl(vec2 p,vec2 o,vec2 n)
{
	return 2.0*o+2.0*n*dot(p-o,n)-p;
}

vec2 rot(vec2 p, vec2 o, float a)
{
    float s = sin(a);
    float c = cos(a);
	return o + mat2(c, -s, s, c) * (p - o);
}

vec4 mainImage(vec2 uv)
{
  float dist = scale / 10.;
  vec2 uv0 = uv;
	uv -= 0.5;
  uv.x *= ratio;
  uv *= z;
  uv = rot(uv, vec2(0.0), progress*speed);
	float theta = progress*6.+PI/.5;
	for(int iter = 0; iter < 10; iter++) {
    for(float i = 0.; i < 2. * PI; i+=deg) {
	    float ts = sign(asin(cos(i))) == 1.0 ? 1.0 : 0.0;
      if(((ts == 1.0) && (uv.y-dist*cos(i) > tan(i)*(uv.x+dist*+sin(i)))) || ((ts == 0.0) && (uv.y-dist*cos(i) < tan(i)*(uv.x+dist*+sin(i))))) {
        uv = refl(vec2(uv.x+sin(i)*dist*2.,uv.y-cos(i)*dist*2.), vec2(0.,0.), vec2(cos(i),sin(i)));
      }
    }
  }
  uv += 0.5;
  uv = rot(uv, vec2(0.5), progress*-speed);
  uv -= 0.5;
  uv.x /= ratio;
  uv += 0.5;
  uv = 2.*abs(uv/2.-floor(uv/2.+0.5));
  vec2 uvMix = mix(uv,uv0,cos(progress*PI*2.)/2.+0.5);
  vec4 color = mix(getFromColor(uvMix),getToColor(uvMix),cos((progress-1.)*PI)/2.+0.5);
	return color;

}
vec4 transition (vec2 uv) {
  vec4 color = mainImage(uv);
  return color;
}

// Author: gre
// License: MIT
// Description: The frame is cut into 3D prisms that turn in a cascade, like a rotating billboard, from the outgoing image on one face to the incoming one on the next
// Tags: 3d, rotate, stripes

// @range(2, 40, 1) Number of prisms
uniform int slats; // = 8
// @range(0, 0.9) Delay of the last prism's turn, as a part of the transition
uniform float stagger; // = 0.45
// @range(0, 4) Amount of perspective
uniform float perspective; // = 1.0
// @range(0, 1) How much the faces darken as they turn away
uniform float shading; // = 0.6
// @param Cut the frame into horizontal prisms instead
uniform bool horizontal; // = false
// @color Color seen where the turning prisms leave the frame uncovered
uniform vec4 backColor; // = vec4(0.0, 0.0, 0.0, 1.0)

const float PI = 3.141592653589793;
const float EDGE = 0.002;

vec4 transition (vec2 uv) {
  float n = float(slats);
  // a: the axis across the prisms, b: the axis they turn around
  float a = horizontal ? uv.y : uv.x;
  float b = horizontal ? uv.x : uv.y;
  // the prisms' half width in frame heights, and the perspective from their depth
  float hw = 0.5 / n * (horizontal ? 1.0 : ratio);
  float k = min(perspective * hw, 0.5);
  float bScale = horizontal ? ratio : 1.0;
  // a turning prism is wider than its strip: keep the two nearest faces
  vec4 near1 = vec4(0.0), near2 = vec4(0.0);
  float cover1 = 0.0, cover2 = 0.0;
  float z1 = -2.0, z2 = -2.0;
  for (int d = -1; d <= 1; d++) {
    float i = floor(a * n) + float(d);
    if (i < 0.0 || i > n - 1.0) continue;
    float order = (horizontal ? n - 1.0 - i : i) / (n - 1.0);
    float t = clamp((progress - stagger * order) / (1.0 - stagger), 0.0, 1.0);
    t = mix(t, t * t * (3.0 - 2.0 * t), 0.7);
    float c = cos(0.5 * PI * t);
    float s = sin(0.5 * PI * t);
    // soft edges while turning (sharp at rest, to keep the first and last frames exact)
    float edge = EDGE * min(1.0, 20.0 * s * c) + 1e-6;
    // x: position across the strip, -1 to 1; the prism's square section has its faces at distance 1
    float x = 2.0 * (a * n - i) - 1.0;
    for (int f = 0; f < 2; f++) {
      // f = 0: the outgoing face turning away, f = 1: the incoming face turning in
      float cf = f == 0 ? c : s;
      if (cf < 1e-4) continue;
      // u: position on the face, z: depth (1 for a face at rest)
      float u = f == 0 ? (x + s) / c : (x - c) / s;
      float z = f == 0 ? u * s + c : s - u * c;
      if (abs(u) > 1.0 || z <= z2) continue;
      float scale = 1.0 - k * (z - 1.0);
      float y = (b - 0.5) * scale + 0.5;
      if (y < 0.0 || y > 1.0) continue;
      // soften the outer edges only: the faces meet at the prism's corner
      float outer = f == 0 ? 1.0 + u : 1.0 - u;
      float cover = clamp(outer * hw * cf / edge, 0.0, 1.0)
        * clamp(min(y, 1.0 - y) * bScale / scale / edge, 0.0, 1.0);
      float sa = (i + 0.5 + 0.5 * u) / n;
      vec2 p = horizontal ? vec2(y, sa) : vec2(sa, y);
      vec4 img = f == 0 ? getFromColor(p) : getToColor(p);
      float lambert = clamp(f == 0 ? c - 0.6 * s : s + 0.6 * c, 0.0, 1.0);
      vec4 color = vec4(img.rgb * mix(1.0 - shading, 1.0, lambert), img.a);
      if (z > z1) {
        near2 = near1; cover2 = cover1; z2 = z1;
        near1 = color; cover1 = cover; z1 = z;
      } else {
        near2 = color; cover2 = cover; z2 = z;
      }
    }
  }
  return mix(mix(backColor, near2, cover2), near1, cover1);
}

// Author: gre
// License: MIT
// Description: The lights go down on the outgoing image and a projector throws the incoming one onto it: a small, blurred, keystoned picture of light lands on the scene, tinted by the colors it falls on, then grows, comes into focus and squares up until it fills the frame as the scene beneath it fades away
// Tags: light, projector, projection, keystone, focus, reveal

// @range(0, 1) How dark the outgoing image gets once the lights go down
uniform float darkness; // = 0.8
// @range(0, 0.8) How much wider the top of the projected picture is than its bottom when it lands
uniform float keystone; // = 0.45
// @range(0, 0.05) How out of focus the projected picture is when it lands, in frame heights
uniform float blur; // = 0.015

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// the projected picture, sampled with 8 taps on a disc of radius r (in its own coordinates),
// averaged premultiplied so transparent texels do not bleed into it
vec4 projected(vec2 q, vec2 r) {
  vec4 c = vec4(0.0);
  for (int i = 0; i < 8; i++) {
    float a = float(i) * 2.39996;
    vec2 o = sqrt((float(i) + 0.5) / 8.0) * vec2(cos(a), sin(a));
    vec4 t = getToColor(mirror(q + o * r));
    c += vec4(t.rgb * t.a, t.a);
  }
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a / 8.0) : vec4(0.0);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec4 from = getFromColor(uv);

  float on = smoothstep(0.06, 0.26, p);
  float ambient = 1.0 - darkness * smoothstep(0.0, 0.2, p);
  float g = smoothstep(0.02, 1.0, p);
  float focus = 1.0 - smoothstep(0.15, 0.85, p);
  float size = mix(0.32, 1.0, g * (0.6 + 0.4 * g));
  float k = keystone * (1.0 - g);
  float cy = mix(0.58, 0.5, g);

  // keystone: the picture is a trapezoid seen in perspective, its rows spaced wider where it is wider
  float y = (uv.y - cy) / size + 0.5;
  float wy = max(1.0 - 0.5 * k + k * y, 0.05);
  vec2 q = vec2((uv.x - 0.5) / (size * wy) + 0.5, y * (1.0 + 0.5 * k) / wy);

  // soft edges of the beam, in frame heights, sharp once in focus
  float e = min((0.5 * size * wy - abs(uv.x - 0.5)) * ratio, size * min(y, 1.0 - y));
  float soft = 0.0015 + 0.035 * focus;
  float cov = mix(smoothstep(-soft, soft, e), 1.0, smoothstep(0.9, 1.0, p));
  float halo = 0.15 * focus * on * exp(-24.0 * max(-e, 0.0)) * (1.0 - cov);

  vec2 d = q - 0.5;
  float gain = on * mix(1.25, 1.0, g) * (1.0 + focus * (0.15 - 1.2 * dot(d, d)));
  // the blur is round on the frame: picture coordinates stretch with the keystone
  vec2 r = blur * focus / (size * wy) * vec2(1.0 / ratio, (1.0 - 0.25 * k * k) / wy);
  vec4 pic = projected(q, r);
  vec3 light = pic.rgb * gain * cov + halo;

  float screen = smoothstep(0.35, 0.95, p);
  vec3 surface = mix(from.rgb, vec3(1.0), 0.35 + 0.65 * screen);
  vec3 col = from.rgb * ambient * (1.0 - cov * screen) + surface * light;
  // the picture of light shows even over a transparent scene
  return vec4(col, mix(max(from.a, pic.a * cov * on), pic.a, cov * screen));
}

// Author: gre
// License: MIT
// Description: The image is cut into jigsaw puzzle pieces that lift one after another and fall away, revealing the incoming image
// Tags: tiles, shadow, rotate, fragments

// @range(2, 12) Number of pieces across the shorter side
uniform float pieces; // = 5.0
// @range(0, 1) Darkness of the shadows of the lifted pieces
uniform float shadow; // = 0.6

// Hash of a cell, without sin, in [0, 1)
float hash(vec2 c) {
  vec2 p = fract(c * vec2(0.1031, 0.1030));
  p += dot(p, p.yx + 33.33);
  return fract((p.x + p.y) * p.x);
}

float boxDist(vec2 p, vec2 halfSize) {
  vec2 q = abs(p) - halfSize;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0);
}

// Signed distance of a point, relative to the center of piece c, to that piece (cell units).
// Each edge has a knob (a round head on a neck): a tab for one piece, a blank for its neighbor; border edges are flat.
float pieceDist(vec2 p, vec2 c, vec2 grid, float aspect) {
  vec2 halfSize = vec2(0.5 * aspect, 0.5);
  float d = boxDist(p, halfSize);
  float tabs = 1e3;
  for (int e = 0; e < 4; e++) {
    // right, left, top, bottom: the edge key is the cell on its left or below
    vec2 dir = e == 0 ? vec2(1.0, 0.0) : e == 1 ? vec2(-1.0, 0.0) : e == 2 ? vec2(0.0, 1.0) : vec2(0.0, -1.0);
    vec2 key = c + min(dir, 0.0);
    vec2 next = c + dir;
    if (next.x >= 0.0 && next.y >= 0.0 && next.x < grid.x && next.y < grid.y) {
      float h = hash(key + (e < 2 ? vec2(0.0) : vec2(71.0, 37.0)));
      // the knob points right or up from the key cell when h < 0.5
      bool tab = (h < 0.5) == (dir.x + dir.y > 0.0);
      vec2 out1 = dir * (tab ? 1.0 : -1.0);
      vec2 along = vec2(abs(dir.y), abs(dir.x));
      vec2 edge = dir * halfSize + along * (fract(h * 2.0) - 0.5) * 0.16;
      float k = min(
        length(p - edge - out1 * 0.15) - 0.125,
        boxDist(p - edge - out1 * 0.06, abs(dir) * 0.08 + along * 0.085));
      if (tab) tabs = min(tabs, k);
      else d = max(d, -k);
    }
  }
  return min(d, tabs);
}

vec4 transition(vec2 uv) {
  // a grid of nearly square cells that fits the frame exactly
  float rows = ratio < 1.0 ? floor(pieces / ratio + 0.5) : pieces;
  float cols = ratio < 1.0 ? pieces : floor(pieces * ratio + 0.5);
  vec2 grid = vec2(cols, rows);
  float aspect = ratio * rows / cols;
  vec2 g = uv * grid;
  vec2 cell = floor(g);

  const float aa = 0.01; // soft edges, in cells
  float boardSum = 0.0;
  float allSum = 0.0;
  float prio1 = -1.0, prio2 = -1.0, cov1 = 0.0, cov2 = 0.0, shade1 = 1.0, shade2 = 1.0;
  vec2 uv1 = uv, uv2 = uv;
  float shadowAll = 0.0;
  float seam = 1.0;
  for (int i = 0; i < 9; i++) {
    vec2 c = cell + vec2(mod(float(i), 3.0), floor(float(i) / 3.0)) - 1.0;
    if (c.x < 0.0 || c.y < 0.0 || c.x >= cols || c.y >= rows) continue;
    vec2 center = c + 0.5;
    vec2 local = (g - center) * vec2(aspect, 1.0);
    float h = hash(c + vec2(13.0, 7.0));
    float diag = (c.x / max(cols - 1.0, 1.0) + (rows - 1.0 - c.y) / max(rows - 1.0, 1.0)) * 0.5;
    float delay = (diag + 1.2 * (h - 0.5) * diag * (1.0 - diag)) * 0.6;
    float t = clamp((progress - delay) / 0.4, 0.0, 1.0);

    float d0 = pieceDist(local, c, grid, aspect);
    float w = 1.0 - smoothstep(-aa, aa, d0);
    allSum += w;
    if (t <= 0.0) {
      boardSum += w;
      seam = min(seam, abs(d0));
      continue;
    }
    float lift = smoothstep(0.0, 0.25, t);
    boardSum += w * (1.0 - smoothstep(0.0, 0.1, t));
    float fall = clamp((t - 0.2) / 0.8, 0.0, 1.0);
    fall *= fall;
    float s = max(1.0 - fall, 0.001);
    float a = (h - 0.5) * 3.0 * fall;
    vec2 off = vec2(0.0, -1.2 * fall);
    mat2 rot = mat2(cos(a), -sin(a), sin(a), cos(a));
    vec2 pl = rot * (local - off) / s;
    float dp = pieceDist(pl, c, grid, aspect);
    float cov = (1.0 - smoothstep(-aa, aa, dp * s)) * min(s * 20.0, 1.0); // fades when tiny
    float shade = (1.0 - 0.5 * fall) * (1.0 - 0.3 * lift * (1.0 - smoothstep(0.0, 0.035, -dp)));
    vec2 puv = (center + pl / vec2(aspect, 1.0)) / grid;
    vec2 sl = rot * (local - off - vec2(0.08, -0.1) * lift) / s;
    float sh = (1.0 - smoothstep(-0.05, 0.12, pieceDist(sl, c, grid, aspect) * s)) * lift * (1.0 - fall) * shadow;
    shadowAll = max(shadowAll, max(sh, w * lift * (1.0 - smoothstep(0.2, 0.5, t)) * shadow));
    float prio = delay;
    if (cov > 0.0 && prio > prio1) {
      prio2 = prio1; cov2 = cov1; uv2 = uv1; shade2 = shade1;
      prio1 = prio; cov1 = cov; uv1 = puv; shade1 = shade;
    } else if (cov > 0.0 && prio > prio2) {
      prio2 = prio; cov2 = cov; uv2 = puv; shade2 = shade;
    }
  }
  vec4 base = mix(getToColor(uv), getFromColor(uv), boardSum / max(allSum, 0.001));
  base.rgb *= (1.0 - shadowAll) * (1.0 - 0.4 * smoothstep(0.0, 0.1, progress) * (1.0 - smoothstep(0.0, 0.015, seam)));
  vec4 p2 = getFromColor(uv2);
  p2.rgb *= shade2;
  vec4 p1 = getFromColor(uv1);
  p1.rgb *= shade1;
  return mix(mix(base, p2, cov2), p1, cov1);
}

// Author: gre
// License: MIT
// Description: The frame becomes the face of a twisty cube puzzle: dark gaps open between its cubies, then whole columns and rows of cubies turn a quarter turn around the cube one after another in 3D, each bringing the incoming image from the cube's side to the front, until the gaps close on the incoming image
// Tags: 3d, rotate, grid

// @range(2, 8, 1) Number of cubies along each side of the face
uniform int size; // = 3
// @range(0, 0.05) Width of the gaps between the cubies, as a part of the frame's height
uniform float gap; // = 0.012
// @range(0, 1) How much the turning sides darken away from the light, and the shadows inside the cube
uniform float shading; // = 0.6
// @color Color of the cubies' body, seen in the gaps, on their inner sides and around the cube
uniform vec4 background; // = vec4(0.04, 0.04, 0.05, 1.0)

const float PI = 3.141592653589793;
// delay between the turns of a group, as a part of a turn
const float STAGGER = 0.45;
const float EDGE = 0.0012;

float gridSize() {
  return float(size < 2 ? 2 : (size > 8 ? 8 : size));
}

// the turns run in 3 groups, one after the other: the even columns, the even rows (counted from the top),
// then the odd columns; the turns of a group overlap
float groupLength(float m) {
  return m > 0.0 ? 1.0 + (m - 1.0) * STAGGER : 0.0;
}

// the time in turn units, and the length of the groups of even and odd slices
vec3 timeline(float n) {
  float lenEven = groupLength(floor((n + 1.0) * 0.5));
  float lenOdd = groupLength(floor(n * 0.5));
  float u = clamp((progress - 0.05) / 0.85, 0.0, 1.0) * (2.0 * lenEven + lenOdd);
  return vec3(u, lenEven, lenOdd);
}

// the turn of a column (isCol) or of a row, 0 at rest to 1 turned
float turnTime(vec3 tl, bool isCol, float idx, float n) {
  float k = isCol ? idx : n - 1.0 - idx;
  bool odd = mod(k, 2.0) > 0.5;
  // the odd rows never turn: the columns already brought the incoming image there
  if (odd && !isCol) return 0.0;
  float start = (odd ? 2.0 * tl.y : (isCol ? 0.0 : tl.y)) + floor(k * 0.5) * STAGGER;
  return clamp(tl.x - start, 0.0, 1.0);
}

// the turn's direction: +1 brings the side of the cube at higher coordinates to the front
float turnDir(bool isCol, float idx) {
  return mod(idx + (isCol ? 0.0 : 1.0), 2.0) < 0.5 ? 1.0 : -1.0;
}

// eased angle, landing with a little speed left like a click
float turnAngle(float t) {
  return 0.5 * PI * mix(t, t * t * (3.0 - 2.0 * t), 0.8);
}

// 1 on the cubies' faces, 0 in the gaps, at the point fp of the face (frame heights)
float faceMask(vec2 fp, float n, float g) {
  if (g <= 0.0) return 1.0;
  vec2 cell = vec2(ratio, 1.0) / n;
  vec2 c = fp / cell;
  vec2 r = floor(c + 0.5);
  // distance to the nearest cubie edge inside the face (the face's own border has no gap)
  vec2 d = abs(c - r) * cell;
  d.x = (r.x < 0.5 || r.x > n - 0.5) ? 1.0 : d.x;
  d.y = (r.y < 0.5 || r.y > n - 0.5) ? 1.0 : d.y;
  float e = min(EDGE, 0.5 * g);
  return smoothstep(0.5 * g - e, 0.5 * g + e, min(d.x, d.y));
}

bool isDone(vec3 tl, vec2 fp, float n) {
  vec2 cell = clamp(floor(fp / (vec2(ratio, 1.0) / n)), 0.0, n - 1.0);
  return turnTime(tl, true, cell.x, n) >= 1.0 || turnTime(tl, false, cell.y, n) >= 1.0;
}

vec4 sticker(vec2 fp, bool incoming, float light, float n, float g) {
  vec2 uv = clamp(fp / vec2(ratio, 1.0), 0.0, 1.0);
  vec4 img = incoming ? getToColor(uv) : getFromColor(uv);
  vec4 body = vec4(background.rgb * light, background.a);
  return mix(body, vec4(img.rgb * light, img.a), faceMask(fp, n, g));
}

// brightness of a face of normal nrm (across the slices, along the turn, depth) in the turn's space, 1 facing the viewer
float lighting(vec3 nrm, bool isCol) {
  vec3 l = normalize(vec3(-0.35, 0.55, 1.0));
  if (isCol) l = l.yxz;
  return 1.0 - shading * (1.0 - clamp(dot(nrm, l) / l.z, 0.0, 1.0));
}

vec2 rot(vec2 v, float a) {
  float c = cos(a), s = sin(a);
  return vec2(c * v.x - s * v.y, s * v.x + c * v.y);
}

// casts the ray (o, d), in the turn's space (across the slices, along the turn, depth), onto the slice
// [a0, a0 + w] turned by the angle a around the middle of the cube (a square section of side S):
// returns the ray's parameter at the hit (or -1), the face hit (0 front, 1 back, 2 and 3 the sides
// at higher and lower coordinates along the turn at rest, 4 the slice's ends), and the point hit
// (across the slices, and across the face, -1 to 1)
vec4 sliceHit(vec3 o, vec3 d, float a0, float w, float S, float a) {
  vec2 lo = rot(o.yz - vec2(0.5 * S, -0.5 * S), -a);
  vec2 ld = rot(d.yz, -a);
  ld = vec2(abs(ld.x) < 1e-6 ? 1e-6 : ld.x, abs(ld.y) < 1e-6 ? 1e-6 : ld.y);
  float dx = abs(d.x) < 1e-6 ? 1e-6 : d.x;
  vec3 t1 = vec3((a0 - o.x) / dx, (-0.5 * S - lo) / ld);
  vec3 t2 = vec3((a0 + w - o.x) / dx, (0.5 * S - lo) / ld);
  vec3 tn = min(t1, t2);
  vec3 tf = max(t1, t2);
  float tNear = max(tn.x, max(tn.y, tn.z));
  float tFar = min(tf.x, min(tf.y, tf.z));
  if (tNear > tFar || tNear <= 0.0) return vec4(-1.0);
  vec2 q = (lo + tNear * ld) / (0.5 * S);
  float across = o.x + tNear * d.x;
  if (tn.x >= tn.y && tn.x >= tn.z) return vec4(tNear, 4.0, across, sign(-dx));
  if (tn.y > tn.z) return vec4(tNear, ld.x < 0.0 ? 2.0 : 3.0, across, q.y);
  return vec4(tNear, ld.y < 0.0 ? 0.0 : 1.0, across, q.x);
}

vec4 sliceColor(vec4 hit, vec3 tl, bool isCol, float a, float dir, float S, float n, float g) {
  float f = hit.y;
  if (f > 3.5) return vec4(background.rgb * lighting(vec3(hit.w, 0.0, 0.0), isCol), background.a);
  vec2 nl = f < 0.5 ? vec2(0.0, 1.0) : f < 1.5 ? vec2(0.0, -1.0) : f < 2.5 ? vec2(1.0, 0.0) : vec2(-1.0, 0.0);
  float light = lighting(vec3(0.0, rot(nl, a)), isCol);
  // the front shows what the cubies showed before this turn, the side that comes to the front
  // shows the incoming image where it lands
  bool front = f < 0.5;
  bool coming = nl.x * dir > 0.5;
  if (!front && !coming) return vec4(background.rgb * light, background.a);
  // on the side coming to the front, the point across lands at -dir times its depth
  float r = 0.5 * S * (1.0 + (front ? hit.w : -dir * hit.w));
  vec2 fp = isCol ? vec2(hit.z, r) : vec2(r, hit.z);
  return sticker(fp, coming || isDone(tl, fp, n), light, n, g);
}

vec4 transition(vec2 uv) {
  float n = gridSize();
  vec3 tl = timeline(n);
  float g = gap * smoothstep(0.0, 0.1, progress) * (1.0 - smoothstep(0.9, 1.0, progress));
  vec2 P = vec2(uv.x * ratio, uv.y);

  // the turns going on are of columns or of rows, never both
  bool isCol = tl.x < tl.y || tl.x >= 2.0 * tl.y;
  // the turn's space: (across the slices, along the turn, depth toward the viewer);
  // a column turns around the horizontal axis through the middle of the cube, a row around the vertical one
  float w = (isCol ? ratio : 1.0) / n;
  float S = isCol ? 1.0 : ratio;
  vec2 pp = isCol ? P : P.yx;
  vec3 o = vec3(isCol ? vec2(0.5 * ratio, 0.5) : vec2(0.5, 0.5 * ratio), 1.2 + 0.6 * max(ratio, 1.0));
  // the ray reaches the face (z = 0) at t = 1
  vec3 d = vec3(pp, 0.0) - o;

  float k0 = clamp(floor(pp.x / w), 0.0, n - 1.0);
  float t0 = turnTime(tl, isCol, k0, n);

  float nearest = 1.0;
  vec4 color;
  if (t0 <= 0.0 || t0 >= 1.0) {
    color = isDone(tl, P, n) ? getToColor(uv) : getFromColor(uv);
    color = mix(background, color, faceMask(P, n, g));
    for (int j = -1; j <= 1; j += 2) {
      float k = k0 + float(j);
      if (k < 0.0 || k > n - 1.0) continue;
      float tk = turnTime(tl, isCol, k, n);
      if (tk <= 0.0 || tk >= 1.0) continue;
      float dist = abs(pp.x - (k + 0.5) * w) - 0.5 * w;
      color.rgb *= 1.0 - 0.5 * shading * sin(2.0 * turnAngle(tk)) * exp(-dist / (0.2 * w));
    }
  } else {
    float tw = abs(d.x) < 1e-6 ? 1e6 : (d.x < 0.0 ? k0 * w - o.x : (k0 + 1.0) * w - o.x) / d.x;
    float tb = (o.z + S) / -d.z;
    nearest = min(tw, tb);
    float along = o.y + nearest * d.y;
    float depth = (o.z + nearest * d.z) / -S;
    float light = tw < tb ? lighting(vec3(-sign(d.x), 0.0, 0.0), isCol) : 1.0;
    light *= 1.0 - shading * (0.5 + 0.4 * clamp(depth, 0.0, 1.0));
    color = along < 0.0 || along > S ? background : vec4(background.rgb * light, background.a);
  }

  for (int j = -1; j <= 1; j++) {
    float k = k0 + float(j);
    if (k < 0.0 || k > n - 1.0) continue;
    float tk = turnTime(tl, isCol, k, n);
    if (tk <= 0.0 || tk >= 1.0) continue;
    float dir = turnDir(isCol, k);
    float a = dir * turnAngle(tk);
    vec4 hit = sliceHit(o, d, k * w, w, S, a);
    if (hit.x > 0.0 && hit.x < nearest) {
      nearest = hit.x;
      color = sliceColor(hit, tl, isCol, a, dir, S, n, g);
    }
  }
  return color;
}

// Author: gre
// License: MIT
// Description: The image is cut into square tiles that turn in blocks of four like little turntables, a quarter turn at a time on two staggered grids, lifting over their neighbours and scrambling the outgoing image; a wave flips the tiles over to the incoming image, then the blocks turn back the same way until every tile is home
// Tags: tiles, rotate, puzzle, shuffle, flip, mechanical

// @range(3, 8, 1) Number of tiles along the short side of the frame
uniform int tiles; // = 4
// @range(0, 0.8) Delay between the first and the last block of each turn, as a part of the turn
uniform float stagger; // = 0.4
// @range(0, 1) Darkness of the shadows cast by the lifted tiles
uniform float shadow; // = 0.6
// @color Color of the tray seen under the turning blocks
uniform vec4 backColor; // = vec4(0.12, 0.12, 0.13, 1.0)

const float PI = 3.141592653589793;
const float FLIP = 1.3;
// share of the flip beat over which the wave crosses the frame; each tile flips in the rest
const float WAVE = 0.8;
const float EYE = 3.0;
const float AA = 0.015;
const vec2 SHADOW_OFFSET = vec2(0.1, -0.14);

vec2 rot(vec2 v, float a) {
  float c = cos(a), s = sin(a);
  return vec2(c * v.x - s * v.y, s * v.x + c * v.y);
}

// beats 0, 1 turn on grids offset by 0 then 1 tile; beat 2 flips; beats 3, 4 undo 1 then 0
float offsetOf(float i) {
  return mod(i < 2.5 ? i : 4.0 - i, 2.0);
}

float dirOf(float i) {
  return i < 2.5 ? 1.0 : -1.0;
}

bool inside(vec2 lo, float size, vec2 dims) {
  return all(greaterThanEqual(lo, vec2(0.0))) && all(lessThanEqual(lo + size, dims));
}

vec2 turn(vec2 p, float i, float way, vec2 dims) {
  float o = offsetOf(i);
  vec2 lo = o + 2.0 * floor((p - o) / 2.0);
  if (!inside(lo, 2.0, dims)) return p;
  vec2 c = lo + 1.0;
  return c + rot(p - c, way * dirOf(i) * 0.5 * PI);
}

float smooth3(float f) {
  return f * f * (3.0 - 2.0 * f);
}

float turnAngle(float f, vec2 c, float o, vec2 dims) {
  vec2 last = o + 2.0 * floor((dims - o) / 2.0) - 1.0;
  float k = c.x + 0.3 * c.y - 1.3 * (o + 1.0);
  float d = stagger * k / max(last.x + 0.3 * last.y - 1.3 * (o + 1.0), 1.0);
  return 0.5 * PI * smooth3(clamp((f - d) / (1.0 - stagger), 0.0, 1.0));
}

// doubled smoothstep rushes through the edge-on moment
float flipAngle(float f, vec2 c, vec2 dims) {
  float d = WAVE * (c.x + c.y - 1.0) / max(dims.x + dims.y - 2.0, 1.0);
  return PI * smooth3(smooth3(clamp((f - d) / (1.0 - WAVE), 0.0, 1.0)));
}

// clamped: sin(PI) is slightly negative in float
float liftOf(float a, bool flip) {
  return max(flip ? sin(a) : sin(2.0 * a), 0.0);
}

// xy: point on the card relative to its center, z: lift, w: distance to its edge on screen
vec4 card(vec2 P, vec2 c, float a, bool flip, float dir) {
  if (flip) {
    float sa = sin(a), ca = cos(a);
    float s = 1.0 + 0.2 * sa;
    vec2 d = (P - c) / s;
    float den = EYE * ca + d.x * sa;
    den = abs(den) < 1e-5 ? (den < 0.0 ? -1e-5 : 1e-5) : den;
    float x = clamp(d.x * EYE / den, -0.5, 0.5);
    float y = d.y * (EYE - x * sa) / EYE;
    float u0 = -0.5 * ca * EYE / (EYE + 0.5 * sa);
    float u1 = 0.5 * ca * EYE / (EYE - 0.5 * sa);
    float wx = min(d.x - min(u0, u1), max(u0, u1) - d.x);
    return vec4(ca < 0.0 ? -x : x, y, liftOf(a, true), s * min(wx, 0.5 - abs(y)));
  }
  float lift = liftOf(a, false);
  float s = 1.0 + 0.06 * lift;
  vec2 l = rot(P - c, -dir * a) / s;
  return vec4(l, lift, s * (1.0 - max(abs(l.x), abs(l.y))));
}

vec4 layer(vec2 Q, float a, bool flip, float beat, vec2 dims) {
  bool incoming = flip ? cos(a) < 0.0 : beat > 2.5;
  vec2 H = Q;
  if (incoming) {
    for (int i = 3; i < 5; i++) {
      if (float(i) >= beat) H = turn(H, float(i), 1.0, dims);
    }
  } else {
    for (int i = 1; i >= 0; i--) {
      if (float(i) < beat) H = turn(H, float(i), -1.0, dims);
    }
  }
  vec2 st = clamp(H / dims, 0.0, 1.0);
  vec4 col = incoming ? getToColor(st) : getFromColor(st);
  float env = sin(PI * clamp(progress, 0.0, 1.0));
  vec2 tf = abs(fract(Q) - 0.5);
  float seam = smoothstep(0.485, 0.5, max(tf.x, tf.y)) * env;
  float light = 1.0;
  if (flip) {
    float sa = sin(a), ca = cos(a);
    light = 1.0 - 0.5 * sa * sa + 0.2 * abs(ca) * sa;
  }
  col.rgb *= (1.0 - 0.5 * seam) * light;
  return col;
}

vec4 transition(vec2 uv) {
  float n = float(tiles);
  vec2 dims = ratio >= 1.0 ? vec2(floor(n * ratio + 0.5), n) : vec2(n, floor(n / ratio + 0.5));
  vec2 P = uv * dims;
  float t = progress * (4.0 + FLIP);
  float beat = t < 2.0 ? floor(t) : t < 2.0 + FLIP ? 2.0 : min(floor(t - FLIP) + 1.0, 4.0);
  float start = beat < 2.5 ? beat : beat - 1.0 + FLIP;
  bool flip = beat == 2.0;
  float f = clamp((t - start) / (flip ? FLIP : 1.0), 0.0, 1.0);

  float size = flip ? 1.0 : 2.0;
  vec2 org = vec2(flip ? 0.0 : offsetOf(beat));
  vec2 b0 = floor((P - org) / size);
  float dir = dirOf(beat);

  // two topmost cards: the second shows through the antialiased edge of the first
  vec2 q1 = P, q2 = P;
  float a1 = 0.0, a2 = 0.0, lift1 = -1.0, lift2 = -1.0, cov1 = 0.0, cov2 = 0.0;
  for (int j = 0; j < 9; j++) {
    vec2 lo = org + size * (b0 + vec2(mod(float(j), 3.0), floor(float(j) / 3.0)) - 1.0);
    if (inside(lo, size, dims)) {
      vec2 c = lo + 0.5 * size;
      float a = flip ? flipAngle(f, c, dims) : turnAngle(f, c, org.x, dims);
      vec4 k = card(P, c, a, flip, dir);
      if (k.w >= 0.0) {
        float cov = k.z > 1e-3 ? clamp(k.w / AA, 0.0, 1.0) : 1.0;
        if (k.z > lift1) {
          q2 = q1; a2 = a1; lift2 = lift1; cov2 = cov1;
          q1 = c + k.xy; a1 = a; lift1 = k.z; cov1 = cov;
        } else if (k.z > lift2) {
          q2 = c + k.xy; a2 = a; lift2 = k.z; cov2 = cov;
        }
      }
    }
  }
  // tiles outside every block of this grid stay in place, under the turning blocks
  if (!flip && !inside(org + 2.0 * b0, 2.0, dims)) {
    if (lift1 < 0.0) {
      q1 = P; a1 = 0.0; lift1 = 0.0; cov1 = 1.0;
    } else if (lift2 < 0.0) {
      q2 = P; a2 = 0.0; lift2 = 0.0; cov2 = 1.0;
    }
  }

  float shade = 0.0;
  for (int j = 0; j < 9; j++) {
    vec2 lo = org + size * (b0 + vec2(mod(float(j), 3.0), floor(float(j) / 3.0)) - 1.0);
    if (inside(lo, size, dims)) {
      vec2 c = lo + 0.5 * size;
      float a = flip ? flipAngle(f, c, dims) : turnAngle(f, c, org.x, dims);
      float lift = liftOf(a, flip);
      if (lift > lift1 + 0.01) {
        vec4 k = card(P - SHADOW_OFFSET * lift, c, a, flip, dir);
        shade = max(shade, (lift - max(lift1, 0.0)) * smoothstep(flip ? -0.08 : -0.25, 0.04, k.w));
      }
    }
  }

  vec4 col = flip ? layer(P, PI, true, beat, dims) : backColor;
  if (lift2 >= 0.0) col = mix(col, layer(q2, a2, flip, beat, dims), cov2);
  if (lift1 >= 0.0) col = mix(col, layer(q1, a1, flip, beat, dims), cov1);
  col.rgb *= 1.0 - shadow * 0.7 * shade;
  return col;
}

// Author: gre
// License: MIT
// Description: The outgoing image breaks into a quadtree of flat color blocks, small where it is detailed and large where it is plain; the blocks merge into a few big squares that change color one by one, then split again, finer and finer, into the incoming image
// Tags: blocks, pixelate, color, grid, motion-graphics

// @range(0, 0.2) How different the colors inside a block may be before it splits (larger gives bigger blocks)
uniform float tolerance; // = 0.05
// @range(0, 1) Darkness of the thin seams between the blocks
uniform float seams; // = 0.35

// number of levels: the smallest blocks are 1/64 of the largest ones
const int LEVELS = 7;
const float AA = 0.0015;
const float SEAM = 0.0025;

vec4 img(vec2 P, bool incoming) {
  vec2 uv = vec2(P.x / ratio, P.y);
  return incoming ? getToColor(uv) : getFromColor(uv);
}

// 1 on a seam between the blocks of size s, 0 elsewhere; the frame's border has none
float seamLine(vec2 P, vec2 s) {
  vec2 frame = vec2(ratio, 1.0);
  vec2 lo = floor(P / s) * s;
  vec2 hi = lo + s;
  vec2 q = vec2(1.0);
  if (lo.x > AA) q.x = P.x - lo.x;
  if (hi.x < frame.x - AA) q.x = min(q.x, hi.x - P.x);
  if (lo.y > AA) q.y = P.y - lo.y;
  if (hi.y < frame.y - AA) q.y = min(q.y, hi.y - P.y);
  return 1.0 - smoothstep(SEAM - AA, SEAM + AA, min(q.x, q.y));
}

// the quadtree of one image around P, the largest blocks of size s0: each block shows the mean of
// its four quadrants and splits while their colors spread more than thr, down to depth dmax. A block
// that just reaches the threshold or the depth is half split: it fades into its four children, so
// the blocks never pop. Thin dark seams, faded in by seamFade, line the blocks
vec4 tree(vec2 P, vec2 s0, bool incoming, float thr, float dmax, float seamFade) {
  vec2 s = s0;
  vec4 col = vec4(0.0);
  // the weight of the current level in the result: how much the blocks above it have split
  float acc = 1.0;
  float seam = 0.0;
  for (int l = 0; l < LEVELS; l++) {
    vec2 c = (floor(P / s) + 0.5) * s;
    vec2 h = 0.25 * s;
    vec4 a = img(c - h, incoming);
    vec4 b = img(c + vec2(h.x, -h.y), incoming);
    vec4 d = img(c + vec2(-h.x, h.y), incoming);
    vec4 e = img(c + h, incoming);
    vec4 mean = 0.25 * (a + b + d + e);
    vec4 v = abs(a - mean) + abs(b - mean) + abs(d - mean) + abs(e - mean);
    float spread = dot(v, vec4(0.0625));
    // the seams of the smallest blocks are fainter, so they never cover the picture with a dark mesh
    seam = max(seam, acc * smoothstep(0.008, 0.04, s.y) * seamLine(P, s));
    float split = smoothstep(thr, 1.35 * thr + 0.003, spread) * smoothstep(0.2, 0.8, dmax - float(l));
    if (l == LEVELS - 1) split = 0.0;
    col += acc * (1.0 - split) * mean;
    acc *= split;
    if (acc <= 0.0) break;
    s *= 0.5;
  }
  col.rgb *= 1.0 - seams * seamFade * seam;
  return col;
}

vec4 transition(vec2 uv) {
  // kept inside the frame, so the right and top edges stay in the last blocks
  vec2 P = clamp(vec2(uv.x * ratio, uv.y), vec2(0.0), vec2(ratio, 1.0) - 1e-4);
  // u: 0 at the ends (the real images), 1 in the middle (the biggest blocks)
  float u = 1.0 - abs(2.0 * progress - 1.0);
  float coarse = mix(u, u * u * (3.0 - 2.0 * u), 0.5);
  float thr = tolerance * (0.08 + 4.0 * coarse * coarse);
  float dmax = float(LEVELS) * (1.0 - coarse) + 0.2;
  float seamFade = smoothstep(0.0, 0.25, u);

  vec2 s0 = ratio >= 1.0
    ? vec2(ratio / floor(2.0 * ratio + 0.5), 0.5)
    : vec2(0.5 * ratio, 1.0 / floor(2.0 / ratio + 0.5));
  float t = (progress - 0.4) / 0.2;
  vec2 cell = floor(P / s0);
  float h = fract((cell.y * floor(ratio / s0.x + 0.5) + cell.x) * 0.618034 + 0.31);
  float flip = smoothstep(0.75 * h, 0.75 * h + 0.25, t);
  vec4 col;
  if (flip <= 0.0) {
    col = tree(P, s0, false, thr, dmax, seamFade);
  } else if (flip >= 1.0) {
    col = tree(P, s0, true, thr, dmax, seamFade);
  } else {
    col = mix(tree(P, s0, false, thr, dmax, seamFade), tree(P, s0, true, thr, dmax, seamFade), flip);
  }
  vec4 real = progress < 0.5 ? getFromColor(uv) : getToColor(uv);
  return mix(real, col, smoothstep(0.0, 0.18, u));
}

// License: MIT
// Author: Xaychru
// Description: A radial wipe that sweeps around the center like a clock hand
// Tags: wipe, radial, clock
// ported by gre from https://gist.github.com/Xaychru/ce1d48f0ce00bb379750

uniform float smoothness; // = 1.0

const float PI = 3.141592653589;

vec4 transition(vec2 p) {
  vec2 rp = p*2.-1.;
  return mix(
    getToColor(p),
    getFromColor(p),
    smoothstep(0., smoothness, atan(rp.y,rp.x) + PI + smoothness - progress * (2.0 * PI + smoothness))
  );
}

// Author: gre
// License: MIT
// Description: The incoming image appears in random squares
// Tags: squares, grid, dissolve

// @param Number of squares (columns, rows)
uniform ivec2 size; // = ivec2(10, 10)
// @param Softness of each square's switch
uniform float smoothness; // = 0.5

float rand (vec2 co) {
  return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

vec4 transition(vec2 p) {
  float r = rand(floor(vec2(size) * p));
  float m = smoothstep(0.0, -smoothness, r - (progress * (1.0 + smoothness)));
  return mix(getFromColor(p), getToColor(p), m);
}

// Author: gre
// License: MIT
// Description: The outgoing image cracks into irregular shards that burst apart toward the viewer, each one turning over in 3D at its own moment, then fly back together and lock into place as the incoming image carried on their backs
// Tags: 3d, shards, flip, explode

// @range(2, 8, 1) Number of rows of shards
uniform int rows; // = 4
// @range(0, 1) How far the shards come toward the viewer
uniform float depth; // = 0.8
// @range(0, 0.5) How far the shards spread apart, as a part of their distance from the center
uniform float spread; // = 0.05
// @color Color seen between the shards
uniform vec4 backColor; // = vec4(0.04, 0.04, 0.05, 1.0)

const float PI = 3.141592653589793;
const float EYE = 2.5;
// width of the anti-aliased edges and half width of the open cracks, in frame heights
const float EDGE = 0.0015;
const float CRACK = 0.005;
// the shards leave between START and START + DELAY, and each one flies for FLIGHT
const float START = 0.03;
const float DELAY = 0.08;
const float FLIGHT = 0.86;

vec3 hash3(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
  q += dot(q, q.yxz + 33.33);
  return fract((q.xxy + q.yzz) * q.zyx);
}

// the seed of the shard of grid cell g, in frame heights from the center
vec2 seed(vec2 g, float size) {
  return (g + 0.5 + 0.7 * (hash3(g).xy - 0.5)) * size;
}

// distance from q to the border of the shard of cell g (its Voronoi cell), negative outside it
float shardDist(vec2 q, vec2 g, float size) {
  vec2 sj = seed(g, size);
  float d = 1e9;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      if (x == 0 && y == 0) continue;
      vec2 sk = seed(g + vec2(float(x), float(y)), size);
      vec2 dir = sk - sj;
      d = min(d, dot(0.5 * (sj + sk) - q, dir) / length(dir));
    }
  }
  return d;
}

float ease(float t) {
  return t * t * (3.0 - 2.0 * t);
}

float burst(float t) {
  float u = clamp(t / 0.4, 0.0, 1.0);
  float v = clamp((t - 0.4) / 0.6, 0.0, 1.0);
  return t < 0.4 ? 1.0 - (1.0 - u) * (1.0 - u) : 1.0 - ease(v);
}

vec4 transition(vec2 uv) {
  vec2 aspect = vec2(ratio, 1.0);
  vec2 x = (uv - 0.5) * aspect;
  float size = 1.0 / clamp(float(rows), 1.0, 8.0);
  float E = clamp(spread, 0.0, 0.5);
  float Z = clamp(depth, 0.0, 1.0);
  float p = clamp(progress, 0.0, 1.0);
  vec3 L = normalize(vec3(-0.45, 0.55, 1.0));
  vec3 H = normalize(L + vec3(0.0, 0.0, 1.0));
  vec3 eye = vec3(0.0, 0.0, EYE);
  vec3 dir = vec3(x, -EYE);
  float act = smoothstep(0.0, START + DELAY, p) * (1.0 - smoothstep(START + FLIGHT, 1.0, p));

  // where this point roughly comes from, to find the shards that can cover it
  float b0 = burst(clamp((p - START - 0.5 * DELAY) / FLIGHT, 0.0, 1.0));
  vec2 x0 = x * (EYE - 0.75 * Z * b0) / EYE / (1.0 + E * b0);
  vec2 cell0 = floor(x0 / size);

  // the two nearest shards seen here: depth, image point, side (1 front), coverage, shading, rim
  float z1 = 1e9, z2 = 1e9;
  vec2 q1 = x, q2 = x;
  float f1 = 1.0, f2 = 1.0, m1 = 0.0, m2 = 0.0;
  float s1 = 1.0, s2 = 1.0, r1 = 0.0, r2 = 0.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 g = cell0 + vec2(float(i), float(j));
      vec3 h = hash3(g + 17.0);
      float t = clamp((p - START - DELAY * h.x) / FLIGHT, 0.0, 1.0);
      float b = burst(t);
      float th = PI * ease(clamp((t - 0.1 - 0.48 * h.z) / 0.24, 0.0, 1.0));
      float ct = cos(th), st = sin(th);
      float phi = PI * h.y;
      float rz = 0.5 * (h.z - 0.5) * b;
      vec2 a0 = vec2(cos(phi), sin(phi));
      vec2 p0 = vec2(-a0.y, a0.x);
      vec3 a = vec3(cos(phi + rz), sin(phi + rz), 0.0);
      vec3 w = vec3(-a.y, a.x, 0.0) * ct + vec3(0.0, 0.0, st);
      vec2 c = seed(g, size);
      vec3 center = vec3(c * (1.0 + E * b), Z * b * (0.5 + 0.5 * h.x));
      vec3 nrm = cross(a, w);
      float den = dot(dir, nrm);
      if (abs(den) < 1e-6) continue;
      float lam = dot(center - eye, nrm) / den;
      if (lam <= 0.0) continue;
      vec3 hit = eye + lam * dir - center;
      float u = dot(hit, a), v = dot(hit, w);
      // the front carries the outgoing image, the back the incoming one, mirrored so that it lands in place;
      // the side seen is the one facing the eye, which swaps where the shard is seen edge-on
      float front = den < 0.0 ? 1.0 : -1.0;
      vec2 q = c + u * a0 + front * v * p0;
      // anti-aliased edges, scaled to the screen; at rest the shards overlap a little to hide their seams
      float k = EYE / (EYE - center.z);
      float e = shardDist(q, g, size) - CRACK * act;
      vec2 box = 0.5 * aspect - abs(q);
      e = min(e, min(box.x, box.y)) * k * mix(1.0, max(abs(ct), 0.2), min(b * 8.0, 1.0)) + 4.0 * EDGE * (1.0 - act);
      float m = clamp(e / (2.0 * EDGE) + 0.5, 0.0, 1.0);
      // at rest the shards lie at the same depth: the one that covers this point fully comes first
      float zk = lam - 0.001 * m;
      if (m <= 0.0 || zk >= z2) continue;
      vec3 n = nrm * front;
      float lit = mix(0.45, 1.0, clamp(dot(n, L) / L.z, 0.0, 1.0));
      float glint = 0.2 * min(b * 4.0, 1.0) * pow(max(dot(n, H), 0.0), 24.0);
      float lock = sin(PI * clamp((t - 0.86) / 0.14, 0.0, 1.0));
      float rim = (0.3 * act * min(b * 4.0, 1.0) + 0.35 * lock) * (1.0 - smoothstep(0.0, 0.006, e));
      if (zk < z1) {
        z2 = z1; q2 = q1; f2 = f1; m2 = m1; s2 = s1; r2 = r1;
        z1 = zk; q1 = q; f1 = front; m1 = m; s1 = lit + glint; r1 = rim;
      } else {
        z2 = zk; q2 = q; f2 = front; m2 = m; s2 = lit + glint; r2 = rim;
      }
    }
  }

  vec4 col = backColor;
  if (m2 > 0.0) {
    vec2 src = q2 / aspect + 0.5;
    vec4 img = f2 > 0.0 ? getFromColor(src) : getToColor(src);
    img.rgb = mix(min(img.rgb * s2, vec3(img.a)), vec3(img.a), r2);
    col = mix(col, img, m2);
  }
  if (m1 > 0.0) {
    vec2 src = q1 / aspect + 0.5;
    vec4 img = f1 > 0.0 ? getFromColor(src) : getToColor(src);
    img.rgb = mix(min(img.rgb * s1, vec3(img.a)), vec3(img.a), r1);
    col = mix(col, img, m1);
  }
  return col;
}

// Author: martiniti
