// Author: gre
// License: MIT
// Description: A slide projector changes slides: the outgoing picture is jerked up out of the frame, blurring as it leaves the focal plane, the bare lamp flickers on the screen for an instant, then the incoming picture drops in from the top, bounces and hunts for focus before it sharpens
// Tags: retro, projector, slide, vertical, bounce, focus, flicker

// @range(0, 1) How high the incoming slide bounces when it lands in the gate
uniform float bounce; // = 0.5
// @range(0, 1) How out of focus the slides get while they move
uniform float defocus; // = 0.5
// @range(0, 1) How much the lamp flickers during the change
uniform float flicker; // = 0.5
// @color Color of the lamp light on the screen while the gate is empty
uniform vec4 lampColor; // = vec4(1.0, 0.95, 0.84, 1.0)

const float PI = 3.14159265;
const float MOUNT = 0.07;
const float CLEAR = 1.0 + MOUNT;
const int TAPS = 16;

float hash(float n) {
  vec3 p3 = fract(vec3(n) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// height of the outgoing picture on the screen: a short dip as the lift arm grabs the slide, then
// it is jerked up, still accelerating as it leaves the frame
float liftOut(float p) {
  float u = clamp((p - 0.05) / 0.3, 0.0, 1.0);
  float d = clamp(p / 0.12, 0.0, 1.0);
  float s = sin(PI * d);
  return CLEAR * u * u * (0.6 + 0.4 * u) - (0.004 + 0.012 * bounce) * s * s;
}

// height of the incoming picture: it falls into the gate under gravity, then makes two small hops
float dropIn(float p) {
  float v = clamp((p - 0.37) / 0.19, 0.0, 1.0);
  float y = CLEAR * (1.0 - v * v);
  float w = clamp((p - 0.56) / 0.22, 0.0, 1.0);
  float h = 0.06 * bounce;
  // hop lengths in proportion to the square root of their heights (1 and 0.15)
  float s1 = clamp(w / 0.72, 0.0, 1.0);
  float s2 = clamp((w - 0.72) / 0.28, 0.0, 1.0);
  return y + h * 4.0 * s1 * (1.0 - s1) + h * 0.15 * 4.0 * s2 * (1.0 - s2);
}

// how far out of focus the projection is (0 to 1): the outgoing slide leaves the focal plane as it
// is lifted, the incoming one lands out of focus, sharpens, overshoots and comes back sharp
float blurAmount(float p) {
  float s = clamp((p - 0.56) / 0.4, 0.0, 1.0);
  float k = 1.0 - s;
  float hunt = abs(cos(s * PI * 1.5)) * k;
  return smoothstep(0.04, 0.3, p) * (p < 0.56 ? 1.0 : hunt);
}

float band(float y, float a, float b, float aa) {
  return clamp((min(y - a, b - y)) / aa + 0.5, 0.0, 1.0);
}

// the gate seen on the screen at y (frame coordinates) with the outgoing slide at height yf and
// the incoming one at height yt, premultiplied; light is the brightness of the bare lamp there and
// shade the one of the pictures
vec4 gate(vec2 q, float yf, float yt, float light, float shade) {
  // edges get sharp as a slide comes to rest, so that it then covers the whole frame
  float af = 0.0015 * min(abs(yf) * 400.0, 1.0) + 1e-6;
  float at = 0.0015 * min(abs(yt) * 400.0, 1.0) + 1e-6;
  vec4 c = vec4(lampColor.rgb * lampColor.a * light, lampColor.a);
  float mf = band(q.y, yf - MOUNT, yf + 1.0 + MOUNT, af);
  float mt = band(q.y, yt - MOUNT, yt + 1.0 + MOUNT, at);
  c.rgb *= 1.0 - 0.96 * max(mf, mt);
  float pf = band(q.y, yf, yf + 1.0, af);
  if (pf > 0.0) {
    vec4 t = getFromColor(vec2(q.x, q.y - yf));
    c = mix(c, vec4(t.rgb * t.a * shade, t.a), pf);
  }
  float pt = band(q.y, yt, yt + 1.0, at);
  if (pt > 0.0) {
    vec4 t = getToColor(vec2(q.x, q.y - yt));
    c = mix(c, vec4(t.rgb * t.a * shade, t.a), pt);
  }
  return c;
}

vec4 transition(vec2 uv) {
  float p = progress;

  float yf = liftOut(p);
  float yt = dropIn(p);
  // vertical speed of the slide that moves (one at a time), for the motion blur
  float dp = 0.004;
  float vf = (liftOut(p + dp) - liftOut(p - dp)) / (2.0 * dp);
  float vt = (dropIn(p + dp) - dropIn(p - dp)) / (2.0 * dp);
  float smear = min(max(abs(vf), abs(vt)) * 0.012, 0.07);

  float b = blurAmount(p);
  float radius = defocus * 0.02 * b;
  float zoom = 1.0 + 0.025 * defocus * b;
  vec2 c0 = (uv - 0.5) / zoom + 0.5;

  float env = smoothstep(0.0, 0.12, p) * (1.0 - smoothstep(0.72, 1.0, p));
  float fc = p * 30.0;
  float fl = mix(hash(floor(fc)), hash(floor(fc) + 1.0), smoothstep(0.3, 0.7, fract(fc)));
  vec2 d = (uv - 0.5) * vec2(ratio, 1.0) / (0.5 * sqrt(ratio * ratio + 1.0));
  float light = (1.0 - 0.3 * dot(d, d)) * (1.0 - 0.3 * flicker * fl * env);
  float shade = mix(1.0, 0.92 * light, env);

  vec4 c;
  if (radius + smear < 1e-4) {
    c = gate(c0, yf, yt, light, shade);
    return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
  }
  c = vec4(0.0);
  for (int i = 0; i < TAPS; i++) {
    float fi = float(i);
    float a = fi * 2.39996;
    vec2 o = sqrt((fi + 0.5) / float(TAPS)) * vec2(cos(a) / ratio, sin(a)) * radius;
    o.y += ((fi + 0.5) / float(TAPS) - 0.5) * smear;
    // the gate is the frame: fold the taps back so its edges stay sharp
    vec2 q = 1.0 - abs(1.0 - abs(c0 + o));
    c += gate(q, yf, yt, light, shade);
  }
  c /= float(TAPS);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: Mark Craig
// mrmcsoftware on github and youtube ( http://www.youtube.com/MrMcSoftware )
// License: MIT
// Description: The outgoing image slides out, or the incoming one slides in, toward an edge, a corner or the center
// Tags: slide, directional

// Slides Transition by Mark Craig (Copyright © 2022)

uniform int type; // = 0
// @param Slide the incoming image in instead of the outgoing one out
uniform bool In; // = false
// type: slide to/from which edge, which corner, or center
// In: if true slide new image in, otherwise slide old image out

#define rad2 rad / 2.0

vec4 transition(vec2 uv)
{
vec2 uv0 = uv;
float rad = In ? progress : 1.0 - progress;
float xc1, yc1;
// I used if/else instead of switch in case it's an old GPU
if (type == 0) { xc1 = .5 - rad2; yc1 = 0.0; }
else if (type == 1) { xc1 = 1.0 - rad; yc1 = .5 - rad2; }
else if (type == 2) { xc1 = .5 - rad2; yc1 = 1.0 - rad; }
else if (type == 3) { xc1 = 0.0; yc1 = .5 - rad2; }
else if (type == 4) { xc1 = 1.0 - rad; yc1 = 0.0; }
else if (type == 5) { xc1 = 1.0 - rad; yc1 = 1.0 - rad; }
else if (type == 6) { xc1 = 0.0; yc1 = 1.0 - rad; }
else if (type == 7) { xc1 = 0.0; yc1 = 0.0; }
else if (type == 8) { xc1 = .5 - rad2; yc1 = .5 - rad2; }
uv.y = 1.0 - uv.y;
vec2 uv2;
if ((uv.x >= xc1) && (uv.x <= xc1 + rad) && (uv.y >= yc1) && (uv.y <= yc1 + rad))
	{
	uv2 = vec2((uv.x - xc1) / rad, 1.0 - (uv.y - yc1) / rad);
	return(In ? getToColor(uv2) : getFromColor(uv2));
	}
return(In ? getFromColor(uv0) : getToColor(uv0));
}

// Author: gre
// License: MIT
// Description: The outgoing image is a sheet cut with rows of staggered slits that is pulled from both ends: it lengthens, the slits open into diamonds and the strands between them twist and thin out like expanded metal until only the incoming image is left behind
// Tags: paper, stretch, pattern, 3d, shadow

// @range(0.05, 0.4) Length of a slit and its bridge, relative to the image height
uniform float size; // = 0.16
// @range(0, 3) How much the sheet lengthens as it is pulled
uniform float stretch; // = 1.6
// @range(0, 1) Strength of the shading of the twisting strands and of their shadow
uniform float shading; // = 0.7
// @range(0, 1) How much the sheet narrows at its waist as it is pulled
uniform float neck; // = 0.8
// @param Pull the sheet sideways instead, with vertical slits
uniform bool horizontal; // = false

vec4 transition(vec2 uv) {
  float t = progress;
  float q = t * t * (3.0 - 2.0 * t);
  if (q <= 0.0) return getFromColor(uv);
  vec2 asp = vec2(ratio, 1.0);
  // work with the slits along x and the pull along y
  vec2 p = (uv - 0.5) * asp;
  if (horizontal) p = p.yx;
  float Sy = 1.0 + stretch * q;
  // (ys: -0.5 to 0.5 along the sheet's length)
  float ys = clamp(p.y / (Sy * (horizontal ? ratio : 1.0)), -0.5, 0.5);
  float hw = 0.5 * (horizontal ? 1.0 : ratio);
  float wf = 1.0 - 0.7 * neck * q * (1.0 - 4.0 * ys * ys);
  // (no edge on the frame's border at the start)
  float side = (hw * wf - abs(p.x)) / (0.003 * min(1.0, 200.0 * q) + 1e-7);
  p.x /= wf;
  float a = 0.5 * size;
  float b = 0.22 * size * Sy;
  float j = floor(p.y / b + 0.5);
  float xo = mod(j, 2.0) * a;
  float i = floor((p.x - xo) / (2.0 * a) + 0.5);
  vec2 c = vec2(i * 2.0 * a + xo, j * b);
  vec2 d = p - c;
  // check the two neighbouring rows too: the diamonds interlock
  vec2 d2 = p - vec2(c.x + (p.x > c.x ? a : -a), c.y + (p.y > c.y ? b : -b));
  if (abs(d2.x) / a + abs(d2.y) / b < abs(d.x) / a + abs(d.y) / b) d = d2;

  // the hole: a slit (the bridges between slits keep the sheet whole) that opens into a diamond,
  // slightly larger than the cell at the end, so the strands have gone edge-on
  float grow = 1.0 + 0.12 * q;
  float A = max(a * mix(0.72, 1.0, q) * grow, 1e-4);
  float H = max(b * sqrt(q) * grow, 1e-5);
  float f = abs(d.x) / A + abs(d.y) / H - 1.0;
  float dist = f / sqrt(1.0 / (A * A) + 1.0 / (H * H));
  float e = 0.004;
  // (the edge moves in by its whole softness at the end, so even the finest strands are gone)
  float hole = max(smoothstep(0.0, e, e * q * q * q * q - dist), clamp(0.5 - side, 0.0, 1.0));

  vec4 img = vec4(0.0);
  if (hole < 1.0) {
    vec2 sp = vec2(p.x, p.y / Sy);
    if (horizontal) sp = sp.yx;
    img = getFromColor(clamp(sp / asp + 0.5, 0.0, 1.0));
    float facet = clamp(d.x * d.y / (0.25 * a * b + 1e-6), -1.0, 1.0);
    float rim = clamp(1.0 - dist / (0.25 * b + 1e-5), 0.0, 1.0);
    img.rgb *= 1.0 + shading * q * (0.35 * facet - 0.25 * rim);
    if (hole <= 0.0) return img;
  }
  vec4 bg = getToColor(uv);
  // soft shadow of the mesh (only within the sheet, not beside its waist)
  float sh = (1.0 - smoothstep(0.0, 0.25 * b + e, -dist)) * clamp(0.5 + side, 0.0, 1.0);
  bg.rgb *= 1.0 - 0.45 * shading * sh * (1.0 - q);
  return mix(img, bg, hole);
}

// Author: gre
// License: MIT
// Description: The frame is cut into vertical reels that spin downward like drums, motion-blurred with speed, carrying the outgoing image then the incoming one, and stop one after another from left to right with a small mechanical bounce
// Tags: 3d, spin, stripes, motion-blur

// @range(1, 16, 1) Number of reels
uniform int reels; // = 5
// @range(0, 1) Amount of vertical motion blur while the reels spin fast
uniform float blur; // = 0.6
// @range(0, 0.9) Delay between the first and the last reel's stop, as a part of the transition
uniform float stagger; // = 0.45
// @range(0, 1) Size of the bounce when a reel stops
uniform float bounce; // = 0.5
// @color Color of the separators between the reels
uniform vec4 separator; // = vec4(0.04, 0.04, 0.05, 1.0)

const float PI = 3.141592653589793;
// half of the arc of the drum seen in the frame, in radians
const float ARC = 1.15;
const float SETTLE = 0.1;
const float LINE = 0.006;
const float EDGE = 0.0015;

float stopTime(float i, float n) {
  float order = n > 1.0 ? i / (n - 1.0) : 1.0;
  return (1.0 - SETTLE) * (1.0 - clamp(stagger, 0.0, 0.9) * (1.0 - order));
}

// how far the reel has turned at time t, in image heights: it speeds up, slows down to its stop
// a little past the incoming image and springs back onto it
float reelOffset(float t, float stopT, float turns) {
  float amp = 0.07 * bounce;
  // speed at the stop, matched with the start of the bounce
  float v1 = amp * PI * stopT / (turns * SETTLE);
  float u = clamp(t / stopT, 0.0, 1.0);
  float g = u * u * (3.0 - 2.0 * u) + v1 * (u * u * u - u * u);
  float b = clamp((t - stopT) / SETTLE, 0.0, 1.0);
  return turns * g + amp * sin(PI * b) * (1.0 - b) * (1.0 - b);
}

// the reel's speed at time t, the derivative of reelOffset, in image heights per transition
float reelSpeed(float t, float stopT, float turns) {
  float amp = 0.07 * bounce;
  float v1 = amp * PI * stopT / (turns * SETTLE);
  if (t < stopT) {
    float u = max(t / stopT, 0.0);
    return turns * (6.0 * u * (1.0 - u) + v1 * u * (3.0 * u - 2.0)) / stopT;
  }
  float b = min((t - stopT) / SETTLE, 1.0);
  return amp * (1.0 - b) * (PI * cos(PI * b) * (1.0 - b) - 2.0 * sin(PI * b)) / SETTLE;
}

vec4 transition (vec2 uv) {
  float n = max(float(reels), 1.0);
  float i = min(floor(uv.x * n), n - 1.0);
  float lx = uv.x * n - i;
  float stopT = stopTime(i, n);
  // an odd number of turns, more for the reels that spin longer, so they land on the incoming image
  float turns = 2.0 * floor(stopT * 4.0) + 1.0;

  float drum = smoothstep(0.0, 0.12, progress) * (1.0 - smoothstep(stopT, stopT + SETTLE, progress));
  float y = 2.0 * uv.y - 1.0;
  // theta: the angle around the drum's axis, 0 facing the viewer
  float theta = asin(clamp(y * sin(ARC), -1.0, 1.0));
  float v = mix(uv.y, 0.5 + theta / (2.0 * ARC), drum);
  float depth = (1.0 - cos(theta)) * drum;
  float px = 0.5 + (lx - 0.5) * (1.0 + 0.2 * depth);

  // offset from the resting position, -turns at the start, 0 once landed
  float off = reelOffset(progress, stopT, turns) - turns;
  float speed = abs(reelSpeed(progress, stopT, turns));
  float spread = blur * min(speed * 0.02, 0.22) * drum;

  vec4 c = vec4(0.0);
  float wsum = 0.0;
  for (int k = 0; k < 8; k++) {
    float f = float(k) / 7.0 - 0.5;
    float w = 1.0 - abs(f);
    float vv = v + off + spread * f;
    float seg = floor(vv);
    vec2 q = vec2((i + clamp(px, 0.0, 1.0)) / n, vv - seg);
    vec4 s = mod(seg, 2.0) < 0.5 ? getToColor(q) : getFromColor(q);
    // a thin shadow at the seams between the images, not at the frame's top and bottom edges
    s.rgb *= 1.0 - 0.6 * drum * (1.0 - y * y) * (1.0 - smoothstep(0.0, 0.02, min(q.y, 1.0 - q.y)));
    c += w * s;
    wsum += w;
    if (spread < 1e-4) break;
  }
  c /= wsum;

  float facing = cos(theta);
  c.rgb *= mix(1.0, 0.25 + 0.75 * facing * facing, drum);
  c.rgb += drum * 0.07 * c.a * exp(-12.0 * (y - 0.3) * (y - 0.3));

  float env = smoothstep(0.0, 0.1, progress) * (1.0 - smoothstep(0.9, 1.0, progress));
  float reelW = ratio / n;
  float persp = reelW / (1.0 + 0.2 * depth);
  float dSide = min(px, 1.0 - px) * persp;
  float dInner = min(i > 0.5 ? px : 2.0, i < n - 1.5 ? 1.0 - px : 2.0) * persp;
  float line = 1.0 - smoothstep(0.5 * LINE - EDGE, 0.5 * LINE + EDGE, dInner);
  float outside = 1.0 - smoothstep(-EDGE, 0.0, dSide);
  c.rgb *= 1.0 - 0.35 * env * (1.0 - smoothstep(0.0, 0.03 * reelW + LINE, dInner));
  return mix(c, separator, max(line * env, outside));
}

// Author: gre
// License: MIT
// Description: Billowing smoke drifts in across the outgoing image, with lit tops, darker folds and wispy edges, and thickens until it covers the frame; as it thins out and drifts away, the incoming image shows through
// Tags: smoke, fog, organic, noise, cover

// @param Direction the smoke drifts toward (it comes in from the opposite side); its length is how far it drifts, in frame heights
uniform vec2 direction; // = vec2(0.5, 0.1)
// @range(1, 8) Size of the billows: more, smaller ones with a larger value
uniform float scale; // = 2.5
// @range(0, 1) How much the smoke rolls in from one side rather than everywhere at once
uniform float spread; // = 0.4
// @range(0.05, 1) Softness of the smoke: wispier, more see-through edges with a larger value
uniform float softness; // = 0.5
// @color Color of the smoke, lit from above
uniform vec4 color; // = vec4(0.86, 0.86, 0.88, 1.0)

float hash12(vec2 v) {
  vec3 v3 = fract(vec3(v.xyx) * 0.1031);
  v3 += dot(v3, v3.yzx + 33.33);
  return fract((v3.x + v3.y) * v3.z);
}

float vnoise(vec2 v) {
  vec2 i = floor(v);
  vec2 f = fract(v);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash12(i), hash12(i + vec2(1.0, 0.0)), f.x),
    mix(hash12(i + vec2(0.0, 1.0)), hash12(i + vec2(1.0, 1.0)), f.x),
    f.y
  );
}

float fbm(vec2 v) {
  float sum = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 4; i++) {
    sum += amp * vnoise(v);
    v = mat2(1.6, 1.2, -1.2, 1.6) * v + 5.3;
    amp *= 0.5;
  }
  return sum / 0.9375;
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 pos = (uv - 0.5) * vec2(ratio, 1.0);

  // where along the drift the pixel is: 0 on the side the smoke comes from, 1 on the other
  float len = length(direction);
  vec2 dir = len > 1e-4 ? direction / len : vec2(0.0);
  float ext = 0.5 * (abs(dir.x) * ratio + abs(dir.y)) + 1e-4;
  float along = len > 1e-4 ? 0.5 + 0.5 * dot(pos, dir) / ext : 0.5;

  // the smoke rolls in (until 0.45), covers the whole frame, then thins out (from 0.55),
  // each side of the frame in turn
  float arrive = (p / 0.45) * (1.0 + spread) - spread * along;
  float leave = ((p - 0.55) / 0.45) * (1.0 + spread) - spread * along;
  float body = smoothstep(0.0, 1.0, arrive) * (1.0 - smoothstep(0.0, 1.0, leave));
  // the images switch while the smoke is fully dense everywhere
  float m = smoothstep(0.48, 0.52, p);
  if (body <= 0.0) return m < 0.5 ? getFromColor(uv) : getToColor(uv);

  vec2 q = (pos - direction * (p - 0.5)) * scale;
  vec2 churn = vec2(0.5 * p, -0.35 * p);
  vec2 warp = vec2(fbm(q + vec2(3.1, 1.7) + churn), fbm(q + vec2(8.3, 2.8) - churn));
  vec2 w = q + 1.1 * (warp - 0.5);
  float n = fbm(w);
  // the billows catch the light from above: brighter where the smoke rises toward it
  // (on the coarse octave only, which shapes them)
  float lit = 0.53 * (vnoise(w) - vnoise(w + vec2(0.0, 0.2)));
  float wisp = vnoise(w * 3.3 - 2.0 * churn) - 0.5;

  float edge = 2.0 * body - (1.0 - smoothstep(0.1, 0.6, n)) + 1.6 * body * (1.0 - body) * wisp;
  float d = smoothstep(0.0, softness, edge) * mix(0.5, 1.0, smoothstep(0.2, 0.9, body));

  vec4 base;
  if (m <= 0.0) base = getFromColor(uv);
  else if (m >= 1.0) base = getToColor(uv);
  else {
    vec4 a = getFromColor(uv);
    vec4 b = getToColor(uv);
    base = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
    base = base.a > 0.0 ? vec4(base.rgb / base.a, base.a) : vec4(0.0);
  }
  if (d <= 0.0) return base;

  float shade = 0.92 + 1.3 * lit;
  shade *= mix(0.76, 1.04, smoothstep(0.25, 0.75, n));
  shade = mix(1.0, shade, 0.3 + 0.7 * d);
  vec3 smoke = clamp(color.rgb * shade, 0.0, 1.0);

  // the smoke color mixes as straight RGBA, like every fill color
  return mix(base, vec4(smoke, color.a), d);
}

// Author: gre
// License: MIT
// Description: Blocks switch to the incoming image one at a time, row after row from the top (or column after column from the left), each line running the opposite way to the one before, like a snake winding across the frame
// Tags: wipe, blocks, grid, zigzag

// @param Number of blocks (columns, rows)
uniform ivec2 grid; // = ivec2(8, 6)
// @param Wind down the columns instead of along the rows
uniform bool vertical; // = false
// @range(0, 4) How long each block takes to fade in, in turns of one block (0 switches it at once)
uniform float smoothness; // = 0.5

vec4 transition(vec2 uv) {
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);

  vec2 g = max(vec2(grid), 1.0);
  vec2 cell = min(floor(vec2(uv.x, 1.0 - uv.y) * g), g - 1.0);
  float lines = vertical ? g.x : g.y;
  float len = vertical ? g.y : g.x;
  float line = vertical ? cell.x : cell.y;
  float pos = vertical ? cell.y : cell.x;
  if (mod(line, 2.0) > 0.5) pos = len - 1.0 - pos;
  float order = line * len + pos;

  // block k fades in from k to k + w, on a timeline from 0 to n - 1 + w
  float n = lines * len;
  float w = max(smoothness, 0.001);
  float m = clamp((progress * (n - 1.0 + w) - order) / w, 0.0, 1.0);

  // mixed premultiplied, so transparent images do not bleed their color
  vec4 c = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image spans the frame like a plank held at its sides: it sags in the middle under its own weight, a jagged crack runs up from the bottom, and the two halves snap apart, swing down around their outer top corners and drop out of the frame, revealing the incoming image under their shadow
// Tags: physical, gravity, break, crack, fall

// @range(0, 0.2) How far the middle sags before it cracks
uniform float sag; // = 0.12
// @range(0, 0.1) Sideways jitter of the jagged crack
uniform float jaggedness; // = 0.035
// @color Color of the shadow cast on the incoming image
uniform vec4 shadow; // = vec4(0.0, 0.0, 0.0, 0.5)

const float PI = 3.141592653589793;
const float BREAK = 0.34;
const float AA = 0.002;

float hash(float n) {
  n = fract(n * 0.1031);
  n *= n + 33.33;
  n *= n + n;
  return fract(n);
}

float jag(float y, float freq, float seed) {
  float k = y * freq;
  return mix(hash(floor(k) + seed), hash(floor(k) + seed + 1.0), fract(k)) - 0.5;
}

float crackX(float y) {
  return 0.5 * ratio + jaggedness * (jag(y, 7.0, 3.0) + 0.4 * jag(y, 23.0, 41.0));
}

// p is mirrored for the right half, so both halves hinge on their top corner at x = 0
vec2 toPiece(vec2 p, mat2 rot, float fall, float bend) {
  vec2 q = rot * (p + vec2(0.0, fall - 1.0)) + vec2(0.0, 1.0);
  q.y += bend * sin(PI * clamp(q.x / ratio, 0.0, 1.0));
  return q;
}

float toCrack(vec2 q, float side) {
  float c = crackX(q.y);
  return (side > 0.0 ? ratio - c : c) - q.x;
}

// outer edges pushed out by one AA width so the halves tile the frame exactly at rest
float cover(vec2 q, float e, float w) {
  vec2 d = min(q, vec2(ratio, 1.0) - q);
  return clamp(min(min(d.x, d.y), e) / w + 1.0, 0.0, 1.0);
}

vec4 shade(vec2 q, float e, float side, float sa, float front, float t) {
  vec4 col = getFromColor(vec2(side > 0.0 ? 1.0 - q.x / ratio : q.x / ratio, q.y));
  float crack = (1.0 - smoothstep(0.0, 0.005, e)) * (1.0 - smoothstep(front - 0.05, front, q.y));
  col.rgb *= (1.0 - 0.75 * crack * (1.0 - smoothstep(0.0, 0.08, t))) * (1.0 - 0.3 * sa * smoothstep(0.0, 0.5 * ratio, q.x));
  return col;
}

vec4 transition(vec2 uv) {
  vec2 p = vec2(uv.x * ratio, uv.y);
  vec2 m = vec2(ratio - p.x, p.y);
  float load = smoothstep(0.0, BREAK, progress);
  float t = clamp((progress - BREAK) / (1.0 - BREAK), 0.0, 1.0);
  float bend = sag * load * (1.0 - smoothstep(0.0, 0.3, t));
  float front = 1.12 * smoothstep(0.12, BREAK, progress) - 0.06;
  float a = 1.1 * t * (0.6 + 0.4 * t);
  float d = max(t - 0.25, 0.0) / 0.75;
  float fall = 1.1 * d * d;
  float ca = cos(a), sa = sin(a);
  mat2 rot = mat2(ca, sa, -sa, ca);

  vec2 ql = toPiece(p, rot, fall, bend);
  vec2 qr = toPiece(m, rot, fall, bend);
  float el = toCrack(ql, -1.0);
  float er = toCrack(qr, 1.0);
  float cl = cover(ql, el, AA);
  float cr = cover(qr, er, AA);

  float lift = 0.3 * load + 0.7 * smoothstep(0.0, 0.4, t);
  vec2 o = vec2(0.015, -0.03) * lift;
  float soft = 0.004 + 0.05 * lift;
  vec2 sl = toPiece(p - o, rot, fall, bend);
  vec2 sr = toPiece(m - vec2(-o.x, o.y), rot, fall, bend);
  float sh = shadow.a * lift * max(cover(sl, toCrack(sl, -1.0), soft), cover(sr, toCrack(sr, 1.0), soft));

  vec4 to = getToColor(uv);
  float alpha = sh + to.a * (1.0 - sh);
  to = vec4((shadow.rgb * sh + to.rgb * to.a * (1.0 - sh)) / max(alpha, 1e-5), alpha);
  vec4 col = mix(to, shade(ql, el, -1.0, sa, front, t), cl);
  return mix(col, shade(qr, er, 1.0, sa, front, t), cr);
}

// Author: gre
// License: MIT
// Description: A camera flash freezes the outgoing image into a printed photo with a white border, which shrinks, tilts and drops out of the frame, revealing the incoming image behind it
// Tags: photo, flash, scale, rotate, fall, shadow

// @range(0, 1) How much the photo turns as it drops
uniform float tilt; // = 0.35
// @range(0, 0.15) Width of the photo's border, relative to the frame height
uniform float border; // = 0.04
// @range(0, 1) Strength of the camera flash
uniform float flash; // = 0.85
// @range(0, 1) Darkness of the soft shadow the photo casts on the incoming image
uniform float shadow; // = 0.45
// @color Color of the photo's border
uniform vec4 borderColor; // = vec4(0.96, 0.94, 0.89, 1.0)

const float SHRINK = 0.24; // how much smaller the photo gets before it drops
const float RADIUS = 0.008;
const float AA = 0.0015;

float roundedBox(vec2 q, vec2 b, float r) {
  vec2 d = abs(q) - b + r;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - r;
}

vec4 premultiply(vec4 c) {
  return vec4(c.rgb * c.a, c.a);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 q = (uv - 0.5) * asp;
  vec2 halfImage = 0.5 * asp;
  vec2 halfCard = halfImage + border;

  float k = smoothstep(0.05, 0.4, p);
  float t = clamp((p - 0.3) / 0.7, 0.0, 1.0);
  float fall = t * t;
  float s = 1.0 - SHRINK * k;
  float a = -tilt * (0.12 * k + 0.88 * fall);
  float bound = (abs(sin(tilt)) * halfCard.x + abs(cos(tilt)) * halfCard.y) * (1.0 - SHRINK);
  float lift = 0.035 * k * (1.0 - fall);
  vec2 center = vec2(0.08 * fall, lift - (0.5 + bound + 0.1) * fall);

  float rad = RADIUS * k;

  float ca = cos(a), sa = sin(a);
  mat2 unrotate = mat2(ca, -sa, sa, ca);

  vec4 col = getToColor(uv);
  float sh = shadow * k;
  if (sh > 0.0) {
    vec2 rs = unrotate * (q - center - vec2(0.012, -0.022) * k) / s;
    float ds = roundedBox(rs, halfCard, rad) * s;
    float blur = 0.035 * s;
    col.rgb *= 1.0 - sh * (1.0 - smoothstep(-blur, blur, ds));
  }
  col = premultiply(col);

  vec2 r = unrotate * (q - center) / s;
  float dCard = roundedBox(r, halfCard, rad) * s;
  float dImage = roundedBox(r, halfImage, 0.0) * s;
  // the edges are pushed out by one antialiasing width, so the photo covers the full frame at the start
  float cardCover = clamp(1.5 - dCard / AA, 0.0, 1.0);
  float imageCover = clamp(1.5 - dImage / AA, 0.0, 1.0);
  // the image replaces what is behind it, while the border is laid over the incoming image, which shows through a translucent border
  vec4 photo = premultiply(getFromColor(clamp(r / asp + 0.5, 0.0, 1.0)));
  vec4 paper = premultiply(borderColor);
  vec4 card = mix(paper + col * (1.0 - paper.a), photo, imageCover);
  col = mix(col, card, cardCover);
  if (col.a <= 0.0) return vec4(0.0);
  col.rgb /= col.a;

  // the flash only adds light: a quick bloom to white that fades as the photo comes out
  float f = flash * smoothstep(0.0, 0.05, p) * (1.0 - smoothstep(0.05, 0.3, p));
  col.rgb = 1.0 - (1.0 - col.rgb) * (1.0 - f);
  return col;
}

// Author: gre
// License: MIT
// Description: A six-armed paper snowflake is cut out of the outgoing picture: the rest of the sheet drops away around it, its punched holes fall out, and the snowflake, still made of the picture, hangs by a thin tab from the top edge, swings and turns, then tears loose and falls, revealing the incoming picture
// Tags: paper, cut, gravity, shape

// @range(0.35, 0.5) Size of the snowflake, in frame heights from its center to an arm tip
uniform float size; // = 0.47

const float PI = 3.141592653589793;
const vec2 SHADOW = vec2(0.016, -0.028);
const vec3 PAPER = vec3(0.94, 0.93, 0.9);

float aa(float d) { return clamp(d * 400.0 + 1.0, 0.0, 1.0); }
float frameDist(vec2 S) { vec2 d = min(S, vec2(ratio, 1.0) - S); return min(d.x, d.y); }
float drop(float t) { t = clamp(t, 0.0, 1.0); return t * t; }
mat2 rot(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

float segment(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a, ba = b - a;
  return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}

// signed angle from the nearest arm, the arms pointing up so the tab sits on an arm tip
// the offset keeps atan defined at the center
float armAngle(vec2 v) { return mod(atan(v.x, v.y + 1e-6) + PI / 6.0, PI / 3.0) - PI / 6.0; }

vec2 fold6(vec2 v) {
  float a = abs(armAngle(v));
  return length(v) * vec2(cos(a), sin(a));
}

float flakeShape(vec2 v) {
  vec2 q = fold6(v);
  float d = length(q) - 0.38;
  d = min(d, max(abs(q.y) - 0.12 + 0.05 * q.x, q.x - 0.9));
  d = min(d, segment(q, vec2(0.46, 0.0), vec2(0.61, 0.25)) - 0.072);
  d = min(d, segment(q, vec2(0.7, 0.0), vec2(0.79, 0.15)) - 0.058);
  d = min(d, length(q - vec2(0.9, 0.0)) - 0.095);
  return d;
}

float holes(vec2 v) {
  vec2 q = fold6(v);
  float h = min(length(q - vec2(0.24, 0.0)) - 0.05, length(q - vec2(0.24, 0.14)) - 0.035);
  return min(h, length(q) - 0.07);
}

// the flake and its hanging tab, which ends at the top of the frame
float flake(vec2 S, vec2 c, float sc) {
  float tab = max(abs(S.x - c.x) - 0.02 * sc, max(c.y + 0.9 * sc - S.y, S.y - 1.0));
  return min(flakeShape((S - c) / sc) * sc, tab);
}

// the sheet point seen at Q on the hanging flake, which turns about the vertical through the tab
vec2 hang(vec2 Q, vec2 tab, float ang, float squeeze) {
  vec2 d = rot(ang) * (Q - tab);
  return tab + vec2(d.x / squeeze, d.y);
}

vec2 sheet(vec2 Q, float t) {
  return rot(0.15 * t) * (Q + vec2(0.0, 2.6 * t - 1.0)) + vec2(0.0, 1.0);
}

float cutSweep(vec2 v, float t) { return step(fract(atan(v.x, v.y + 1e-6) * 0.5 / PI + 1.0), t); }

vec4 transition(vec2 uv) {
  float p = progress, R = ratio;
  vec2 Q = vec2(uv.x * R, uv.y);
  float sc = size * min(1.0, R * 1.1);
  vec2 c = vec2(0.5 * R, 0.97 - 0.9 * sc);
  vec2 tab = vec2(c.x, 1.0);

  float cutT = 1.2 * smoothstep(0.0, 0.13, p) - 0.1;
  float cutA = smoothstep(0.0, 0.05, p) * (1.0 - smoothstep(0.75, 0.95, p));
  float wasteT = drop((p - 0.13) / 0.34);
  float holeT = drop((p - 0.26) / 0.3);
  float s = clamp((p - 0.36) / 0.64, 0.0, 1.0);
  float fall = drop((p - 0.7) / 0.3);
  float ang = 0.3 * sin(s * 10.0) * exp(-3.5 * s) * smoothstep(0.0, 0.12, s) + 0.6 * fall;
  float turn = 0.5 * sin(s * 7.0 + 0.6) * exp(-2.5 * s) * smoothstep(0.0, 0.15, s) + 1.1 * fall;
  float squeeze = cos(turn);
  float lift = smoothstep(0.08, 0.3, p);
  vec2 drop2 = vec2(0.0, 2.2 * fall);

  vec4 col = getToColor(uv);
  vec2 Ssh = hang(Q - SHADOW + drop2, tab, ang, squeeze);
  float fsh = max(flake(Ssh, c, sc), -holes((Ssh - c) / sc) * sc);
  col.rgb *= 1.0 - 0.4 * lift * smoothstep(0.02, -0.02, fsh);

  vec2 W = sheet(Q, wasteT);
  vec2 Wsh = sheet(Q - SHADOW, wasteT);
  col.rgb *= 1.0 - 0.35 * smoothstep(0.0, 0.1, wasteT) * smoothstep(-0.03, 0.03, min(frameDist(Wsh), flake(Wsh, c, sc)));
  float f = flake(W, c, sc);
  vec4 a = getFromColor(clamp(vec2(W.x / R, W.y), 0.0, 1.0));
  a.rgb *= 1.0 - 0.45 * cutA * smoothstep(0.004, 0.0, f) * cutSweep(W - c, cutT);
  col = mix(col, a, aa(f) * aa(frameDist(W)));

  vec2 H = Q + vec2(0.0, 2.6 * holeT);
  float h = holes((H - c) / sc) * sc;
  a = getFromColor(clamp(vec2(H.x / R, H.y), 0.0, 1.0));
  a.rgb *= 1.0 - 0.45 * cutA * smoothstep(0.004, 0.0, -h);
  col = mix(col, a, aa(-h));

  vec2 S = hang(Q + drop2, tab, ang, squeeze);
  vec2 v = (S - c) / sc;
  f = flake(S, c, sc);
  h = holes(v) * sc;
  float edge = min(-f, h);
  a = getFromColor(clamp(vec2(S.x / R, S.y), 0.0, 1.0));
  // folded paper: each arm is lit a little differently on either side of its crease
  float aA = armAngle(v);
  float crease = sign(aA) * smoothstep(0.0, 0.02, abs(aA) * length(v)) * smoothstep(0.0, 0.02, (PI / 6.0 - abs(aA)) * length(v));
  a.rgb *= 1.0 + lift * (0.04 * crease - 0.12 * abs(sin(turn)));
  a.rgb = mix(a.rgb, PAPER, 0.65 * lift * (1.0 - smoothstep(0.0, 0.0035, edge)));
  a.rgb *= 1.0 - 0.45 * cutA * (1.0 - lift) * smoothstep(0.004, 0.0, edge) * max(cutSweep(v, cutT), step(h, 0.01));
  col = mix(col, a, aa(-f) * aa(h) * aa(frameDist(S)));
  return col;
}

// Author: gre
// License: MIT
// Description: A drop of water lands on the outgoing image as if it were a sheet of paper: a wet stain with a dark tide line spreads from it, the soaked paper turns see-through and cockles, sags into a bowl under its weight, then tears out in the middle and drops away, and the ragged hole follows the stain out to the edges onto the incoming image
// Tags: physical, paper, water, tear, organic

// @param Where the drop lands
uniform vec2 center; // = vec2(0.45, 0.55)
// @range(0, 1) How see-through the soaked paper gets
uniform float seeThrough; // = 0.3
// @range(0, 1) How deep the wet paper sags before it tears
uniform float sag; // = 0.6

const float TEAR = 0.3;
const float F = 1.6;

float hash(vec2 p) {
  vec3 q = fract(p.xyx * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + 1.0), f.x), f.y);
}

float ease(float x) {
  x = clamp(x, 0.0, 1.0);
  return x * x * (3.0 - 2.0 * x);
}

vec2 mirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

float bowl(float r, float rr) {
  float s = min(r / rr, 1.0);
  return (1.0 - s * s) * (1.0 - s * s);
}

vec4 transition(vec2 uv) {
  vec2 R = vec2(ratio, 1.0);
  vec2 c = center * R;
  vec2 P = uv * R;
  float far = length(max(c, R - c));
  float p = progress;

  vec2 d = P - c;
  float r = length(d);
  vec2 dir = r > 1e-5 ? d / r : vec2(1.0, 0.0);
  // noise sampled on the direction circle keeps the ragged fronts seamless all around
  float ragW = 1.0 + 0.35 * (noise(dir * 2.2 + 3.1) - 0.5) + 0.12 * (noise(dir * 7.0 + 9.0) - 0.5);
  float ragH = 1.0 + 0.3 * (noise(dir * 2.6 + 5.7) - 0.5) + 0.12 * (noise(dir * 6.0 + 1.3) - 0.5);

  float stain = 1.35 * far * ease(p / 0.7);
  float rw = stain * ragW;
  float th = clamp((p - TEAR) / (1.0 - TEAR), 0.0, 1.0);
  float rh = 1.3 * far * pow(th, 1.3) * ragH;

  float rr = max(0.8 * stain, 1e-3);
  // depth follows the stain's width so the first dimple stays shallow instead of reading as a hole
  float depth = sag * 0.6 * min(rr, 0.5) * ease(p / TEAR) * (1.0 - ease(th / 0.15));
  float droop = sag * 0.3 * ease(th / 0.06) * (1.0 - ease(th / 0.9)) * exp(-max(r - rh, 0.0) / 0.06);
  vec2 S = P;
  for (int i = 0; i < 3; i++) {
    S = c + d * (F + depth * bowl(length(S - c), rr) + droop) / F;
  }
  // outside starts within the hole's antialiased band so the rim covers it
  float outside = clamp((r - rh) * 300.0 + 1.0, 0.0, 1.0);
  float s = min(r / rr, 1.0);
  float z = depth * (1.0 - s * s) * (1.0 - s * s) + droop;
  float slope = 4.0 * depth * s * (1.0 - s * s) / rr + droop / 0.06 * outside;

  vec4 from = getFromColor(mirror(S / R));
  vec4 to = getToColor(uv);
  float wetEdge = rw - length(S - c);
  float wet = clamp(wetEdge * 300.0, 0.0, 1.0);
  float soak = smoothstep(0.0, 0.2, wetEdge);
  vec2 n = S * 14.0;
  float n0 = noise(n);
  float cockle = ((noise(n - vec2(0.3, 0.0)) - n0) - (noise(n - vec2(0.0, 0.3)) - n0)) * 0.7 * soak;
  vec3 paper = from.rgb * (1.0 - 0.18 * wet - 0.1 * soak + cockle);
  paper = mix(paper, to.rgb * 0.85, seeThrough * soak);
  float tide = wetEdge / 0.012;
  paper *= 1.0 - 0.3 * exp(-tide * tide) * wet;
  paper *= clamp(1.0 - 0.8 * z + 0.35 * slope * dot(dir, vec2(-0.6, 0.8)), 0.3, 1.15);
  float rim = (1.0 - smoothstep(0.0, 0.012, r - rh)) * outside * ease(th / 0.02);
  paper = mix(paper, vec3(0.93, 0.91, 0.86), 0.75 * rim);
  vec4 sheet = vec4(paper, mix(from.a, to.a, seeThrough * soak));

  float fall = clamp((p - TEAR) / 0.35, 0.0, 1.0);
  float zp = depth + 6.0 * fall * fall;
  vec2 Sp = c + d * (F + zp) / F;
  float inPlug = clamp((0.16 * ragH * (1.0 - 0.1 * fall) - length(Sp - c)) * 300.0, 0.0, 1.0) * (1.0 - fall);
  vec4 plug = getFromColor(mirror(Sp / R));
  plug = mix(vec4(plug.rgb * 0.72, plug.a), vec4(to.rgb * 0.85, to.a), seeThrough);
  plug.rgb *= (1.0 - 0.8 * depth) * (1.0 - 0.6 * fall);
  vec4 below = mix(to, plug, inPlug * ease(th / 0.02));
  below.rgb *= 1.0 - 0.35 * exp(-max(rh - r, 0.0) / 0.05) * (1.0 - th);

  float hole = clamp((rh - r) * 300.0, 0.0, 1.0);
  return mix(sheet, below, hole);
}

// Author: gre
// License: MIT
// Description: A drop of soap touches the outgoing image, which floats on water like a skin: the skin rushes away from the drop and piles up into a glossy, wrinkled rim that is shoved out of the frame, leaving the incoming image under clear, rippling water
// Tags: liquid, surface-tension, push, radial, physical

// @param Where the drop touches the skin
uniform vec2 center; // = vec2(0.42, 0.56)
// @range(0, 1) How much the piled-up skin wrinkles
uniform float crumple; // = 0.8

const float TAU = 6.2831853;
const float AA = 0.002;
const vec3 LIGHT = vec3(-0.45, 0.55, 0.7);
const vec2 LIGHT_XY = vec2(-0.633, 0.774);
const vec3 HALFWAY = vec3(-0.244, 0.299, 0.923);

float sdHash(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

// periodic with period n so the angle wrap leaves no seam
float sdNoise(float x, float n) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(sdHash(mod(i, n)), sdHash(mod(i + 1.0, n)), f);
}

vec2 sdMirror(vec2 v) {
  return 1.0 - abs(1.0 - mod(v, 2.0));
}

// offset keeps atan defined at the drop's exact center
float sdAngle(vec2 q) {
  return atan(q.y, q.x + 1e-9) / TAU + 0.5;
}

float sdFront(float th, float R) {
  return R * (1.0 + 0.08 * crumple * (sdNoise(th * 7.0, 7.0) + 0.5 * sdNoise(th * 19.0, 19.0) - 0.75));
}

float sdHeight(vec2 q, float R0, float L) {
  float r = length(q);
  float th = sdAngle(q);
  float R = sdFront(th, R0);
  float d = max(r - R, 0.0);
  float comp = R / L * exp(-d / L);
  float T = comp / (1.0 + comp);
  float wob = 9.0 * sdNoise(th * 13.0, 13.0) + 7.0 * sdNoise(th * 37.0, 37.0);
  // angular detail would crowd into spikes on a small disc
  float folds = sin(d * 110.0 + wob) * sdNoise(th * 53.0 + d * 40.0, 53.0) * smoothstep(0.05, 0.3, R);
  float lip = 1.0 - exp(-d / 0.004);
  return 0.008 * T * lip * (1.0 + 1.4 * crumple * T * folds);
}

vec4 transition(vec2 uv) {
  vec2 a = vec2(ratio, 1.0);
  vec2 q = (uv - center) * a;
  float r = length(q);
  vec2 dir = q / max(r, 1e-5);
  float th = sdAngle(q);
  float rmax = length(max(center, 1.0 - center) * a);

  float t = progress;
  float e = t * (1.4 - 0.4 * t);
  float L = 0.02 + 0.05 * e;
  // the lowest point of the noisy front still clears the farthest corner at the end
  float R0 = e * (rmax + 0.02) / (1.0 - 0.06 * crumple);
  float R = sdFront(th, R0);

  float d = max(r - R, 0.0);
  float fall = exp(-d / L);
  float s = max(r - R * fall, 0.0);
  float comp = R / L * fall;
  float T = comp / (1.0 + comp);

  const vec2 EPS = vec2(0.0015, 0.0);
  vec2 grad = vec2(
    sdHeight(q + EPS, R0, L) - sdHeight(q - EPS, R0, L),
    sdHeight(q + EPS.yx, R0, L) - sdHeight(q - EPS.yx, R0, L)
  ) / (2.0 * EPS.x);
  vec3 n = normalize(vec3(-grad, 1.0));
  float diffuse = max(1.0 + 0.9 * (dot(n, LIGHT) - LIGHT.z), 0.0);
  // subtracting the flat surface's highlight keeps the untouched skin exact
  float spec = max(pow(max(dot(n, HALFWAY), 0.0), 50.0) - pow(HALFWAY.z, 50.0), 0.0);

  vec2 suv = center + (dir * s - grad * 0.004) / a;
  vec4 skin = getFromColor(sdMirror(suv));
  skin.rgb *= diffuse * (1.0 - 0.18 * T);
  skin.rgb += 0.6 * spec * T * skin.a;

  float behind = max(R - r, 0.0);
  float calm = 1.0 - t;
  float k = behind * 70.0 - t * 38.0;
  float env = calm * calm * exp(-behind * 3.0);
  float wave = 0.009 * sin(k) + 0.005 * sin(k * 0.43 + 1.7);
  vec4 water = getToColor(sdMirror(uv - dir * env * wave / a));
  water.rgb *= 1.0 + 0.25 * env * cos(k) * dot(dir, LIGHT_XY);
  float shadow = T * exp(-behind / 0.03) * (0.5 + 0.5 * dot(dir, LIGHT_XY));
  water.rgb *= 1.0 - 0.45 * calm * shadow;

  float m = mix(1.0, smoothstep(-AA, AA, r - R), smoothstep(0.0, 4.0 * AA, R));
  return mix(water, skin, m);
}

// Author: gre
// License: MIT
// Description: The incoming image wells up from one point as a round bubble while the outgoing one streams away along curved field lines and drains into a second point, both pictures flowing like a field between two charges
// Tags: conformal, flow, warp, bubble, mobius

// @param Point the incoming image wells up from
uniform vec2 source; // = vec2(0.1, 0.5)
// @param Point the outgoing image drains into
uniform vec2 sink; // = vec2(0.9, 0.5)
// @range(0.5, 4) How far the pictures travel along the field lines
uniform float flow; // = 1.4
// @range(-2.5, 2.5) Spin of the flow around the two points, 0 for straight field lines
uniform float swirl; // = 0.0
// @range(0, 1) Shadow and highlight along the rim of the bubble
uniform float shading; // = 0.6

vec2 cmul(vec2 a, vec2 b) { return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x); }
vec2 cdiv(vec2 a, vec2 b) { return vec2(a.x * b.x + a.y * b.y, a.y * b.x - a.x * b.y) / max(dot(b, b), 1e-12); }

// the outer field lines bring in content from beyond the frame
vec2 mirrorUv(vec2 uv) { return 1.0 - abs(1.0 - mod(uv, 2.0)); }

// w = (z-A)/(z-B) sends source/sink to 0/infinity: scaling w slides points along the circular field lines
vec2 unflow(vec2 w, vec2 A, vec2 B, vec2 asp, float s, float a) {
  vec2 v = cmul(w, exp(s) * vec2(cos(a), sin(a)));
  return mirrorUv(cdiv(A - cmul(B, v), vec2(1.0, 0.0) - v) / asp + 0.5);
}

vec4 transition(vec2 uv) {
  float t = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 A = (source - 0.5) * asp, B = (sink - 0.5) * asp;
  if (length(B - A) < 0.01) B = A + vec2(0.01, 0.0);
  float ab = length(B - A);
  vec2 z = (uv - 0.5) * asp;
  vec2 w = cdiv(z - A, z - B);

  float e = t * t * (3.0 - 2.0 * t);
  // the outer field lines loop through off-frame space: slow them down so little of it streams in;
  // a spin above ~2.76 would let some point of w * exp(i a h) reach 1, a pole of unflow
  float h = 0.5 - 0.5 * w.x * inversesqrt(max(dot(w, w), 1e-12));
  float a = clamp(swirl, -2.5, 2.5) * h;
  vec4 from = getFromColor(unflow(w, A, B, asp, -flow * h * e, -a * e));
  vec4 to = getToColor(unflow(w, A, B, asp, flow * h * (1.0 - e), a * (1.0 - e)));

  // seam: the Apollonius circle |w| = k, k = (t / (1 - t))^1.8, written with q = k^2 / (1 + k^2) so nothing overflows
  float p0 = pow(t, 3.6), p1 = pow(1.0 - t, 3.6);
  float q = p0 / (p0 + p1);
  vec2 za = z - A, zb = z - B;
  float d = ((1.0 - q) * dot(za, za) - q * dot(zb, zb))
    / (length((1.0 - 2.0 * q) * z - (1.0 - q) * A + q * B) + sqrt(q * (1.0 - q)) * ab);
  float radius = sqrt(q * (1.0 - q)) * ab / max(abs(1.0 - 2.0 * q), 1e-4);
  float rim = clamp(0.3 * radius, 1e-4, 0.07);

  // the bias keeps a pixel exactly on the source or sink on the right side at both ends
  float m = smoothstep(-0.003, 0.003, d + 0.003 * (1.0 - 2.0 * t));
  float env = shading * 4.0 * t * (1.0 - t);
  from.rgb *= 1.0 - 0.55 * env * exp(-max(d, 0.0) / rim);
  to.rgb += 0.3 * env * exp(-d * d / (0.08 * rim * rim)) * (1.0 - m);
  return mix(to, from, m);
}

// Author: gre
// License: MIT
// Description: Comic-style speed lines shoot in from the edges of the frame toward a focus point as the outgoing image punches in; at the peak it cuts to the incoming image, which settles back as the lines retract to the edges
// Tags: comic, lines, radial, zoom, stylized

// @param Point the lines converge to, from (0, 0) at the bottom left to (1, 1) at the top right
uniform vec2 center; // = vec2(0.5, 0.5)
// @color Color of the lines
uniform vec4 lineColor; // = vec4(1.0, 1.0, 1.0, 1.0)
// @range(30, 240) Number of lines around the focus point
uniform float density; // = 110.0
// @range(0, 1) Size of the clear area around the focus point at the peak, from almost nothing to the whole frame
uniform float focus; // = 0.35
// @range(0, 0.5) How much the images punch in toward the focus point
uniform float zoom; // = 0.12

const float PI = 3.141592653589793;
const float AA = 0.0012;

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// how far the lines are in, from 0 (all out of the frame) to 1 (peak), for a line with random h:
// each line shoots in up to a little later than the others and retracts the same way
float reachOf(float h) {
  float d = 0.05 * h;
  float a = 1.0 - clamp((progress - d) / 0.4, 0.0, 1.0);
  float b = clamp((progress - 0.5 - d) / 0.4, 0.0, 1.0);
  return (1.0 - a * a * a) * (1.0 - b * b * b);
}

// coverage of one layer of lines: n angular cells around the focus point (a in 0..1),
// at most one tapered line per cell. e is the elliptical radius (1 at the edges of the frame),
// r the radius in frame heights, E the elliptical radius where the ray leaves the frame
float layer(float a, float e, float r, float n, float seed, float E) {
  // (a can be exactly 1, which is cell 0 again)
  float cell = mod(floor(a * n), n);
  float h1 = hash12(vec2(cell, seed));
  float h2 = hash12(vec2(cell, seed + 7.0));
  float h3 = hash12(vec2(cell, seed + 13.0));
  float on = step(0.22, h1);
  float h4 = hash12(vec2(cell, seed + 50.0 + floor(progress * 12.0)));
  // (a share of the way from the frame's edge to the focus point, so that the burst stays even
  // when the focus point is off-center)
  float len = 1.0 - 0.85 * h2 * h2 - 0.15 * h4;
  float tipPeak = E * (1.0 - (1.0 - focus) * (0.55 + 0.45 * len));
  float tip = mix(E + 0.05, tipPeak, reachOf(h3));
  float t = clamp((e - tip) / max(E * (0.2 + 0.5 * h2), 1e-4), 0.0, 1.0);
  float cellWidth = 2.0 * PI * r / n;
  // its position across the cell, and its width, kept so that its antialiased edges stay in the cell
  float offset = 0.3 + 0.4 * h3;
  float width = min(cellWidth * (0.06 + 0.22 * h1) * sqrt(t), (0.5 - abs(offset - 0.5)) * cellWidth - AA);
  float across = abs(fract(a * n) - offset) * cellWidth;
  return on * (1.0 - smoothstep(width - AA, width + AA, across)) * step(tip, e);
}

vec4 transition(vec2 uv) {
  float p = progress;
  vec2 asp = vec2(ratio, 1.0);
  vec2 d = (uv - center) * asp;
  float r = length(d);
  // (nudged off zero, where atan is undefined)
  float a = atan(d.y, d.x + 1e-6) / (2.0 * PI) + 0.5;
  // elliptical radius, following the shape of the frame: 1 at the middle of its edges
  // when the focus point is in the middle
  float e = length((uv - center) * 2.0);
  // where the ray from the focus point through this pixel leaves the frame, so that every line
  // enters the frame at once
  vec2 w = uv - center;
  vec2 room = vec2(w.x > 0.0 ? 1.0 - center.x : center.x, w.y > 0.0 ? 1.0 - center.y : center.y);
  vec2 exits = room / max(abs(w), vec2(1e-6));
  float E = e * min(exits.x, exits.y);

  float k = p < 0.5 ? smoothstep(0.0, 0.5, p) : 1.0 - smoothstep(0.5, 1.0, p);
  float s = 1.0 - zoom * k * k;
  // (between the focus point and uv, so in the frame)
  vec2 q = center + (uv - center) * s;
  vec4 c = p < 0.5 ? getFromColor(q) : getToColor(q);

  // two interleaved layers of lines so that their spacing looks random
  float n = max(floor(density), 2.0);
  float l = layer(a, e, r, n, 1.0, E);
  l = max(l, layer(fract(a + 0.5 / n), e, r, n, 31.0, E));
  l *= lineColor.a;

  vec4 pc = vec4(c.rgb * c.a, c.a);
  pc = pc * (1.0 - l) + vec4(lineColor.rgb, 1.0) * l;
  return pc.a > 0.0 ? vec4(pc.rgb / pc.a, pc.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: The outgoing image wraps itself onto a shaded ball that shrinks and rolls away, revealing the incoming image under its shadow
// Tags: 3d, sphere, roll, wrap, shape

// @param Direction the ball rolls away toward
uniform vec2 direction; // = vec2(1.0, 0.0)
// @range(0.1, 0.5) Radius of the ball once wrapped, relative to the shorter side of the frame
uniform float size; // = 0.3
// @range(0, 1) Strength of the light and shading on the ball
uniform float shading; // = 0.6
// @range(0, 1) Darkness of the soft shadow the ball casts on the incoming image
uniform float shadow; // = 0.5

const float PI = 3.14159265;
const float AA = 0.0015;
const vec3 LIGHT = vec3(-0.5, 0.6, 1.0) / 1.2689;

vec4 transition(vec2 uv) {
  vec4 b = getToColor(uv);

  vec2 dir = length(direction) > 0.0 ? normalize(direction) : vec2(1.0, 0.0);
  vec2 side = vec2(-dir.y, dir.x);
  vec2 p = (uv - 0.5) * vec2(ratio, 1.0);
  float shorter = min(ratio, 1.0);
  float r0 = clamp(size, 0.1, 0.5) * shorter;

  // the image curves into a ball (infinite radius: exactly flat at the start), then the
  // ball shrinks while rolling away until it and its shadow have left the frame
  float w = clamp(progress / 0.45, 0.0, 1.0);
  w = 1.0 - (1.0 - w) * (1.0 - w);
  float away = smoothstep(0.3, 1.0, progress);
  away *= away;
  float wrapped = r0 / max(w, 1e-4);
  float radius = wrapped * mix(1.0, 0.5, away);
  // the image is pulled tighter as it wraps, so that it ends up covering the whole ball
  // (its shortest half extent reaches around to the back)
  float tight = mix(1.0, min(1.0, 0.48 * shorter / (PI * r0)), w * w);
  float paper = radius * tight;
  float e = 0.5 * (abs(dir.x) * ratio + abs(dir.y));
  // far enough that the ball (0.5 * r0 by then) and its shadow (within 0.9 * r0 of it) have left
  float full = e + 1.1 * r0 + 2.0 * AA;
  float travel = away * full;
  vec2 center = dir * travel;
  // rolling without slipping: the integral of dtravel / radius while the radius shrinks
  float angle = -2.0 * full * log(1.0 - 0.5 * away) / wrapped;

  vec2 d = p - center;
  float r = length(d);

  vec2 sd = d - vec2(0.25, -0.3) * radius * w;
  float sh = shadow * w * (1.0 - smoothstep(0.6 * radius, 1.4 * radius, length(sd)));
  vec4 bg = vec4(b.rgb * b.a * (1.0 - sh), b.a);

  vec4 ball = vec4(0.0);
  float cover = 1.0 - smoothstep(radius - AA, radius + AA, r);
  if (cover > 0.0) {
    // normal of the visible point of the ball (no squared radius, which overflows when it is huge)
    vec2 nd = d / radius;
    vec3 n = vec3(nd, sqrt(max(1.0 - dot(nd, nd), 0.0)));
    float u = dot(n.xy, dir);
    float s = dot(n.xy, side);
    float cu = cos(angle), su = sin(angle);
    vec3 q = vec3(u * cu - n.z * su, s, u * su + n.z * cu);
    // the image is wrapped around the ball from its front point, distances kept along the surface
    float lq = length(q.xy);
    float arc = atan(lq, q.z) * paper;
    vec2 img = lq > 0.0 ? (q.x * dir + q.y * side) / lq * arc : vec2(0.0);
    vec2 iuv = img / vec2(ratio, 1.0) + 0.5;
    vec2 edge = min(iuv, 1.0 - iuv) * vec2(ratio, 1.0);
    float inside = cover * smoothstep(-AA, AA, min(edge.x, edge.y));
    if (inside > 0.0) {
      vec4 c = getFromColor(clamp(iuv, 0.0, 1.0));
      float diff = max(dot(n, LIGHT), 0.0);
      float spec = pow(max(reflect(-LIGHT, n).z, 0.0), 24.0);
      float k = shading * w;
      vec3 lit = c.rgb * mix(1.0, 0.25 + 0.85 * diff, k) + 0.35 * k * spec;
      ball = vec4(clamp(lit, 0.0, 1.0) * c.a, c.a) * inside;
    }
  }

  // the ball over the incoming image, premultiplied so transparent images do not bleed their color
  vec4 c = ball + bg * (1.0 - ball.a);
  return c.a > 0.0 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: Square blocks switch to the incoming image one after another along a rectangular spiral, from the border inward or from the center outward
// Tags: wipe, grid, blocks, spiral

// @param Number of blocks (columns, rows)
uniform ivec2 grid; // = ivec2(8, 6)
// @param Spiral from the top left corner inward; false spirals from the center outward, ending at the top left corner
uniform bool inward; // = true
// @param Turn clockwise; false turns counterclockwise
uniform bool clockwise; // = true
// @range(0, 0.5) Duration of each block's fade, as a fraction of the transition
uniform float smoothness; // = 0.05

// Position of the cell c (from the top left corner) along the spiral that runs clockwise
// from the top left corner of a n.x by n.y grid inward, from 0 to n.x * n.y - 1
float spiralIndex(vec2 c, vec2 n) {
  // ring: distance to the border, in cells
  float k = min(min(c.x, c.y), min(n.x - 1.0 - c.x, n.y - 1.0 - c.y));
  vec2 s = n - 2.0 * k;
  vec2 l = c - k;
  float before = n.x * n.y - s.x * s.y;
  float along;
  if (l.y == 0.0) along = l.x; // top side, to the right
  else if (l.x == s.x - 1.0) along = s.x - 1.0 + l.y; // right side, down
  else if (l.y == s.y - 1.0) along = 2.0 * s.x + s.y - 3.0 - l.x; // bottom side, to the left
  else along = 2.0 * (s.x - 1.0) + 2.0 * (s.y - 1.0) - l.y; // left side, up
  return before + along;
}

vec4 transition(vec2 uv) {
  vec2 n = max(vec2(grid), vec2(1.0));
  vec2 c = min(floor(vec2(uv.x, 1.0 - uv.y) * n), n - 1.0);
  // the transposed spiral turns the other way from the same corner; walking the spiral
  // outward reverses it too
  if (clockwise != inward) {
    c = c.yx;
    n = n.yx;
  }
  float count = n.x * n.y;
  float i = spiralIndex(c, n);
  if (!inward) i = count - 1.0 - i;

  // the blocks switch one after another, each one fading in over w blocks of time, the first
  // fade starting at 0 and the last ending at 1; without fade, block i switches at (i + 0.5) / count
  float w = max(smoothness, 0.0) * count;
  float o = max(0.5 * (1.0 - w), 0.0);
  float x = progress * (count - 1.0 + 2.0 * o + w) - i - o;
  float m = w > 0.0 ? smoothstep(0.0, w, x) : step(0.0, x);

  if (m <= 0.0) return getFromColor(uv);
  if (m >= 1.0) return getToColor(uv);
  vec4 a = getFromColor(uv);
  vec4 b = getToColor(uv);
  // mixed premultiplied, so transparent images do not bleed their color
  vec4 col = mix(vec4(a.rgb * a.a, a.a), vec4(b.rgb * b.a, b.a), m);
  return col.a > 0.0 ? vec4(col.rgb / col.a, col.a) : vec4(0.0);
}

// Author: gre
// License: MIT
// Description: A spiral arm winds out from the center and widens to reveal the incoming image
// Tags: shape, wipe, radial

#define PI 3.141592653589793

// @range(2, 8) Number of turns of the spiral
uniform float turns; // = 3.0
// @range(0, 0.5) Softness of the arm's edges
uniform float smoothness; // = 0.05
// @param Wind clockwise; false winds counterclockwise
uniform bool clockwise; // = true

// Coverage of the arm turn at position s (in turns along the spiral), d away from its middle line
float arm (float s, float d) {
  // The tip reaches the frame's corners at 60% of the transition, and the whole arm widens until the end
  float end = -0.5 + (turns + 0.5) / 0.6;
  float tip = mix(-0.5, end, progress);
  s = max(s, -0.5);
  float width = sqrt(clamp((tip - s) / max(end - s, 0.001), 0.0, 1.0));
  // Edge softness in arm widths, at least a pixel wide
  float e = smoothness + 0.005 * turns;
  return smoothstep(0.0, e, width * (0.5 + e) - d);
}

vec4 transition (vec2 uv) {
  // Square pixels, normalized so the frame's corners are at distance 1
  vec2 q = (uv - 0.5) * vec2(ratio, 1.0) / (0.5 * length(vec2(ratio, 1.0)));
  // Fraction of a turn, starting at the top
  float a = dot(q, q) < 1e-12 ? 0.0 : atan(q.x, q.y) / (2.0 * PI);
  a = fract(clockwise ? a : -a);
  // Radius in turns of the spiral, and the arm turn the point is in
  float w = length(q) * turns - a;
  float n = floor(w);
  float f = w - n;
  // The arm turns around it can overlap it near the edges
  float m = max(arm(n + a, abs(f - 0.5)), max(arm(n + 1.0 + a, 1.5 - f), arm(n - 1.0 + a, f + 0.5)));
  return mix(getFromColor(uv), getToColor(uv), m);
}

// Author: gre
// License: MIT
// Description: Splats of paint land one after another, each popping in with a spiky outline, flung droplets and a few drips running down, revealing the incoming image until they cover the frame
// Tags: paint, splash, organic, reveal

// @range(2, 10, 1) Number of splats across the frame
uniform float splats; // = 4.0
// @range(0, 1) How long the spikes around each splat are
uniform float spikiness; // = 0.6
// @range(0, 1) How many droplets are flung around each splat
uniform float droplets; // = 0.6
// @range(0, 1) How far the paint drips run down
uniform float drips; // = 0.5
// @range(0, 1) How dark and glossy the rim of the splats is
uniform float rim; // = 0.5
// @param Random seed for the splats
uniform float seed; // = 3.0

const float PI = 3.141592653589793;
const float SPIKES = 14.0;
// furthest reach of the shapes of a splat from its center, in cells. Splats are looked for in the 3x3 cells
// around a pixel, and the center of a splat 2 cells away is more than 1.35 cells away; on top of REACH, the
// smooth unions add up to 0.02 and the antialiasing 0.025 (at 10 splats), which leaves a margin of 0.055
// so that no splat is ever cut by the search
const float REACH = 1.25;

float hash12(vec2 v) {
  vec3 v3 = fract(vec3(v.xyx) * 0.1031);
  v3 += dot(v3, v3.yzx + 33.33);
  return fract((v3.x + v3.y) * v3.z);
}

// smooth noise around a splat, wrapping over a full turn (t in 0..1)
float turnNoise(float t, float n, vec2 key) {
  float x = t * n;
  float i = floor(x);
  float f = x - i;
  float a = hash12(key + vec2(mod(i, n), 61.0));
  float b = hash12(key + vec2(mod(i + 1.0, n), 61.0));
  return mix(a, b, f * f * (3.0 - 2.0 * f));
}

float smax(float a, float b, float k) {
  float h = max(k - abs(a - b), 0.0) / k;
  return max(a, b) + h * h * k * 0.25;
}

// signed distance (approximately, in cells, > 0 inside) to the splat of a grid cell
float splat(vec2 q, vec2 cell, vec2 key) {
  float t0 = 0.01 + 0.6 * hash12(key + vec2(3.0, 0.0));
  if (progress <= t0) return -1.0;
  vec2 c = cell + 0.5 + 0.3 * (vec2(hash12(key + vec2(5.0, 1.0)), hash12(key + vec2(9.0, 2.0))) - 0.5);
  vec2 d = q - c;
  float l = length(d);
  // nothing of the splat reaches this far (its distance there would be below -0.08 anyway)
  if (l > REACH + 0.1) return -1.0;
  float pop = clamp((progress - t0) / 0.08, 0.0, 1.0);
  pop = 1.0 - (1.0 - pop) * (1.0 - pop) * (1.0 - pop);
  float x = clamp((progress - t0) / (0.96 - t0), 0.0, 1.0);
  float grow = x * x * x;
  float r0 = 0.42 + 0.2 * hash12(key + vec2(11.0, 3.0));
  // the farthest corner of the cell is at most 0.65 * sqrt(2) ~ 0.92 cells away, and the body dents by 6% at most in the end
  float rc = mix(r0 * pop, 1.03, grow);

  float a = l > 1e-5 ? atan(d.y, d.x) / (2.0 * PI) + 0.5 : 0.0;
  float lumps = mix(0.3, 0.06, grow) * (turnNoise(a, 5.0, key) - 0.5) + mix(0.18, 0.06, grow) * (turnNoise(a, 19.0, key + 3.0) - 0.5);
  float f = rc * (1.0 + lumps) - l;

  // a spike in each slice of the turn: a ray that tapers from a wide base, the long ones ending in a bead;
  // the slices on both sides are looked at too, as their spikes can lean over the boundary
  float s = floor(a * SPIKES);
  float spike = -1.0;
  for (int k = -1; k <= 1; k++) {
    float sl = s + float(k);
    vec2 sk = key + vec2(mod(sl, SPIKES), 17.0);
    float h = hash12(sk);
    float w0 = (0.022 + 0.03 * hash12(sk + 1.5)) * pop;
    float len = max(min(spikiness * (0.06 + 0.6 * h * h) * pop, REACH - 1.2 * w0 - rc), 0.0);
    if (len > 0.0) {
      // short spikes are thin too, so that no spikiness leaves a clean body
      float w = w0 * min(len / 0.06, 1.0);
      float ang = (sl + 0.5 + 0.4 * (hash12(sk + 0.5) - 0.5)) / SPIKES * 2.0 * PI - PI;
      vec2 dir = vec2(cos(ang), sin(ang));
      float along = dot(d, dir);
      float across = abs(d.x * dir.y - d.y * dir.x);
      float u = clamp((along - rc) / len, 0.0, 1.0);
      float ray = min(w * (1.0 - 0.7 * u) - across, rc + len - along);
      if (h > 0.5) ray = max(ray, w * 1.2 - length(d - dir * (rc + len)));
      spike = max(spike, ray);
    }
  }
  f = smax(f, spike, 0.08);

  for (int j = 0; j < 5; j++) {
    vec2 dk = key + vec2(float(j), 29.0);
    float hr = hash12(dk + 0.5);
    float rad = (0.015 + 0.05 * hr * hr) * clamp(droplets * 5.0 - float(j), 0.0, 1.0) * pop;
    if (rad > 0.0) {
      float da = 2.0 * PI * hash12(dk);
      float dist = min(r0 + 0.08 + 0.5 * hash12(dk + 1.5), REACH - rad) * mix(0.5, 1.0, pop);
      f = max(f, rad - length(d - dist * vec2(cos(da), sin(da))));
    }
  }

  if (drips > 0.0) {
    float run = clamp((progress - t0 - 0.03) / 0.45, 0.0, 1.0);
    run = run * (2.0 - run);
    for (int j = 0; j < 2; j++) {
      vec2 dk = key + vec2(float(j), 43.0);
      float xo = (hash12(dk) - 0.5) * r0;
      float dw = (0.03 + 0.02 * hash12(dk + 0.5)) * pop;
      float top = sqrt(r0 * r0 - xo * xo) * pop;
      float bottom = min(top + drips * (0.25 + 0.75 * hash12(dk + 1.5)) * run, sqrt(REACH * REACH - xo * xo) - 1.6 * dw);
      float dx = abs(d.x - xo);
      float drip = min(dw - dx, min(d.y + bottom, -d.y));
      float tip = dw * 1.4 - length(vec2(dx, d.y + bottom + 0.2 * dw));
      f = smax(f, max(drip, tip), 0.05);
    }
  }
  return f;
}

vec4 transition(vec2 uv) {
  float n = max(1.0, floor(splats + 0.5));
  float cellSize = max(ratio, 1.0) / n;
  vec2 q = vec2(uv.x * ratio, uv.y) / cellSize; // in cells
  vec2 base = floor(q);
  vec2 sd = seed * vec2(7.0, 13.0);
  float f = -1.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 cell = base + vec2(float(i), float(j));
      f = max(f, splat(q, cell, cell + sd));
    }
  }
  float aa = 0.0025 / cellSize; // about a pixel or two, in cells
  float inside = smoothstep(-aa, aa, f);
  vec4 from = getFromColor(uv);
  vec4 to = getToColor(uv);
  float e = clamp(f / 0.045, 0.0, 1.0);
  float amount = rim * (1.0 - smoothstep(0.75, 1.0, progress));
  float dark = (1.0 - e) * (1.0 - e) * 0.6;
  float gloss = smoothstep(0.2, 0.4, e) * (1.0 - smoothstep(0.4, 0.7, e)) * 0.3;
  to.rgb = mix(to.rgb * (1.0 - dark * amount), vec3(1.0), gloss * amount * to.a);
  return mix(from, to, inside);
}

// Author: gre
// License: MIT
// Description: The frame becomes a split-flap board: in each cell the top half of the outgoing image flips down on a hinge across the middle, cell after cell, its back bringing the bottom half of the incoming image
// Tags: 3d, flip, grid

// @param Number of cells (columns, rows)
uniform ivec2 size; // = ivec2(8, 6)
// @range(0, 0.9) Delay of the last cell's flip, as a part of the transition
uniform float stagger; // = 0.6
// @range(0, 1) How much the order of the cells is shuffled, from a wave across the board to random
uniform float randomness; // = 0.3
// @range(1, 4, 1) Number of flaps that fall in each cell, the ones before the last showing other parts of the incoming image
uniform int flaps; // = 1
// @range(0, 0.05) Width of the gaps between the cells, as a part of the frame's shorter side (the hinges get half of it)
uniform float gap; // = 0.004
// @range(0, 1) Amount of perspective: the falling flaps grow as they come toward the viewer
uniform float perspective; // = 0.35
// @range(0, 1) How much the flaps darken as they turn away from the light, and the shadows they cast
uniform float shading; // = 0.4
// @color Color seen in the gaps between the cells
uniform vec4 background; // = vec4(0.0, 0.0, 0.0, 1.0)

const float PI = 3.141592653589793;
const float EDGE = 0.001;

float hash12(vec2 v) {
  vec3 v3 = fract(vec3(v.xyx) * 0.1031);
  v3 += dot(v3, v3.yzx + 33.33);
  return fract((v3.x + v3.y) * v3.z);
}

float cellTime(vec2 cell, vec2 grid) {
  float wave = (cell.x + 0.5 * (grid.y - 1.0 - cell.y)) / max(grid.x - 1.0 + 0.5 * (grid.y - 1.0), 1.0);
  float order = mix(wave, hash12(cell + 17.0), randomness);
  float delay = clamp(stagger, 0.0, 0.99);
  return clamp((progress - order * delay) / (1.0 - delay), 0.0, 1.0);
}

// the card on the front of the falling flap, at the cell's flip t
float flapIndex(float t, float n) {
  return min(floor(t * n), n - 1.0);
}

// the falling flap's angle, 0 upright to PI down: it starts gently and lands fast
float flapAngle(float t, float n) {
  float u = t * n - flapIndex(t, n);
  return PI * u * (0.3 + 0.7 * u);
}

// card i of a cell at the point lc of the card: the outgoing image first, the incoming one last,
// and in between the incoming image of another cell
vec4 card(float i, float n, vec2 cell, vec2 grid, vec2 lc) {
  if (i < 0.5) return getFromColor((cell + lc) / grid);
  vec2 src = cell;
  if (i < n - 0.5) src = floor(vec2(hash12(cell * 3.7 + i * 11.3), hash12(cell * 5.3 + i * 7.9 + 1.7)) * grid);
  return getToColor((src + lc) / grid);
}

// 1 inside a half card, 0 in the gaps: x across the card and f the distance from the hinge, in cell sizes
float cardMask(float x, float f, vec2 cellSize, float g) {
  if (g <= 0.0) return 1.0;
  float e = EDGE * min(1.0, g / max(gap, 1e-4));
  // the gap at the hinge is half as wide as the one between the cells
  float d = min(min(x, 1.0 - x) * cellSize.x, min(2.0 * f, 0.5 - f) * cellSize.y);
  return smoothstep(0.5 * g - e, 0.5 * g + e, d);
}

vec4 transition (vec2 uv) {
  vec2 grid = max(vec2(size), 1.0);
  float n = max(float(flaps), 1.0);
  vec2 cellSize = vec2(ratio, 1.0) / grid / min(ratio, 1.0);
  vec2 cell = floor(uv * grid);
  vec2 l = uv * grid - cell;
  float g = gap * smoothstep(0.0, 0.12, progress) * (1.0 - smoothstep(0.88, 1.0, progress));
  // w: height above the hinge, in cell heights
  float w = l.y - 0.5;
  bool upper = w >= 0.0;

  // the board behind the falling flaps: the top half of the next card once the flap has left it,
  // the bottom half of the current card until the flap has landed on it
  float t = cellTime(cell, grid);
  float k = flapIndex(t, n);
  float a = flapAngle(t, n);
  bool started = t * n > k;
  bool landed = t >= 1.0;
  vec4 color = card(k + (upper ? (started ? 1.0 : 0.0) : (landed ? 1.0 : 0.0)), n, cell, grid, l);
  if (started && !landed) color.rgb *= 1.0 - 0.45 * shading * max(upper ? cos(a) : -cos(a), 0.0);
  color = mix(background, color, cardMask(l.x, abs(w), cellSize, g));

  // the falling flaps of this cell and of its neighbors, which grow beyond their cells as they come closer
  float nearest = -1.0;
  for (int d = -1; d <= 1; d++) {
    vec2 nc = cell + vec2(float(d), 0.0);
    if (nc.x < 0.0 || nc.x > grid.x - 1.0) continue;
    float nt = d == 0 ? t : cellTime(nc, grid);
    float na = d == 0 ? a : flapAngle(nt, n);
    float fc = cos(na);
    float fs = sin(na);
    // a point at distance f from the hinge is at height f * fc and depth f * fs, nearer points look wider
    if (abs(fc) < 1e-5 || (w >= 0.0) != (fc > 0.0)) continue;
    float f = w / fc;
    if (f > 0.5) continue;
    float z = f * fs;
    if (z <= nearest) continue;
    float lx = 0.5 + (l.x - float(d) - 0.5) * (1.0 - perspective * z);
    if (lx < 0.0 || lx > 1.0) continue;
    bool front = fc > 0.0;
    vec2 lc = vec2(lx, front ? 0.5 + f : 0.5 - f);
    float m = cardMask(lx, f, cellSize, g);
    if (m <= 0.0) continue;
    vec4 img = card(flapIndex(nt, n) + (front ? 0.0 : 1.0), n, nc, grid, lc);
    float lambert = (front ? 0.92 * fc - 0.4 * fs : 0.4 * fs - 0.92 * fc) / 0.92;
    img.rgb *= mix(1.0 - shading, 1.0, clamp(lambert, 0.0, 1.0));
    color = mix(color, img, m);
    nearest = z;
  }
  return color;
}

